Here is the Terraform HCL program that configures a query log with Route 53 resources:

```hcl
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for Route 53 query logging
resource "aws_iam_role" "route53_query_logging" {
  name        = "route53-query-logging-role"
  description = "Role for Route 53 query logging"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
      }
    ]
  })
}

# Attach a policy to the IAM role that allows logging to CloudWatch
resource "aws_iam_role_policy" "route53_query_logging_policy" {
  name   = "route53-query-logging-policy"
  role   = aws_iam_role.route53_query_logging.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Create an IAM role for Route 53 to assume
resource "aws_iam_role" "route53_assume_role" {
  name        = "route53-assume-role"
  description = "Role for Route 53 to assume"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
      }
    ]
  })
}

# Create a Route 53 hosted zone
resource "aws_route53_zone" "primary" {
  name = "example.com"
}

# Create a CloudWatch log group
resource "aws_cloudwatch_log_group" "aws_route53_example_com" {
  name              = "aws_route53_example_com"
  retention_in_days = 14
}

# Create a CloudWatch log resource policy
resource "aws_cloudwatch_log_resource_policy" "route53_query_logging_policy" {
  policy_name = "route53-query-logging-policy"
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        LogGroupName = "${aws_cloudwatch_log_group.aws_route53_example_com.name}:*"
        Principal    = {
          Service = "route53.amazonaws.com"
        }
        Action      = "logs:PutLogEvents"
        Condition   = {
          ArnLike = {
            "aws:SourceArn" = aws_route53_zone.primary.id
          }
        }
      }
    ]
  })
  depends_on = [aws_cloudwatch_log_group.aws_route53_example_com]
}
```

Note that this Terraform program creates IAM roles, attaches policies to those roles, creates a Route 53 hosted zone, a CloudWatch log group, and a CloudWatch log resource policy. The log resource policy is designed to allow Route 53 to put log events into the specified log group. Make sure to replace "example.com" with your actual domain name.

