Here is the Terraform program that configures a Route 53 record with an Elastic Load Balancer resource.

**Configuration**

This configuration assumes you have already set up an AWS provider. The `aws` block is configured to use the `us-west-2` region.

```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an Elastic Load Balancer
resource "aws_elb" "main" {
  name            = "main-elb"
  subnets         = [aws_subnet.primary.id]
  security_groups = [aws_security_group.allow_http.id]

  access_logs {
    bucket        = aws_s3_bucket.elb_logs.id
    bucket_prefix = "elb-logs"
  }
}

# Create a Route 53 zone
resource "aws_route53_zone" "primary" {
  name = "example.com"
}

# Create an A record for the Elastic Load Balancer
resource "aws_route53_record" "main" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = "main.example.com"
  type    = "A"
  alias {
    name                   = aws_elb.main.dns_name
    zone_id                = aws_elb.main.zone_id
    evaluate_target_health = false
  }
}

# Create an S3 bucket for ELB logs
resource "aws_s3_bucket" "elb_logs" {
  bucket = "example-elb-logs"
}

# Create a security group to allow HTTP traffic
resource "aws_security_group" "allow_http" {
  name        = "allow_http"
  description = "Allow HTTP traffic"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a subnet
resource "aws_subnet" "primary" {
  cidr_block = "10.0.1.0/24"
  vpc_id     = aws_vpc.primary.id
}

# Create a VPC
resource "aws_vpc" "primary" {
  cidr_block = "10.0.0.0/16"
}
```

This configuration defines the necessary resources to create an Elastic Load Balancer, Route 53 zone, A record, S3 bucket, security group, and subnet. The ELB and Route 53 record are configured to use the `us-west-2` region.

Note that you will need to replace `example.com` with your own domain name in the `aws_route53_zone` resource.

