**Description:**

The Terraform program will create two Elastic Beanstalk environments named `dev` and `prod` that use the same Elastic Beanstalk application named `my_application`. The environments will be deployed in the `us-west-2` region. Two IAM roles and instance profiles will be created to manage the Elastic Beanstalk environments. The IAM roles and instance profiles will be named `eb_ec2_role` and `eb_ec2_profile` respectively.

**Terraform HCL Program:**
```hcl
provider "aws" {
  region = "us-west-2"
}

# Create Elastic Beanstalk Application
resource "aws_ebs_application" "my_application" {
  name = "my_application"
}

# Create IAM Role and Instance Profile
resource "aws_iam_role" "eb_ec2_role" {
  name        = "eb_ec2_role"
  description = "Elastic Beanstalk EC2 Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# Create Elastic Beanstalk Environment 1 (dev)
resource "aws_ebs_environment" "dev" {
  name                = "dev"
  application         = aws_ebs_application.my_application.name
  solution_stack_name = "64bit Amazon Linux 2 v2.1.0 running Docker"

  # Attach IAM Role and Instance Profile
  iam_role_name  = aws_iam_role.eb_ec2_role.name
  instance_profile_name = aws_iam_instance_profile.eb_ec2_profile.name

  tags = {
    Environment = "dev"
  }
}

# Create Elastic Beanstalk Environment 2 (prod)
resource "aws_ebs_environment" "prod" {
  name                = "prod"
  application         = aws_ebs_application.my_application.name
  solution_stack_name = "64bit Amazon Linux 2 v2.1.0 running Docker"

  # Attach IAM Role and Instance Profile
  iam_role_name  = aws_iam_role.eb_ec2_role.name
  instance_profile_name = aws_iam_instance_profile.eb_ec2_profile.name

  tags = {
    Environment = "prod"
  }
}
```
This configuration creates two Elastic Beanstalk environments, `dev` and `prod`, that use the same application, `my_application`. The IAM role and instance profile, `eb_ec2_role` and `eb_ec2_profile`, are used by both environments.

