Here is a Terraform HCL configuration that meets the requirements:
```
# Configure the AWS Provider
provider "aws" {
  region = "us-east-1"
}

# Create IAM Role
resource "aws_iam_role" "eb_ec2_role" {
  name        = "eb_ec2_role"
  description = "Elastic Beanstalk EC2 Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create IAM Instance Profile
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name        = "eb_ec2_profile"
  description = "Elastic Beanstalk EC2 Profile"

  role = aws_iam_role.eb_ec2_role.name
}

# Create Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "batch_job_app" {
  name        = "batch_job_app"
  description = "Elastic Beanstalk Application for batch processing jobs"
}

# Create Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "batch_job_env" {
  name        = "batch_job_env"
  application = aws_elastic_beanstalk_application.batch_job_app.name
  version_label = var.version

  # Define environment tier
  setting {
    namespace = "aws:ec2:instance"
    name      = "InstanceType"
    value     = "t2.micro"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "Worker"
  }
}

# Create S3 Bucket
resource "aws_s3_bucket" "sampleapril26426" {
  bucket = "sampleapril26426"
  acl    = "private"
}

# Create S3 Object
resource "aws_s3_bucket_object" "examplebucket_object" {
  bucket = aws_s3_bucket.sampleapril26426.id
  key    = "examplebucket_object.txt"
  source = "/path/to/examplebucket_object.txt"
  etag   = "d41d8cd98f00b204e9800998ecf8427e"
}

# Create SQS Queue
resource "aws_sqs_queue" "batch_job_queue" {
  name = "batch_job_queue"
}

# Create IAM Policy for SQS Queue
resource "aws_iam_policy" "batch_job_policy" {
  name        = "batch_job_policy"
  description = "Policy for batch job queue"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sqs:SendMessage"
        Effect = "Allow"
        Resource = aws_sqs_queue.batch_job_queue.arn
      }
    ]
  })
}

# Attach policy to IAM Role
resource "aws_iam_role_policy_attachment" "batch_job_attach" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = aws_iam_policy.batch_job_policy.arn
}

variable "version" {
  type        = string
  default     = "version"
}
```
This configuration creates an Elastic Beanstalk worker environment for running batch processing jobs. It includes:

* IAM Role and Instance Profile
* Elastic Beanstalk Application and Environment
* S3 Bucket and Object
* SQS Queue and IAM Policy for SQS
* IAM Role Policy Attachment for SQS

Note that this configuration assumes you have the AWS Provider configured in your Terraform environment.

