```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create a unique name for the S3 bucket
resource "random_string" "suffix" {
  length = 8
  special = false
}

# Create an IAM role for Elastic Beanstalk
resource "aws_iam_role" "eb_ec2_role" {
  name               = "eb_ec2_role"
  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Effect": "Allow",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      }
    }
  ]
}
EOF
}

# Create an IAM instance profile for Elastic Beanstalk
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# Create an IAM policy for Elastic Beanstalk
resource "aws_iam_policy" "eb_policy" {
  name        = "eb_policy"
  description = "Policy for Elastic Beanstalk"

  policy      = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "s3:GetObject",
        "s3:PutObject",
        "s3:DeleteObject"
      ],
      "Effect": "Allow",
      "Resource": "arn:aws:s3:::${aws_s3_bucket.eb_bucket.id}/*"
    }
  ]
}
EOF
}

# Create an IAM policy attachment for Elastic Beanstalk
resource "aws_iam_policy_attachment" "eb_attach" {
  name       = "eb_attach"
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = aws_iam_policy.eb_policy.arn
}

# Create an S3 bucket for Elastic Beanstalk
resource "aws_s3_bucket" "eb_bucket" {
  bucket = "myapp-bucket-${random_string.suffix.result}"
  acl    = "private"
}

# Create an S3 object in the Elastic Beanstalk bucket
resource "aws_s3_object" "examplebucket_object" {
  bucket = aws_s3_bucket.eb_bucket.id
  key    = "examplebucket_object.txt"
  content = "This is a test object"
}

# Create an Elastic Beanstalk application
