  }
}

# Create a Route 53 zone
resource "aws_route53_zone" "main" {
  name = "example.com"
}

# Create a Route 53 record set for the Elastic Beanstalk environment
resource "aws_route53_record" "eb_env_record" {
  zone_id = aws_route53_zone.main.id
  name    = aws_elastic_beanstalk_environment.eb_env.name
  type    = "CNAME"
  alias {
    name                   = aws_elastic_beanstalk_environment.eb_env.domain_name
    zone_id                = aws_elastic_beanstalk_environment.eb_env.zone_name
    evaluate_target_health = false
  }
}

output "Route 53 Zone ID" {
  value = aws_route53_zone.main.id
}

output "Elastic Beanstalk Environment URL" {
