Here's the Terraform HCL configuration for Blue/Green deployment with Route53 resources to navigate traffic between Elastic Beanstalk Environments.

```hcl
# Configure the AWS Provider
provider "aws" {
  region                  = "us-west-2"
  shared_credentials_file = "~/.aws/credentials"
  profile                 = "default"
}

# Create an Elastic Beanstalk Environment for "blue"
resource "aws_eb_environment" "blue" {
  name = "blue-env"
}

# Create an Elastic Beanstalk Environment for "green"
resource "aws_eb_environment" "green" {
  name = "green-env"
}

# Create a Route53 Hosted Zone for the Elastic Beanstalk environment
resource "aws_route53_zone" "example_zone" {
  name = "example.com"
}

# Create a Route53 Record Set for the "blue" environment
resource "aws_route53_record" "blue_record" {
  zone_id = aws_route53_zone.example_zone.zone_id
  name    = "blue.example.com"
  type    = "A"
  alias {
    name                   = aws_eb_environment.blue.name
    zone_id                = aws_eb_environment.blue.zone_name
    evaluate_target_health = false
  }
}

# Create a Route53 Record Set for the "green" environment
resource "aws_route53_record" "green_record" {
  zone_id = aws_route53_zone.example_zone.zone_id
  name    = "green.example.com"
  type    = "A"
  alias {
    name                   = aws_eb_environment.green.name
    zone_id                = aws_eb_environment.green.zone_name
    evaluate_target_health = false
  }
}

# Create a Route53 Weighted Routing Policy
resource "aws_route53_health_check" "health_check" {
  name                = "example-health-check"
  port                = 80
  type                = "HTTP"
  resource_path       = "/"
  failure_threshold   = 3
}

resource "aws_route53_traffic_policy" "traffic_policy" {
  name      = "example-traffic-policy"
  depends_on = [aws_route53_record.blue_record, aws_route53_record.green_record]
}

resource "aws_route53_traffic_policy_instance" "blue_instance" {
  name      = "example-blue-instance"
  policy_id = aws_route53_traffic_policy.traffic_policy.id
  traffic_policy_configuration {
    traffic_percent = 100
    health_check_id = aws_route53_health_check.health_check.id
  }
}

resource "aws_route53_traffic_policy_instance" "green_instance" {
  name      = "example-green-instance"
  policy_id = aws_route53_traffic_policy.traffic_policy.id
  traffic_policy_configuration {
    traffic_percent = 0
    health_check_id = aws_route53_health_check.health_check.id
  }
}

resource "aws_route53_traffic_policy_instance" "blue_green_instance" {
  name      = "example-blue-green-instance"
  policy_id = aws_route53_traffic_policy.traffic_policy.id
  traffic_policy_configuration {
    traffic_percent = 100
    health_check_id = aws_route53_health_check.health_check.id
  }
}
```

This configuration includes:

1.  AWS Provider Configuration
2.  Elastic Beanstalk Environment creation for "blue" and "green"
3.  Route53 Hosted Zone creation for the Elastic Beanstalk environment
4.  Route53 Record Set creation for the "blue" and "green" environments
5.  Route53 Weighted Routing Policy creation
6.  Route53 Traffic Policy and instances for the weighted routing policy

The weighted routing policy navigates traffic between the "blue" and "green" environments, allocating 100% traffic to the "blue" environment initially, and gradually shifting traffic to the "green" environment. This configuration assumes that the Elastic Beanstalk environments are already created, and that the Route53 Hosted Zone exists.

