```hcl
# Configure the AWS Provider
provider "aws" {
  region = var.region
}

# Define the Elastic Beanstalk Environment for us_west
resource "aws_elastic_beanstalk_environment" "us_west" {
  name        = "us_west-env"
  application = aws_elastic_beanstalk_application.us_west.name
  version_label = "us_west-version"
}

# Define the Elastic Beanstalk Environment for eu_central
resource "aws_elastic_beanstalk_environment" "eu_central" {
  name        = "eu_central-env"
  application = aws_elastic_beanstalk_application.eu_central.name
  version_label = "eu_central-version"
}

# Define the Elastic Beanstalk Application for us_west
resource "aws_elastic_beanstalk_application" "us_west" {
  name = "us_west-app"
}

# Define the Elastic Beanstalk Application for eu_central
resource "aws_elastic_beanstalk_application" "eu_central" {
  name = "eu_central-app"
}

# Define the Route53 Zone
resource "aws_route53_zone" "example" {
  name = "example.com"
}

# Define the Route53 Record Set for us_west
resource "aws_route53_record" "us_west" {
  zone_id = aws_route53_zone.example.id
  name    = "us-west.example.com"
  type    = "A"
  alias {
    name                   = aws_elastic_beanstalk_environment.us_west.dns_alias
    zone_id                = aws_elastic_beanstalk_environment.us_west.dns_zone_id
    evaluate_target_health = false
  }
}

# Define the Route53 Record Set for eu_central
resource "aws_route53_record" "eu_central" {
  zone_id = aws_route53_zone.example.id
  name    = "eu-central.example.com"
  type    = "A"
  alias {
    name                   = aws_elastic_beanstalk_environment.eu_central.dns_alias
    zone_id                = aws_elastic_beanstalk_environment.eu_central.dns_zone_id
    evaluate_target_health = false
  }
}

# Define the Route53 Geolocation Resource Record Set
resource "aws_route53_geolocation_resource_record_set" "us_west" {
  name            = "_geodb.us_west.example.com"
  type            = "SRV"
  zone_id         = aws_route53_zone.example.id
  latency_preference = "us"
  alias {
    name                   = aws_elastic_beanstalk_environment.us_west.dns_alias
    zone_id                = aws_elastic_beanstalk_environment.us_west.dns_zone_id
    evaluate_target_health = false
  }
}

# Define the Route53 Geolocation Resource Record Set
resource "aws_route53_geolocation_resource_record_set" "eu_central" {
  name            = "_geodb.eu-central.example.com"
  type            = "SRV"
  zone_id         = aws_route53_zone.example.id
  latency_preference = "eu"
  alias {
    name                   = aws_elastic_beanstalk_environment.eu_central.dns_alias
    zone_id                = aws_elastic_beanstalk_environment.eu_central.dns_zone_id
    evaluate_target_health = false
  }
}

# Define the variable for region
variable "region" {
  type        = string
  default     = "us-west-2"
}

# Define the variable for environment names
variable "environment_names" {
  type        = list(string)
  default     = ["us_west", "eu_central"]
}

# Define the variable for application names
variable "application_names" {
  type        = list(string)
  default     = ["us_west-app", "eu_central-app"]
}
```
This configuration will create two Elastic Beanstalk environments, `us_west` and `eu_central`, in their respective regions. It will also create two Route53 record sets, one for each environment, that navigate traffic to the closest environment based on geolocation.

Note that you will need to replace `example.com` with your own domain name and update the `region` variable to the desired region.

