# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Define the IAM Role for Elastic Beanstalk
resource "aws_iam_role" "eb_ec2_role" {
  name        = "eb_ec2_role"
  description = "Elastic Beanstalk EC2 Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create an instance profile for the IAM Role
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# Create an IAM policy for Elastic Beanstalk
resource "aws_iam_policy" "eb_policy" {
  name        = "eb_policy"
  description = "Elastic Beanstalk Policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Resource = "arn:aws:s3:::my-bucket/*"
      },
      {
        Action = "s3:PutObject"
        Effect = "Allow"
        Resource = "arn:aws:s3:::my-bucket/*"
      }
    ]
  })
}

# Attach the IAM policy to the instance profile
resource "aws_iam_policy_attachment" "attach_policy" {
  name       = "attach_policy"
  policy_arn = aws_iam_policy.eb_policy.arn
  roles      = [aws_iam_role.eb_ec2_role.name]
}

# Create the Elastic Beanstalk environment
resource "aws_elastic_beanstalk_environment" "my_environment" {
  name        = "my_environment"
  application_name = "my_application"
  description   = "My Elastic Beanstalk Environment"

  setting {
    namespace = "aws:ec2:instance"
    name      = "InstanceType"
    value     = "t2.micro"
  }

  setting {
    namespace = "aws:ec2:instance"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }
}

# Create the Elastic Beanstalk application
resource "aws_elastic_beanstalk_application" "my_application" {
  name = "my_application"
}
```
Note that I've assumed that you have a bucket named `my-bucket` in your S3 account, and that you want to grant the Elastic Beanstalk environment access to it. You'll need to update the bucket name and policy to match your specific requirements. Also, I've used the `t2.micro` instance type for the Elastic Beanstalk environment, but you can adjust this to suit your needs.

