**Description of the Terraform Program:**

The Terraform program will create an AWS Elastic Beanstalk application with the following features:

*   A new Elastic Beanstalk application named "my-eb-app" in the specified region (default: us-west-2).
*   A new Elastic Beanstalk environment named "my-eb-env" with a specified instance type and environment type (default: load-balanced environment with 2 instances).
*   A new Elastic Beanstalk environment configuration with a specified application version.
*   An IAM role for the Elastic Beanstalk environment with necessary permissions.
*   A valid provider configuration for AWS.

**Terraform HCL Program:**

```terraform
# Provider Configuration
provider "aws" {
  region = "us-west-2"
}

# Variables
variable "instance_type" {
  type        = string
  default     = "t2.micro"
  description = "The instance type for the Elastic Beanstalk environment"
}

variable "application_name" {
  type        = string
  default     = "my-eb-app"
  description = "The name of the Elastic Beanstalk application"
}

variable "environment_name" {
  type        = string
  default     = "my-eb-env"
  description = "The name of the Elastic Beanstalk environment"
}

variable "environment_type" {
  type        = string
  default     = "LoadBalanced"
  description = "The type of the Elastic Beanstalk environment"
}

variable "application_version" {
  type        = string
  default     = "my-eb-app-version"
  description = "The version of the Elastic Beanstalk application"
}

# IAM Role for Elastic Beanstalk
resource "aws_iam_role" "elastic_beanstalk_role" {
  name        = "${var.application_name}-elastic-beanstalk-role"
  description = "The IAM role for the Elastic Beanstalk environment"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      },
    ]
  })
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "my_app" {
  name        = var.application_name
  description = "The Elastic Beanstalk application"
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "my_env" {
  name        = var.environment_name
  application = aws_elastic_beanstalk_application.my_app.name
  solution_stack_name = "64bit Amazon Linux 2018.03 v2.12.4 running Tomcat 8"

  tier {
    name     = "WebServer"
    instance_type = var.instance_type
  }

  setting {
    namespace = "aws:ec2:instance"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = var.environment_type
  }
}

# Elastic Beanstalk Environment Configuration
resource "aws_elastic_beanstalk_environment_config" "my_env_config" {
  application = aws_elastic_beanstalk_application.my_app.name
  environment_name = aws_elastic_beanstalk_environment.my_env.name
  application_version = var.application_version
}

output "eb_app_name" {
  value = aws_elastic_beanstalk_application.my_app.name
}

output "eb_env_name" {
  value = aws_elastic_beanstalk_environment.my_env.name
}
```

