  name                = "example"
  application         = "example"
  description         = "Elastic Beanstalk Environment"
  tier                 = "WebServer"
  platformArn          = "arn:aws:elasticbeanstalk::us-west-2::platform/go"
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = "vpc-12345678"
  }
  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = "subnet-12345678,subnet-23456789"
  }
  role             = aws_iam_role.elastic_beanstalk_role.arn
}

# Create an Elastic Beanstalk environment configuration
