    name      = "VPCId"
    value     = "vpc-12345678"
  }
  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = "subnet-12345678,subnet-23456789"
  }
  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }
}

# Output the Elastic Beanstalk environment URL
output "beanstalk_environment_url" {
  value = aws_elastic_beanstalk_environment.example_environment_url
}

