```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create a new IAM role for the CodeBuild project
resource "aws_iam_role" "codebuild_role" {
  name               = "CodeBuildRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the AWSCodeBuildServiceRole managed policy to the IAM role
resource "aws_iam_role_policy_attachment" "codebuild_attach" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildServiceRole"
}

# Create a new IAM policy for the GitHub source
resource "aws_iam_policy" "github_policy" {
  name        = "GitHubPolicy"
  description = "Policy for CodeBuild to access GitHub source"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "codecommit:GetCommit",
          "codecommit:GetRepository",
          "codecommit:GetBlob",
          "codecommit:GetObject",
        ]
        Effect = "Allow"
        Resource = [
          "arn:aws:codecommit:${aws_region}:${aws_caller_identity.account_id}/example-repo",
          "arn:aws:codecommit:${aws_region}:${aws_caller_identity.account_id}/example-repo/*",
        ]
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "github_attach" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.github_policy.arn
}

# Create a new CodeBuild project
resource "aws_codebuild_project" "example" {
  name         = "example-codebuild-project"
  description  = "An example CodeBuild project"
  source {
    type     = "GITHUB"
    location = "https://github.com/username/repository.git"
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/docker:18.09.0"
    type         = "Linux"
  }

  service_role = aws_iam_role.codebuild_role.arn
}
```

