Here is a Terraform program that creates an AWS CodeBuild project with an example IAM role, GitHub source, environment variables, and a cache:

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create a GitHub repository
resource "aws_codebuild_project" "example" {
  name        = "example-codebuild-project"
  description = "Example CodeBuild project"
  build_timeout = 5
  queue_timeout = 2

  # Specify the IAM role
  service_role = aws_iam_role.codebuild_service_role.arn

  # Specify the source as a GitHub repository
  source {
    type     = "GITHUB"
    location = "https://github.com/username/repository.git"
    oauth_token = aws_secretsmanager_secret_version.github_oauth_token.secret_string
  }

  # Specify environment variables
  environment {
    type = "LINUX_CONTAINER"
    compute_type = "BUILD_GENERAL1_SMALL"
    image = "aws/codebuild/dotnetcore:3.20.0"
    environment_variables {
      name  = "EXAMPLE_VAR"
      value = "example-value"
    }
  }

  # Specify the cache
  cache {
    type     = "S3"
    location = aws_s3_bucket.codebuild_cache_bucket.bucket
  }
}

# Create an IAM role for CodeBuild
resource "aws_iam_role" "codebuild_service_role" {
  name        = "codebuild-service-role"
  description = "CodeBuild service role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for CodeBuild
resource "aws_iam_policy" "codebuild_policy" {
  name        = "codebuild-policy"
  description = "CodeBuild policy"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "codebuild:ImportSource",
          "codebuild:ExportArtifact",
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:CreateKeyPair",
          "ec2:DeleteKeyPair"
        ]
        Resource = "*"
        Effect = "Allow"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "codebuild_attach" {
  role       = aws_iam_role.codebuild_service_role.name
  policy_arn = aws_iam_policy.codebuild_policy.arn
}

# Create a GitHub OAuth token secret
resource "aws_secretsmanager_secret" "github_oauth_token" {
  name = "github-oauth-token"
}

resource "aws_secretsmanager_secret_version" "github_oauth_token" {
  secret_id = aws_secretsmanager_secret.github_oauth_token.id
  secret_string = "your-github-oauth-token"
}

# Create an S3 bucket for the cache
resource "aws_s3_bucket" "codebuild_cache_bucket" {
  bucket = "codebuild-cache-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }
}
```

Note that you should replace `https://github.com/username/repository.git` with your actual GitHub repository URL, and `your-github-oauth-token` with your actual GitHub OAuth token.

Also, make sure to set the `region` variable at the top of the configuration to the region where you want to create your AWS resources.

This configuration creates a CodeBuild project with an example IAM role, GitHub source, environment variables, and a cache. The IAM role has a policy attached that grants necessary permissions to CodeBuild. The GitHub OAuth token is stored in Secrets Manager as a secret, and the cache is stored in an S3 bucket.

