Here is a Terraform program that creates an AWS CodeBuild project with an example IAM role, a GitHub source, an artifact, and a cache.

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM Role for the CodeBuild Project
resource "aws_iam_role" "codebuild_role" {
  name               = "codebuild-example-role"
  description        = "CodeBuild service role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM Policy for the CodeBuild Role
resource "aws_iam_policy" "codebuild_policy" {
  name        = "codebuild-example-policy"
  description = "Policy for CodeBuild"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = "arn:aws:logs:*:*:*"
      },
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        Resource = "arn:aws:s3:::example-bucket/*"
      },
    ]
  })
}

# Attach the IAM Policy to the CodeBuild Role
resource "aws_iam_role_policy_attachment" "codebuild_attach" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_policy.arn
}

# Create the CodeBuild Project
resource "aws_codebuild_project" "example" {
  name          = "example-codebuild-project"
  description   = "Example CodeBuild Project"
  build_timeout = 5

  source {
    type     = "GITHUB"
    location = "https://github.com/username/repository.git"
  }

  artifacts {
    type = "S3"
    paths = ["**"]
    name  = "example-artifact"
  }

  cache {
    type     = "S3"
    location = "arn:aws:s3:::example-bucket/codebuild-cache/"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/docker:18.09.0"
    type         = "LINUX_CONTAINER"
  }
}
```
This Terraform configuration includes an IAM role for the CodeBuild project, an IAM policy for the role, an IAM policy attachment, and a CodeBuild project with a GitHub source, artifact, and cache. You can customize the settings as needed for your specific use case.

