```hcl
# Define the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for CodeBuild
resource "aws_iam_role" "example_codebuild_role" {
  name        = "example-codebuild-role"
  description = "CodeBuild service role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for CodeBuild
resource "aws_iam_policy" "example_codebuild_policy" {
  name        = "example-codebuild-policy"
  description = "Policy for CodeBuild"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = "*"
        Effect    = "Allow"
      },
      {
        Action = [
          "codecommit:GetRepository",
          "codecommit:GetBlob",
          "codecommit:GetObject",
        ]
        Resource = "arn:aws:codecommit:*:*:example-repo"
        Effect    = "Allow"
      },
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "example_codebuild_attach" {
  role       = aws_iam_role.example_codebuild_role.name
  policy_arn = aws_iam_policy.example_codebuild_policy.arn
}

# Create a GitHub source
resource "aws_codebuild_project_source" "example_source" {
  version = "1.0"

  type             = "GITHUB"
  location         = "https://github.com/your-username/your-repo-name.git"
  git_clone_type   = "NO_SOURCE"
  buildspec       = file("${path.module}/example_buildspec.yaml")
}

# Create a CodeBuild project
resource "aws_codebuild_project" "example_codebuild_project" {
  name         = "example-codebuild-project"
  source        = aws_codebuild_project_source.example_source.id
  service_role  = aws_iam_role.example_codebuild_role.arn
  environment   = {
    compute_type                = "BUILD_GENERAL1_SMALL"
    type                        = " LINUX_CONTAINER"
    image                       = "aws/codebuild/standard:5.0"
  }
  logs_config = {
    cloudwatch_logs_group_name  = "example-codebuild-logs"
    cloudwatch_logs_role_arn    = aws_iam_role.example_codebuild_role.arn
    group_name                  = "example-codebuild-group"
    stream_name                 = "example-codebuild-stream"
  }
}

# Define a variable for the GITHUB repo URL
variable "github_repo_url" {
  type        = string
  default     = "https://github.com/your-username/your-repo-name.git"
}

# Define a variable for the buildspec path
variable "buildspec_path" {
  type        = string
  default     = "${path.module}/example_buildspec.yaml"
}
```

Note that you should replace `"https://github.com/your-username/your-repo-name.git"` with your actual GitHub repository URL, and replace `"${path.module}/example_buildspec.yaml"` with the path to your buildspec file. 

Also note that you need to have AWS credentials configured on your machine to be able to run this code.

