Here is a Terraform configuration that creates an AWS CodeBuild project with an example IAM role and secondary artifacts:

**main.tf**
```terraform
# Provider configuration
provider "aws" {
  region = "us-west-2"
}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_role" {
  name               = "CodeBuildRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for CodeBuild
resource "aws_iam_policy" "codebuild_policy" {
  name        = "CodeBuildPolicy"
  description = "Policy for CodeBuild"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutEvent",
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
        ]
        Effect = "Allow"
        Resource = "arn:aws:s3:::example-bucket/*"
      },
    ]
  })
}

# IAM Policy Attachment
resource "aws_iam_role_policy_attachment" "codebuild_attach" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_policy.arn
}

# CodeBuild Project
resource "aws_codebuild_project" "example_project" {
  name         = "ExampleProject"
  description  = "Example CodeBuild project"
  source_type  = "S3"
  source_config {
    location = "s3://example-bucket/codebuild-source/"
  }

  artifacts {
    type = "S3"
    location = "s3://example-bucket/codebuild-artifacts/"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image          = "aws/codebuild/docker:18.09.0"
    type           = "LINUX_CONTAINER"
  }

  service_role = aws_iam_role.codebuild_role.arn
}

# Output the CodeBuild project ARN
output "codebuild_project_arn" {
  value = aws_codebuild_project.example_project.arn
}
```
This configuration creates:

* An IAM role for CodeBuild with an assume role policy that allows CodeBuild to assume the role.
* An IAM policy for CodeBuild that allows it to create log groups and streams, put events, and get/put objects in a specified S3 bucket.
* An IAM policy attachment that attaches the policy to the CodeBuild role.
* A CodeBuild project with an S3 source and an S3 artifact location, and an environment configured for Docker.
* Outputs the ARN of the CodeBuild project.

Note that you should replace `example-bucket` with your actual S3 bucket name.

