Here is the Terraform program that defines an AWS Lex Bot:

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
  version = "4.27.0"
}

# Define a variable for the Lex Bot name
variable "lex_bot_name" {
  type        = string
  default     = "my_lex_bot"
}

# Define a variable for the Lex Bot alias name
variable "lex_bot_alias_name" {
  type        = string
  default     = "my_lex_bot_alias"
}

# Create an IAM role for Lex
resource "aws_iam_role" "lex_role" {
  name        = "lex-role-${var.lex_bot_name}"
  description = "Role for Lex bot"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for Lex
resource "aws_iam_policy" "lex_policy" {
  name        = "lex-policy-${var.lex_bot_name}"
  description = "Policy for Lex bot"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "lex:CreateSession"
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "lex_attach" {
  role       = aws_iam_role.lex_role.name
  policy_arn = aws_iam_policy.lex_policy.arn
}

# Create the Lex Bot
resource "aws_lex_bot" "lex_bot" {
  name      = var.lex_bot_name
  role_arn  = aws_iam_role.lex_role.arn
  alias_name = var.lex_bot_alias_name

  idle_session_ttl_in_seconds = 300
  conversation_flow_arn = aws_lex_conversation_flow.lex_flow.arn
}

# Create the Lex Conversation Flow
resource "aws_lex_conversation_flow" "lex_flow" {
  name      = var.lex_bot_name
  role_arn  = aws_iam_role.lex_role.arn
}
```

This Terraform program creates an IAM role and policy for the Lex Bot, attaches the policy to the role, and creates the Lex Bot with a conversation flow.

