  role       = aws_iam_role.lex_bot_role.name
  policy_arn = aws_iam_policy.lex_bot_policy.arn
}

# Create a Lex bot
resource "aws_lex_runtime_v2_bot" "pizza_bot" {
  name        = "pizza-bot"
  alias       = "pizza-bot-alias"
  role_arn    = aws_iam_role.lex_bot_role.arn

  conversation_flow {
    name    = "order-pizza"
    intent  = "OrderPizzaIntent"
    prompt  = "Welcome to Pizza Palace! How can we help you?"
  }

  # Create an intent for ordering pizza
  resource "aws_lex_runtime_v2_intent" "order_pizza_intent" {
    name        = "OrderPizzaIntent"
    description = "Intent for ordering pizza"

    slots = [
      {
        name                = "crust"
        type                = "CRUST"
        valueSelectionStrategy = "USER"
        isRequired          = true
      },
      {
        name                = "toppings"
        type                = "TOPPINGS"
        valueSelectionStrategy = "USER"
        isRequired          = true
      },
      {
        name                = "size"
        type                = "SIZE"
        valueSelectionStrategy = "USER"
        isRequired          = true
      },
    ]
  }

  # Create a follow-up question
  resource "aws_lex_runtime_v2_intent_slot" "toppings_slot" {
    name                = "Toppings"
    parent_intent_name  = aws_lex_runtime_v2_intent.order_pizza_intent.name
    slot_type_name      = "TOPPINGS"
    is_required         = true
  }

  # Define the slot values for the toppings slot
  resource "aws_lex_runtime_v2_intent_slot_value" "toppings_slot_value" {
    name                = "toppings"
    parent_intent_name  = aws_lex_runtime_v2_intent.order_pizza_intent.name
    slot_type_name      = "TOPPINGS"
    slot_value          = jsonencode({
      shape = "list"
      values = [
        {
          shape  = "object"
          values = [
            {
              shape  = "string"
              values = ["mushrooms"]
            },
            {
              shape  = "string"
              values = ["pepperoni"]
            }
          ]
        }
      ]
    })
  }
}

# Define a variable for the bot name
variable "bot_name" {
  type        = string
  default     = "pizza-bot"
}
```
This Terraform configuration creates an IAM role for the Lex bot, attaches a policy to the role, and creates a Lex bot with an intent for ordering pizza and a follow-up question for selecting toppings. The configuration also defines a variable for the bot name, which can be overridden when running the Terraform apply command.

