# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM Role for Lex
resource "aws_iam_role" "lex_role" {
  name        = "lex-role"
  description = "Role for AWS Lex"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM Policy for Lex
resource "aws_iam_policy" "lex_policy" {
  name        = "lex-policy"
  description = "Policy for AWS Lex"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "lex:PutSession",
          "lex:GetSession",
          "lex:PostText",
          "lex:PostAudio"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach Policy to Role
resource "aws_iam_role_policy_attachment" "lex_attach" {
  role       = aws_iam_role.lex_role.name
  policy_arn = aws_iam_policy.lex_policy.arn
}

# Create Lex Bot
resource "aws_lex_bot" "pizza_bot" {
  name          = "pizza-bot"
  locale        = "en-US"
  role_arn      = aws_iam_role.lex_role.arn
  conversation_flow_arn = aws_lex_conversation_flow.pizza_flow.arn
}

# Create Lex Conversation Flow
resource "aws_lex_conversation_flow" "pizza_flow" {
  name      = "pizza-flow"
  locale    = "en-US"
  role_arn  = aws_iam_role.lex_role.arn

  intents = [
    {
      name = "OrderPizzaIntent"
      slots = [
        {
          name        = "Crust"
          description = "The type of crust for the pizza"
          type        = "CrustType"
        },
        {
          name        = "Sauce"
          description = "The type of sauce for the pizza"
          type        = "SauceType"
        },
        {
          name        = "Cheese"
          description = "The type of cheese for the pizza"
          type        = "CheeseType"
        }
      ]
    }
  ]

  conclusions = [
    {
      statement = {
        text = "Your pizza order has been placed successfully. Thank you for ordering with us!"
      }
    }
  ]

  dialog Actions = [
    {
      name = "DialogAction"
      description = "Dialog Action"
      type        = "Text"
    }
  ]
}

# Output Bot ARN
output "lex_bot_arn" {
  value = aws_lex_bot.pizza_bot.arn
}
```

