```
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for Lex
resource "aws_iam_role" "lex_role" {
  name        = "lex-role"
  description = "Role for Lex Bot"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.us-west-2.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for Lex
resource "aws_iam_policy" "lex_policy" {
  name        = "lex-policy"
  description = "Policy for Lex Bot"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "lex:PutBot",
          "lex:PutIntent",
          "lex:PutSession",
          "lex:PostText"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach policy to role
resource "aws_iam_role_policy_attachment" "lex_attach" {
  role       = aws_iam_role.lex_role.name
  policy_arn = aws_iam_policy.lex_policy.arn
}

# Create Lex Bot
resource "aws_lex_bot" "pizza_bot" {
  name = "pizza-bot"
  alias = "pizza-bot-alias"

  # Set NLU Intent Confidence Threshold
  nlu_intent_confidence_threshold = 0.5

  # Define pizza ordering intent
  intent = {
    name = "order-pizza"
    slots = [
      {
        name         = "crust"
        description  = "What kind of crust do you want?"
        type         = "CRUST"
        values       = ["thin", "thick"]
        resolution_values = [
          {
            symbol  = "thin"
            value_id = "thin"
          },
          {
            symbol  = "thick"
            value_id = "thick"
          }
        ]
      },
      {
        name         = "toppings"
        description  = "What toppings do you want?"
        type         = "TOPPINGS"
        values       = ["pepperoni", "mushrooms", "olive"]
        resolution_values = [
          {
            symbol  = "pepperoni"
            value_id = "pepperoni"
          },
          {
            symbol  = "mushrooms"
            value_id = "mushrooms"
          },
          {
            symbol  = "olive"
            value_id = "olive"
          }
        ]
      }
    ]
  }

  # Configure bot response
  response = {
    output_speech = {
      ssml_mark_up = {
        text = "Your pizza will be delivered in 30 minutes."
      }
    }
  }
}
```

This configuration creates an IAM role and policy for Lex, attaches the policy to the role, and creates a Lex Bot with a single intent for ordering pizzas. The `nlu_intent_confidence_threshold` is set to 0.5 as requested. Note that this is a basic configuration and you may need to add additional features or configurations depending on your specific use case.

