**Terraform Program Description**
=====================================

This Terraform configuration will create an AWS Lex V2 model for a chatbot designed for children. The model will be configured with a child-friendly personality and responses. The chatbot will be integrated with Amazon Connect for handling incoming customer contacts.

**Terraform HCL Program**
```hcl
provider "aws" {
  region = "us-west-2"
}

variable "lexv2_model_name" {
  type        = string
  default     = "KidsChatbot"
  description = "Name of the Lex V2 model"
}

variable "lexv2_bot_name" {
  type        = string
  default     = "KidsChatbotBot"
  description = "Name of the Lex V2 bot"
}

variable "lexv2_intent_name" {
  type        = string
  default     = "GreetingIntent"
  description = "Name of the Lex V2 intent"
}

variable "lexv2_slot_name" {
  type        = string
  default     = "ChildNameSlot"
  description = "Name of the Lex V2 slot"
}

resource "aws_lexv2_model" "kids_chatbot" {
  name        = var.lexv2_model_name
  description = "Chatbot for kids"
  tags        = {
    "project" = "KidsChatbot"
  }
}

resource "aws_lexv2_bot" "kids_chatbot_bot" {
  name        = var.lexv2_bot_name
  description = "Chatbot for kids"
  model_id    = aws_lexv2_model.kids_chatbot.id
  idle_session_timeout_in_seconds = 300
}

resource "aws_lexv2_intent" "greeting_intent" {
  name        = var.lexv2_intent_name
  description = "Greeting intent for kids"
  parent_intent_signature_id = aws_lexv2_model.kids_chatbot.default_intent_signature_id
}

resource "aws_lexv2_slot" "child_name_slot" {
  name        = var.lexv2_slot_name
  description = "Slot for child's name"
  type        = "STRING"
  intent_id   = aws_lexv2_intent.greeting_intent.id
}

resource "aws_lexv2_intent_response" "greeting_response" {
  intent_id   = aws_lexv2_intent.greeting_intent.id
  name        = "GreetingResponse"
  type        = "TEXT"
  messages    = jsonencode([
    {
      content = "Hi, what's your name?"
    }
  ])
}

resource "aws_lexv2_intent_response" "goodbye_response" {
  intent_id   = aws_lexv2_intent.greeting_intent.id
  name        = "GoodbyeResponse"
  type        = "TEXT"
  messages    = jsonencode([
    {
      content = "See you later!"
    }
  ])
}

resource "aws_lexv2_session_storage" "storage" {
  storage_config {
    s3_config {
      bucket_name = "kids-chatbot-storage"
      prefix      = "sessions/"
    }
  }
  session_storage_config_name = "kids-chatbot-storage-config"
}

resource "aws_connect_flow" "kids_flow" {
  name        = "KidsChatbotFlow"
  instance_id = aws_connect_instance.kids_instance.id
  description = "Flow for kids chatbot"
}

resource "aws_connect_instance" "kids_instance" {
  name        = "KidsChatbotInstance"
  description = "Instance for kids chatbot"
}

resource "aws_connect_phone_number_config" "kids_phone_config" {
  instance_id = aws_connect_instance.kids_instance.id
  phone_numbers = [
    {
      phone_number      = "+1-123-456-7890"
      amazon_phone_number = "+1-123-456-7890"
    }
  ]
}
```
This Terraform configuration will create the following resources:

* An AWS Lex V2 model for a chatbot designed for children
* An AWS Lex V2 bot associated with the model
* An AWS Lex V2 intent for greeting users
* An AWS Lex V2 slot for capturing child's name
* An AWS Lex V2 intent response for greeting users
* An AWS Lex V2 intent response for saying goodbye
* An AWS Lex V2 session storage for storing user sessions
* An AWS Connect instance for handling incoming customer contacts
* An AWS Connect flow for integrating with the chatbot
* An AWS Connect phone number configuration for specifying the phone number to use

Note that you will need to create the S3 bucket "kids-chatbot-storage" and update the `aws_connect_instance` and `aws_connect_phone_number_config` resources to match your AWS Connect instance and phone number configuration.

