**Terraform Program Description**

The Terraform program will create an AWS Connect Bot Association resource to manage a bot for customer support in a contact center setting, specifically designed for interactions with children. The bot association will be created within a specified AWS Region.

**Terraform HCL Configuration**
```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the bot
resource "aws_iam_role" "connect_bot_role" {
  name        = "connect-bot-kids-role"
  description = "IAM role for AWS Connect bot"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "connect.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Create an IAM policy for the bot
resource "aws_iam_policy" "connect_bot_policy" {
  name        = "connect-bot-kids-policy"
  description = "IAM policy for AWS Connect bot"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "connect:StartChatContact",
          "connect:CreateContactFlow",
          "connect:CreateQueue",
          "connect:UpdateQueue",
          "connect:DescribeQueue",
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "connect_bot_attach" {
  role       = aws_iam_role.connect_bot_role.name
  policy_arn = aws_iam_policy.connect_bot_policy.arn
}

# Create an AWS Connect instance
resource "aws_connect_instance" "kids_instance" {
  name = "Kids-Support-Instance"

  // This is the ARN of the IAM role created above
  instance_identity = aws_iam_role.connect_bot_role.arn
}

# Create an AWS Connect bot
resource "aws_connect_bot" "kids_bot" {
  name        = "Kids-Support-Bot"
  instance_id = aws_connect_instance.kids_instance.id

  // This is the ARN of the IAM role created above
  identity = aws_iam_role.connect_bot_role.arn
}

# Create an AWS Connect bot association
resource "aws_connect_bot_association" "kids_association" {
  name        = "Kids-Support-Association"
  instance_id = aws_connect_instance.kids_instance.id

  // This is the ARN of the IAM role created above
  identity = aws_iam_role.connect_bot_role.arn

  // Specify the bot to associate
  bot_arn = aws_connect_bot.kids_bot.arn
}
```
This Terraform program will create:

1. An IAM role for the bot with the necessary permissions.
2. An IAM policy for the bot with the necessary permissions.
3. An AWS Connect instance with the IAM role attached.
4. An AWS Connect bot associated with the instance and IAM role.
5. An AWS Connect bot association with the bot and instance specified.

