**Description:**
This Terraform configuration will create a basic Amazon Kinesis stream in the US East (N. Virginia) region. The configuration includes the IAM role necessary for the Kinesis stream to write data to the stream. The Kinesis stream will be created with the default attributes.

**Terraform HCL Program:**

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-east-1"
}

# Create an IAM Role for Kinesis
resource "aws_iam_role" "kinesis_role" {
  name        = "kinesis-stream-role"
  description = "Role for Kinesis stream to write to the stream"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesis.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM Policy for Kinesis
resource "aws_iam_policy" "kinesis_policy" {
  name        = "kinesis-stream-policy"
  description = "Policy for Kinesis stream to write to the stream"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:PutRecord",
          "kinesis:PutRecords",
        ]
        Effect = "Allow"
        Resource = aws_kinesis_stream.kinesis_stream.arn
      }
    ]
  })
}

# Attach the Policy to the IAM Role
resource "aws_iam_role_policy_attachment" "kinesis_attach" {
  role       = aws_iam_role.kinesis_role.name
  policy_arn = aws_iam_policy.kinesis_policy.arn
}

# Create the Kinesis Stream
resource "aws_kinesis_stream" "kinesis_stream" {
  name        = "my-kinesis-stream"
  shard_count = 1

  iam_role_arn = aws_iam_role.kinesis_role.arn
}
```

This Terraform configuration will create a basic Amazon Kinesis stream named `my-kinesis-stream` in the US East (N. Virginia) region. The IAM role `kinesis-stream-role` is created and attached to the Kinesis stream, allowing it to write data to the stream. The IAM policy `kinesis-stream-policy` is also created and attached to the IAM role, granting the necessary permissions to the Kinesis stream.

