**Description of the Terraform Program**

This Terraform configuration will create the following resources:

1. An Amazon Kinesis Data Stream with a single shard
2. An Amazon Kinesis Analytics Application with an input stream configured
3. An IAM Role for the Kinesis Analytics Application

The Terraform program will use the AWS provider to create these resources in the `us-west-2` region.

**Terraform HCL Program**
```hcl
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM Role for the Kinesis Analytics Application
resource "aws_iam_role" "kinesis-analytics-role" {
  name        = "kinesis-analytics-role"
  description = "Role for Kinesis Analytics Application"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesis.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM Policy for the Kinesis Analytics Application
resource "aws_iam_policy" "kinesis-analytics-policy" {
  name        = "kinesis-analytics-policy"
  description = "Policy for Kinesis Analytics Application"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "kinesis:GetShardIterator"
        Effect = "Allow"
        Resource = aws_kinesis_stream.example.arn
      },
      {
        Action = "kinesis:GetRecords"
        Effect = "Allow"
        Resource = aws_kinesis_stream.example.arn
      },
      {
        Action = "kinesis:DescribeStream"
        Effect = "Allow"
        Resource = aws_kinesis_stream.example.arn
      }
    ]
  })
}

# Create the IAM Policy Attachment
resource "aws_iam_role_policy_attachment" "kinesis-analytics-attachment" {
  role       = aws_iam_role.kinesis-analytics-role.name
  policy_arn = aws_iam_policy.kinesis-analytics-policy.arn
}

# Create the Kinesis Data Stream
resource "aws_kinesis_stream" "example" {
  name        = "example-stream"
  shard_count = 1

  shard_configuration = jsonencode({
    StreamingMode = "PROVISIONED"
    RetentionPeriodHours = 24
  })
}

# Create the Kinesis Analytics Application
resource "aws_kinesis_analytics_application" "example" {
  name                = "example-application"
  input_schema        = jsonencode({
    "name" = "example-stream"
    "type" = "Kinesis"
  })
  input_streams = [
    {
      name = aws_kinesis_stream.example.name
    }
  ]
  role_arn = aws_iam_role.kinesis-analytics-role.arn
}

variable "aws_region" {
  default = "us-west-2"
}
```
This Terraform configuration creates the necessary IAM role and policy for the Kinesis Analytics Application, a Kinesis Data Stream with a single shard, and the Kinesis Analytics Application itself. The input stream is configured to read from the created Kinesis Data Stream.

