# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM Role for the Firehose Delivery Stream
resource "aws_iam_role" "firehose_role" {
  name        = "firehose-role"
  description = "IAM Role for Firehose Delivery Stream"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM Policy for the Firehose Delivery Stream
resource "aws_iam_policy" "firehose_policy" {
  name        = "firehose-policy"
  description = "IAM Policy for Firehose Delivery Stream"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:GetObject"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.firehose_bucket.arn,
          "${aws_s3_bucket.firehose_bucket.arn}/*"
        ]
      }
    ]
  })
}

# Create an IAM Role Policy Attachment for the Firehose Delivery Stream
resource "aws_iam_role_policy_attachment" "firehose_attach" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = aws_iam_policy.firehose_policy.arn
}

# Create an S3 Bucket for the Firehose Destination
resource "aws_s3_bucket" "firehose_bucket" {
  bucket = "firehose-bucket"
  acl    = "private"
}

# Create a Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "example" {
  name        = "firehose-example"
  destination = "extended_s3"

  kinesis_stream_source_configuration {
    kinesis_stream_arn = aws_kinesis_stream.example.arn
  }

  extended_s3_configuration {
    role_arn = aws_iam_role.firehose_role.arn

    s3_bucket_arn = aws_s3_bucket.firehose_bucket.arn
    s3_configuration {
      role_arn = aws_iam_role.firehose_role.arn

      compression_format = "GZIP"
      encryption_mode   = "SSE_KMS"

      dynamic_partitioning_enabled = true
      dynamic_partitioning_configuration {
        enabled = true
        hash_key_field = "event_id"
      }
    }
  }
}

# Create a Kinesis Stream (required for Firehose Delivery Stream)
resource "aws_kinesis_stream" "example" {
  name        = "firehose-stream"
  shard_count = 1
}
```

Note: This code creates a Kinesis Firehose Delivery Stream with an extended S3 Destination and Dynamic Partitioning enabled. It also creates the required IAM Role, Policy, and Role Policy Attachment. The code uses the `aws_iam_role` and `aws_iam_policy` resources to create the IAM Role and Policy, and then attaches the Policy to the Role using `aws_iam_role_policy_attachment`. The `aws_kinesis_firehose_delivery_stream` resource is used to create the Firehose Delivery Stream, and the `aws_kinesis_stream` resource is used to create the required Kinesis Stream.

