  region = "us-west-2"
}

# Create a IAM role for Firehose to assume
resource "aws_iam_role" "firehose_role" {
  name        = "firehose-role"
  description = "Firehose execution role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      },
    ]
  })
}

