resource "aws_iam_policy" "firehose_policy" {
  name        = "firehose-policy"
  description = "Firehose policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:PutRecord",
          "kinesis:PutRecords",
          "kinesis:PutRecordBatch",
        ]
        Effect = "Allow"
        Resource = "arn:aws:kinesis:${aws_region}:${data.aws_caller_identity.current.account_id}:stream/*"
      },
      {
        Action = [
          "redshift:GetClusterCredentials",
          "redshift:DescribeClusters",
          "redshift:GetClusterProperties",
        ]
        Effect = "Allow"
        Resource = "arn:aws:redshift:${aws_region}:${data.aws_caller_identity.current.account_id}:cluster/*"
      },
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:PutObjectAcl",
        ]
        Effect = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.firehose_bucket.name}/*"
      },
    ]
  })
}

# Attach the policy to the role
