Here is the Terraform program that defines a Kinesis Firehose Delivery Stream with an Elasticsearch destination, an IAM role, and a bucket:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create IAM role for Firehose
resource "aws_iam_role" "firehose_role" {
  name        = "Firehose-${var.environment}"
  description = "Firehose Role for ${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}

# Create IAM policy for Firehose
resource "aws_iam_policy" "firehose_policy" {
  name        = "Firehose-${var.environment}"
  description = "Firehose Policy for ${var.environment}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "KinesisAccess"
        Effect    = "Allow"
        Action    = "kinesis:PutRecord"
        Resource  = aws_kinesis_stream.example.arn
      },
      {
        Sid       = "S3Access"
        Effect    = "Allow"
        Action    = ["s3:PutObject", "s3:DeleteObject"]
        Resource  = aws_s3_bucket.example.arn
      },
      {
        Sid       = "ESAccess"
        Effect    = "Allow"
        Action    = ["es:ESHttpPost"]
        Resource  = aws_elasticsearch_domain.example.domain_endpoint
      }
    ]
  })
}

# Attach policy to IAM role
resource "aws_iam_role_policy_attachment" "firehose_attach" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = aws_iam_policy.firehose_policy.arn
}

# Create S3 Bucket
resource "aws_s3_bucket" "example" {
  bucket = "firehose-bucket-${var.environment}"
  acl    = "private"

  versioning {
    enabled = true
  }
}

# Create Elasticsearch domain
resource "aws_elasticsearch_domain" "example" {
  domain_name           = "firehose-es-${var.environment}"
  elasticsearch_version = "7.10"

  domain_endpoint_options {
    enforce_https        = true
    tls_security_policy  = "Policy-Min-TLS-1-0-2019-07"
  }

  access_policies = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowAccess"
        Effect    = "Allow"
        Principal = {
          AWS = aws_iam_role.firehose_role.arn
        }
        Action    = [
          "es:ESHttpPost",
        ]
        Resource  = aws_elasticsearch_domain.example.domain_endpoint
      }
    ]
  })
}

# Create Kinesis Stream
resource "aws_kinesis_stream" "example" {
  name        = "firehose-stream-${var.environment}"
  shard_count = 1
}

# Create Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "example" {
  name        = "firehose-delivery-stream-${var.environment}"
  destination = "elasticsearch"

  elasticsearch_configuration {
    role_arn = aws_iam_role.firehose_role.arn
    domain_name = aws_elasticsearch_domain.example.domain_endpoint
  }

  kinesis_source_configuration {
    kinesis_stream_arn = aws_kinesis_stream.example.arn
    data_format = "json"
  }

  s3_bucket_arn = aws_s3_bucket.example.arn

  depends_on = [
    aws_elasticsearch_domain.example,
    aws_kinesis_stream.example,
    aws_s3_bucket.example,
  ]
}

variable "environment" {
  type = string
  default = "dev"
}
```

Note: This configuration assumes you want to create a new Elasticsearch domain and S3 bucket, and a Kinesis Firehose Delivery Stream that sends data to the Elasticsearch domain. The IAM role created for the Firehose Delivery Stream has access to the Kinesis Stream, the S3 bucket, and the Elasticsearch domain. Make sure to replace `us-west-2` with your preferred region and adjust the variable `environment` as needed.

