  role_arn = aws_iam_role.firehose-role.arn

  # S3 Configuration
  s3_configuration {
    role_arn            = aws_iam_role.firehose-role.arn
    compression_format  = "GZIP"
    compression_library = "SNappy"

    s3_backup_mode = "Disabled"

    # Kinesis Firehose Buffer Size
    buffer_size = 64

    # Kinesis Firehose Buffer Interval
    buffer_interval = 300

    s3_backup_mode = "Disabled"
    s3_backup_bucket_arn = aws_s3_bucket.example.arn
  }

  # Kinesis Firehose Buffer Size
  buffer_size = 64

  # Kinesis Firehose Buffer Interval
  buffer_interval = 300

