And here is the Terraform HCL program:
```hcl
provider "aws" {
  region = "us-west-2"
}

variable "delivery_stream_name" {
  default = "splunk-delivery-stream"
}

variable "splunk_hec_url" {
  default = "https://your-splunk-hec-url.com:8088"
}

variable "splunk_hec_token" {
  default = "your-splunk-hec-token"
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose-splunk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_policy" {
  name        = "firehose-splunk-policy"
  description = "Policy for Firehose to access Splunk"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "logs:CreateLogGroup"
        Effect = "Allow"
        Resource = "arn:aws:logs:${aws_region}:${aws_account_id}:*"
      },
      {
        Action = "logs:CreateLogStream"
        Effect = "Allow"
        Resource = "arn:aws:logs:${aws_region}:${aws_account_id}:*"
      },
      {
        Action = "logs:PutLogEvents"
        Effect = "Allow"
        Resource = "arn:aws:logs:${aws_region}:${aws_account_id}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_attachment" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = aws_iam_policy.firehose_policy.arn
}

resource "aws_kinesis_firehose_delivery_stream" "splunk_stream" {
  name = var.delivery_stream_name

  destination = "s3"
  s3_bucket_arn = aws_s3_bucket.splunk_bucket.arn

  splunk {
    hec_url       = var.splunk_hec_url
    hec_token      = var.splunk_hec_token
    hec_username   = "your-splunk-hec-username"
    hec_password   = "your-splunk-hec-password"
    hec_hec_index  = "your-splunk-hec-index"
  }
}

resource "aws_s3_bucket" "splunk_bucket" {
  bucket = "splunk-bucket"
  acl    = "private"
}
```
