Here is a Terraform HCL program to create a Kinesis Firehose Delivery Stream with an OpenSearch Serverless Destination:

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-east-1"
}

# Create an IAM role for the Firehose Delivery Stream
resource "aws_iam_role" "firehose_delivery_role" {
  name        = "kinesis-firehose-delivery-role"
  description = "Role for Kinesis Firehose Delivery Stream"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the Firehose Delivery Stream
resource "aws_iam_policy" "firehose_delivery_policy" {
  name        = "kinesis-firehose-delivery-policy"
  description = "Policy for Kinesis Firehose Delivery Stream"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "kinesis:DescribeStream",
          "kinesis:GetShardIterator",
          "kinesis:GetRecords",
        ]
        Effect = "Allow"
        Resource = "arn:aws:kinesis:${aws_region}:*:stream:*"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "firehose_delivery_policy_attach" {
  role       = aws_iam_role.firehose_delivery_role.name
  policy_arn = aws_iam_policy.firehose_delivery_policy.arn
}

# Create a Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "example" {
  name        = "example-delivery-stream"
  destination = "opensearch"

  opensearch {
    domain_arn = "arn:aws:opensearch:${aws_region}:*:domain:*"
  }

  s3_configuration {
    role_arn = aws_iam_role.firehose_delivery_role.arn
  }
}
```

Please note that the `aws_region` variable is a special variable in Terraform that represents the current region, which we're setting to `us-east-1` in this example. You should replace it with your desired region. Also, you need to replace the `domain_arn` value with the actual ARN of your OpenSearch domain.

