**Description**

This Terraform program will create a Kinesis Data Firehose Delivery Stream with an Elasticsearch destination, configured to run within a specified VPC.

**Terraform HCL Program**
```terraform
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  type = string
  default = "vpc-12345678"
}

variable "subnet_ids" {
  type = list(string)
  default = ["subnet-12345678", "subnet-23456789"]
}

variable "elasticsearch_domain" {
  type = string
  default = "my-elasticsearch-domain"
}

variable "firehose_name" {
  type = string
  default = "my-firehose-delivery-stream"
}

resource "aws_iam_role" "firehose_role" {
  name        = "${var.firehose_name}-role"
  description = "Firehose role for delivering data to Elasticsearch"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "firehose_policy" {
  name   = "${var.firehose_name}-policy"
  role   = aws_iam_role.firehose_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutEvent"
        ]
        Resource = "*"
        Effect    = "Allow"
      },
      {
        Action = "es:ESHttpPost"
        Resource = "${aws_elasticsearch_domain.elasticsearch.domain_name}:443"
        Effect    = "Allow"
      }
    ]
  })
}

resource "aws_elasticsearch_domain" "elasticsearch" {
  domain_name           = var.elasticsearch_domain
  elasticsearch_version = "7.10"
  cluster_config {
    instance_count = 1
  }
}

resource "aws_kinesis_firehose_delivery_stream" "delivery_stream" {
  name        = var.firehose_name
  destination = "elasticsearch"

  ElasticsearchConfiguration {
    role_arn = aws_iam_role.firehose_role.arn
    domain_name = aws_elasticsearch_domain.elasticsearch.domain_name
  }

  vpc_configuration {
    subnet_ids = var.subnet_ids
  }
}
```
