  description = "Policy for Firehose to access HTTP endpoint"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "logs:PutRecord"
        Effect = "Allow"
        Resource = "arn:aws:logs:us-west-2:*:*"
      },
      {
        Action = "logs:DescribeLogGroups"
        Effect = "Allow"
        Resource = "arn:aws:logs:us-west-2:*:*"
      },
      {
        Action = "kinesis:PutRecord"
        Effect = "Allow"
        Resource = "arn:aws:kinesis:us-west-2:*:*"
      },
      {
        Action = "iam:GetRole"
        Effect = "Allow"
        Resource = "arn:aws:iam::*:role/firehose-delivery-stream-role"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_attach" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = aws_iam_policy.firehose_policy.arn
}

# Create a Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "example" {
  name        = "example-delivery-stream"
  role_arn    = aws_iam_role.firehose_role.arn
  destination = "http"

  s3_bucket_arn = "arn:aws:s3:::my-bucket"

  http_endpoint_configuration {
    url              = "https://ingest.newrelic.com/v1/accounts/1234567/events"
    name             = "New Relic"
    role_arn         = aws_iam_role.firehose_role.arn
    s3backup_mode   = "FailedDataS3BackupMode"
  }
}

# Create a VPC Configuration for the Delivery Stream
resource "aws_kinesis_firehose_vpc_configuration" "example" {
  name                = "example-vpc-config"
  vpc_id              = "vpc-12345678"
  role_arn            = aws_iam_role.firehose_role.arn

  subnet_ids = [
    "subnet-12345678",
    "subnet-90123456",
  ]

  tags = {
    Name = "example-vpc-config"
  }
}
```
This program creates a Kinesis Firehose Delivery Stream named "example-delivery-stream" with a HTTP endpoint destination at "https://ingest.newrelic.com/v1/accounts/1234567/events". The Delivery Stream uses an IAM role named "firehose-delivery-stream-role" with the necessary permissions to access the HTTP endpoint. The VPC Configuration enables the Delivery Stream to access the VPC.

