Here is a Terraform configuration that defines a Kinesis Stream Consumer resource:

```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM Role for the Kinesis Stream Consumer
resource "aws_iam_role" "kinesis_consumer_role" {
  name        = "kinesis-consumer-role"
  description = "Role for Kinesis Stream Consumer"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesis.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM Policy for the Kinesis Stream Consumer
resource "aws_iam_policy" "kinesis_consumer_policy" {
  name        = "kinesis-consumer-policy"
  description = "Policy for Kinesis Stream Consumer"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "kinesis:GetShardIterator"
        Effect = "Allow"
        Resource = "${aws_kinesis_stream.consumer.arn}:shard-iterator/*"
      },
      {
        Action = "kinesis:GetRecords"
        Effect = "Allow"
        Resource = "${aws_kinesis_stream.consumer.arn}:shard-iterator/*"
      }
    ]
  })
}

# Attach the IAM Policy to the IAM Role
resource "aws_iam_role_policy_attachment" "kinesis_consumer_attach" {
  role       = aws_iam_role.kinesis_consumer_role.name
  policy_arn = aws_iam_policy.kinesis_consumer_policy.arn
}

# Create a Kinesis Stream
resource "aws_kinesis_stream" "consumer" {
  name             = "kinesis-consumer-stream"
  shard_count      = 1
  retention_period = 24

  # Enable Server-Side Encryption (SSE) for the Kinesis Stream
  encryption_type = "KMS"

  # Define the Kinesis Stream's KMS Key ID
  kms_key_id = "arn:aws:kms:us-west-2:123456789012:key/12345678-1234-1234-1234-123456789012"
}

# Create a Kinesis Stream Consumer
resource "aws_kinesis_consumer" "kinesis_consumer" {
  name       = "kinesis-consumer"
  stream_arn = aws_kinesis_stream.consumer.arn

  # Specify the IAM Role for the Kinesis Stream Consumer
  iam_role = aws_iam_role.kinesis_consumer_role.arn
}
```

In this Terraform configuration:

1. We define an IAM Role for the Kinesis Stream Consumer.
2. We create an IAM Policy for the Kinesis Stream Consumer, allowing the necessary permissions.
3. We attach the IAM Policy to the IAM Role.
4. We create a Kinesis Stream with one shard.
5. We create a Kinesis Stream Consumer with the IAM Role specified.

