```hcl
# Provider configuration
provider "aws" {
  region = "us-west-2"
}

# Create a Kinesis Analytics Application
resource "aws_kinesisanalyticsv2_application" "example_app" {
  name        = "example-app"
  environment = "DEV"

  runtime = "SQL_2"

  source {
    application_name = aws_kinesisanalyticsv2_application.example_app.name
    source_type      = "KINESIS_STREAM_AS_SOURCE"

    kinesis_stream_sources {
      source_id         = "stream-source"
      stream_name       = "example-stream"
      role_arn          = aws_iam_role.kinesis_analytics_role.arn
    }
  }

  destination {
    destination_id = "cw-destination"
    kinesis_streams {
      output {
        destination_arn = aws_kinesis_stream.example_stream.arn
        name            = "output-stream"
      }
    }
  }
}

# Create a CloudWatch Log Group and Stream
resource "aws_cloudwatch_log_group" "example_log_group" {
  name              = "example-log-group"
  retention_in_days = 14
}

resource "aws_cloudwatch_log_stream" "example_log_stream" {
  name           = "example-log-stream"
  log_group_name = aws_cloudwatch_log_group.example_log_group.name
}

# Create a Kinesis Stream
resource "aws_kinesis_stream" "example_stream" {
  name        = "example-stream"
  shard_count = 1
}

# Create IAM Role for Kinesis Analytics
resource "aws_iam_role" "kinesis_analytics_role" {
  name        = "kinesis-analytics-role"
  description = "Role for Kinesis Analytics"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })
}

# Create IAM Policy for Kinesis Analytics
resource "aws_iam_policy" "kinesis_analytics_policy" {
  name        = "kinesis-analytics-policy"
  description = "Policy for Kinesis Analytics"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:GetShardIterator",
          "kinesis:GetRecords",
          "kinesis:DescribeStream",
        ]
        Effect = "Allow"
        Resource = [
          aws_kinesis_stream.example_stream.arn
        ]
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Effect = "Allow"
        Resource = [
          aws_cloudwatch_log_group.example_log_group.arn,
          aws_cloudwatch_log_stream.example_log_stream.arn,
        ]
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "kinesis_analytics_policy_attachment" {
  role       = aws_iam_role.kinesis_analytics_role.name
  policy_arn = aws_iam_policy.kinesis_analytics_policy.arn
}
```
