Here is the Terraform program in HCL that configures Active-Active Failover policies using Route 53 resources:
```hcl
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Create the health check resources
resource "aws_route53_health_check" "primary_health_check" {
  fqdn = "primary.example.com."
  port = 80
  type = "HTTP"
  resource_path = "/"
  enabled = true
}

resource "aws_route53_health_check" "secondary_health_check" {
  fqdn = "secondary.example.com."
  port = 80
  type = "HTTP"
  resource_path = "/"
  enabled = true
}

# Create the Route 53 zone
resource "aws_route53_zone" "main" {
  name = "example.com."
}

# Create a resource record set for each health check
resource "aws_route53_record" "primary_health_check_rrset" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "primary.example.com."
  type    = "A"
  alias {
    name                   = aws_route53_health_check.primary_health_check.id
    zone_id                = aws_route53_health_check.primary_health_check.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "secondary_health_check_rrset" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "secondary.example.com."
  type    = "A"
  alias {
    name                   = aws_route53_health_check.secondary_health_check.id
    zone_id                = aws_route53_health_check.secondary_health_check.zone_id
    evaluate_target_health = true
  }
}

# Create the Route 53 resource record set for failover
resource "aws_route53_record" "failover_rrset" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "example.com."
  type    = "A"
  alias {
    name                   = aws_route53_health_check.primary_health_check.id
    zone_id                = aws_route53_health_check.primary_health_check.zone_id
    evaluate_target_health = true
  }
  failover_routing_policy {
    primary        = aws_route53_health_check.primary_health_check.id
    secondary      = aws_route53_health_check.secondary_health_check.id
    failure_threshold = 1
  }
  # Use the primary health check resource as the primary record
  set_identifier = "primary"
  # Use the secondary health check resource as the secondary record
  set_identifier = "secondary"
}

output "zone_id" {
  value = aws_route53_zone.main.zone_id
}

output "primary_health_check_id" {
  value = aws_route53_health_check.primary_health_check.id
}

output "secondary_health_check_id" {
  value = aws_route53_health_check.secondary_health_check.id
}
```
This configuration will create a Route 53 zone, two health check resources, and two resource record sets that reference the health checks. The failover routing policy is also configured, using the primary health check resource as the primary record and the secondary health check resource as the secondary record.

