}

# Create a CloudWatch metric alarm
resource "aws_cloudwatch_metric_alarm" "foobar" {
  alarm_name          = "foobar"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = "1"
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  period              = "120"
  statistic           = "Average"
  threshold           = "50"

  dimensions = {
    AutoScalingGroupName = "foobar"
  }

  actions_enabled = true
  alarm_description = "foobar"
  alarm_actions = [
    "arn:aws:sns:us-east-1:123456789012:foobar"
  ]

  ok_actions = [
    "arn:aws:sns:us-east-1:123456789012:foobar"
  ]
}

# Create a Route 53 health check
resource "aws_route53_health_check" "foobar" {
  caller_reference = "foobar"
  ip_address      = "8.8.8.8"
  port            = 443
  type            = "HTTPS"

  request {
    protocol_version = "HTTP1"
    resource_path    = "/"
    fully_qualified_domain_name = "foobar.example.com"
  }

  # Configure the health check to use the CloudWatch metric alarm
  failure_threshold = 5
  insufficient_data_action {
    health_check_id = aws_route53_health_check.foobar.id
    action = "UNHEALTHY"
    value = "0"
  }
  insufficient_data_action {
    health_check_id = aws_route53_health_check.foobar.id
    action = "UNHEALTHY"
    value = "0"
  }

  # If the health check doesn't have enough info about the alarm, the status should be "Healthy"
  insufficient_data_action {
    health_check_id = aws_route53_health_check.foobar.id
    action = "HEALTHY"
    value = "0"
  }
}
