**Description of the Terraform Program:**
This Terraform program will define a Route 53 Traffic Policy to route traffic between two resources based on a specified traffic policy type. The program will create a Route 53 hosted zone, a Traffic Policy, and the necessary Route 53 records to enable the traffic policy.

**Terraform HCL Program:**
```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create a Route 53 Hosted Zone
resource "aws_route53_zone" "example" {
  name = "example.com"
}

# Create a Traffic Policy
resource "aws_route53_traffic_policy" "example" {
  name            = "example-traffic-policy"
  query_log_config = false
  type             = "MULTI_VALUE_ANSWER"
  zone_id          = aws_route53_zone.example.id
}

# Create a Traffic Policy Record
resource "aws_route53_traffic_policy_record" "example" {
  name            = "example.com"
  type            = "A"
  traffic_policy  = aws_route53_traffic_policy.example.id
  zone_id         = aws_route53_zone.example.id
  records         = ["1.2.3.4", "5.6.7.8"]
}

# Create an IAM Role for the Traffic Policy
resource "aws_iam_role" "traffic_policy_role" {
  name        = "example-traffic-policy-role"
  description = "Role for the Route 53 Traffic Policy"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the IAM Role to the Traffic Policy
resource "aws_route53_traffic_policy_association" "example" {
  traffic_policy_id = aws_route53_traffic_policy.example.id
  zone_id          = aws_route53_zone.example.id
}
```
