```hcl
# Define the variable 'cluster_name'
variable "cluster_name" {
  type        = string
  default     = "my-eks-cluster"
  description = "The name of the EKS cluster"
}

# Define the VPC subnet IDs for networking
variable "subnet_ids" {
  type        = list(string)
  default     = ["subnet-12345678", "subnet-90123456"]
  description = "List of VPC subnet IDs for EKS cluster"
}

# Define the IAM role for EKS cluster
resource "aws_iam_role" "eks_cluster" {
  name        = "${var.cluster_name}-eks-cluster-role"
  description = "EKS cluster IAM role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

# Define the IAM policy attachment for EKS cluster and service policies
resource "aws_iam_role_policy_attachment" "eks_cluster" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_service" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

# Define the EKS cluster
resource "aws_eks_cluster" "this" {
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids = var.subnet_ids
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster,
    aws_iam_role_policy_attachment.eks_service,
  ]
}

# Define the EKS cluster provider
provider "aws" {
  region = "us-west-2"
  alias  = "eks_region"
}

# Define the EKS cluster kubectl configuration
resource "null_resource" "eks_cluster_kubectl" {
  provisioner "local-exec" {
    command     = "aws eks update-kubeconfig --name ${var.cluster_name} --region ${aws_eks_cluster.this.endpoint.split('.')[0]} --role ${aws_iam_role.eks_cluster.arn}"
    when        = create
  }

  provisioner "local-exec" {
    command     = "aws eks delete-kubeconfig --name ${var.cluster_name} --region ${aws_eks_cluster.this.endpoint.split('.')[0]} --role ${aws_iam_role.eks_cluster.arn}"
    when        = destroy
  }
}
```

Note that you will need to adjust the `subnet_ids` variable to match the IDs of your actual VPC subnets. Additionally, the `aws_iam_role_policy_attachment` resources are attaching the `AmazonEKSClusterPolicy` and `AmazonEKSServicePolicy` policies to the IAM role, which are necessary for EKS cluster and service management.

To use this configuration, save it to a file named `main.tf`, then run `terraform init` to initialize the Terraform working directory. Run `terraform apply` to create the resources specified in the configuration.

