# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create the IAM role for the EKS cluster
resource "aws_iam_role" "example" {
  name        = "example-eks-cluster"
  description = "For EKS Cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

# Create the IAM policy for the EKS cluster
resource "aws_iam_policy" "example" {
  name        = "example-eks-cluster-policy"
  description = "Policy for EKS Cluster"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "eks:DescribeCluster",
          "eks:DescribeNodegroup",
          "eks:UpdateClusterConfig",
          "eks:UpdateNodegroupConfig",
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "example" {
  role       = aws_iam_role.example.name
  policy_arn = aws_iam_policy.example.arn
}

# Create the VPC and subnets
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "example2" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

# Create the EKS cluster
resource "aws_eks_cluster" "example" {
  name     = "example"
  role_arn = aws_iam_role.example.arn

  vpc_config {
    subnet_ids = [aws_subnet.example.id, aws_subnet.example2.id]
  }

  depends_on = [aws_iam_role_policy_attachment.example]
}

# Output the cluster endpoint and kubeconfig certificate authority data
output "cluster_endpoint" {
  value       = aws_eks_cluster.example.endpoint
  description = "The endpoint for the EKS cluster"
}

output "kubeconfig_certificate_authority_data" {
  value       = aws_eks_cluster.example.certificate_authority[0].data
  description = "The certificate authority data for the EKS cluster"
}
```
