```hcl
# Configure AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Variable for S3 Bucket Suffix
variable "bucket_suffix" {
  default     = "test"
  description = "S3 bucket suffix"
}

# Variable for the local file path of the object to upload
variable "object_path" {
  default     = "path/to/order_data2.csv"
  description = "Path to the object to upload to the web data bucket"
}

# S3 Bucket for CloudGoat Data Storage
resource "aws_s3_bucket" "cloudgoat_data" {
  bucket = "cloudgoat-data-${var.bucket_suffix}"
  acl    = "private"

  # Enable versioning to track changes
  versioning {
    enabled = true
  }

  # Enable server-side encryption by default
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# IAM Role for Object Writer Access
resource "aws_iam_role" "object_writer" {
  name = "ObjectWriterAccess"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      },
    ]
  })
}

# S3 Bucket Policy for Object Writer Access
resource "aws_s3_bucket_policy" "cloudgoat_data_policy" {
  bucket = aws_s3_bucket.cloudgoat_data.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowObjectWriterAccess"
        Effect    = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action    = "s3:GetObject"
        Resource  = aws_s3_bucket.cloudgoat_data.arn
        Condition  = {
          StringEquals = {
            s3:x-amz-acl  = "bucket-owner-full-control"
          }
        }
      },
    ]
  })
}

# S3 Bucket for Web Data Storage
resource "aws_s3_bucket" "web_data" {
  bucket = "web-data-${var.bucket_suffix}"
  acl    = "private"

  # Enable versioning to track changes
  versioning {
    enabled = true
  }

  # Enable server-side encryption by default
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# Upload 'order_data2.csv' to the web data bucket
resource "aws_s3_bucket_object" "web_data_object" {
  bucket = aws_s3_bucket.web_data.id
  key    = "order_data2.csv"
  source = var.object_path
  etag   = filemd5(var.object_path)
}

# Public Access Block for the web data bucket
resource "aws_s3_bucket_public_access_block" "web_data_access" {
  bucket = aws_s3_bucket.web_data.id

  block_public_acls   = true
  block_public_policy = true
  ignore_public_acls  = true
  restrict_public_buckets = true
}

# Bucket Policy for the web data bucket
resource "aws_s3_bucket_policy" "web_data_policy" {
  bucket = aws_s3_bucket.web_data.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowPutObject"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = aws_s3_bucket.web_data.arn
        Condition  = {
          StringEquals = {
            s3:x-amz-acl  = "bucket-owner-full-control"
          }
        }
      },
    ]
  })
}
```

