**Terraform Configuration for AWS S3 Buckets with Access Control and Logging**

This Terraform configuration sets up two AWS S3 buckets with distinct names, defines access control for each bucket with predefined ACL settings, and configures S3 bucket logging for one of the buckets to send its logs to the other.

**main.tf**
```terraform
# Define provider configuration
provider "aws" {
  region = "us-west-2"
}

# Define variables
variable "bucket_name1" {
  default = "my-private-bucket"
}

variable "bucket_name2" {
  default = "my-logging-bucket"
}

variable "acl" {
  default = "private"
}

variable "log_prefix" {
  default = "my-bucket-logs-"
}

# Create IAM role for S3 bucket logging
resource "aws_iam_role" "s3_logging_role" {
  name        = "s3-bucket-logging-role"
  description = "Role for S3 bucket logging"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Create S3 buckets
resource "aws_s3_bucket" "private_bucket" {
  bucket = var.bucket_name1
  acl    = var.acl

  # Create IAM policy for S3 bucket access
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = "*"
        Action = "s3:GetObject"
        Resource = aws_s3_bucket.private_bucket.arn
      }
    ]
  })
}

resource "aws_s3_bucket" "logging_bucket" {
  bucket = var.bucket_name2
  acl    = "log-delivery-write"

  # Create IAM policy for S3 bucket logging
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = "*"
        Action = "s3:PutObject"
        Resource = aws_s3_bucket.logging_bucket.arn
      }
    ]
  })
}

# Configure S3 bucket logging
resource "aws_s3_bucket_logging" "bucket_logging" {
  bucket = aws_s3_bucket.private_bucket.id
  target_bucket = aws_s3_bucket.logging_bucket.id
  target_prefix = var.log_prefix
}

# Output bucket IDs
output "private_bucket_id" {
  value = aws_s3_bucket.private_bucket.id
}

output "logging_bucket_id" {
  value = aws_s3_bucket.logging_bucket.id
}
```
This Terraform configuration defines two S3 buckets, `my-private-bucket` and `my-logging-bucket`, with distinct names and access control settings. The `my-private-bucket` is set to private, while `my-logging-bucket` is set to allow log delivery writes. The configuration also sets up S3 bucket logging for `my-private-bucket` to send its logs to `my-logging-bucket`, specifying a log file prefix.

Note that this configuration assumes you have the AWS provider configured in your Terraform setup. Make sure to replace the `us-west-2` region with your desired region. Also, ensure that you have the necessary AWS credentials set up in your Terraform environment.

