**Terraform Configuration Description**

This Terraform configuration will create the following resources:

1. A VPC with public and private subnets
2. An EC2 Fleet with a combination of 5 On-Demand and 4 Spot Instances
3. A Launch Template to configure the EC2 instances

**Terraform HCL Program**
```terraform
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

# Create public and private subnets
resource "aws_subnet" "public" {
  cidr_block              = "10.0.1.0/24"
  vpc_id                  = aws_vpc.example.id
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  cidr_block              = "10.0.2.0/24"
  vpc_id                  = aws_vpc.example.id
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = false
}

# Create an EC2 Fleet with On-Demand and Spot Instances
resource "aws_ec2_fleet" "example" {
  name               = "example-ec2-fleet"
  instance_type       = "t3.xlarge"
  launch_template_id  = aws_launch_template.example.id
  termination_policies = ["Default"]

  on_demand_options {
    allocation_strategy = "lowest-price"
  }

  spot_options {
    allocation_strategy = "lowest-price"
  }

  instance_requirements {
    instance_types = ["t3.xlarge", "c5.xlarge"]
  }
}

# Create a Launch Template
resource "aws_launch_template" "example" {
  name           = "example-launch-template"
  description    = "Example Launch Template"
  image_id       = "ami-abcd1234" // AWS Linux 2 AMI ID

  instance_type = "t3.xlarge"

  network_settings {
    vpc_security_group_ids = [aws_security_group.example.id]
  }
}

# Create a Security Group for the EC2 instances
resource "aws_security_group" "example" {
  name        = "example-security-group"
  description = "Example Security Group"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```
Note that you should replace `ami-abcd1234` with the actual AWS Linux 2 AMI ID for your region. Also, make sure to configure the provider with your AWS credentials and region.

