**Terraform Program Description**

This Terraform program will create a VPC with three subnets, each with its own specific purpose:
1. `public_subnet` - accessible via the internet for web servers
2. `private_app_subnet` - isolated for application servers
3. `private_db_subnet` - isolated for the RDS database

The program will also create an EC2 instance in the `public_subnet` to host web servers, an EC2 instance in the `private_app_subnet` to host application servers, and an RDS instance in the `private_db_subnet` to serve as the database.

**Terraform HCL Program**
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
  access_key = "YOUR_ACCESS_KEY"
  secret_key = "YOUR_SECRET_KEY"
}

# Create a VPC
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "example-vpc"
  }
}

# Create public subnet
resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = true
  tags = {
    Name = "public-subnet"
  }
}

# Create private subnets
resource "aws_subnet" "private_app" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "private-app-subnet"
  }
}

resource "aws_subnet" "private_db" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-west-2c"
  tags = {
    Name = "private-db-subnet"
  }
}

# Create Internet Gateway and attach it to the VPC
resource "aws_internet_gateway" "example" {
  vpc_id = aws_vpc.example.id
  tags = {
    Name = "example-igw"
  }
}

resource "aws_vpc_attachment" "example" {
  vpc_id        = aws_vpc.example.id
  internet_gateway_id = aws_internet_gateway.example.id
}

# Create Security Group for EC2 instance
resource "aws_security_group" "example" {
  name        = "example-sg"
  description = "Allow inbound traffic"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create EC2 instance in public subnet
resource "aws_instance" "web" {
  ami           = "ami-abc123"
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.public.id
  vpc_security_group_ids = [aws_security_group.example.id]
  key_name = "example-key"
}

# Create EC2 instance in private subnet
resource "aws_instance" "app" {
  ami           = "ami-abc123"
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.private_app.id
  vpc_security_group_ids = [aws_security_group.example.id]
  key_name = "example-key"
}

# Create RDS instance in private subnet
resource "aws_db_instance" "example" {
  allocated_storage = 20
  engine           = "mysql"
  instance_class   = "db.t2.micro"
  name             = "example-db"
  username         = "example-user"
  password         = "example-password"
  subnet_id        = aws_subnet.private_db.id
  vpc_security_group_ids = [aws_security_group.example.id]
}

# Create IAM roles as needed
resource "aws_iam_role" "example" {
  name        = "example-role"
  description = "example-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

