**Terraform Program Description**

This Terraform program will create an AWS VPC with private subnets, two EC2 instances running the newest AWS Linux 2 AMI, and an Elastic File System (EFS) for shared storage. The EC2 instances will be launched in the private subnets and will mount the EFS file system.

**Terraform HCL Program**
```hcl
provider "aws" {
  region = "us-west-2"
}

# Create VPC with private subnets
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create EFS file system
resource "aws_efs_file_system" "example" {
  creation_token = "exampleefs"
  performance_mode = "generalPurpose"
}

# Create EC2 instances in private subnet
resource "aws_security_group" "example" {
  vpc_id = aws_vpc.example.id
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "example" {
  ami           = "ami-0c94855ba95c71c99" # Newest AWS Linux 2 AMI
  instance_type = "t2.micro"
  vpc_security_group_ids = [aws_security_group.example.id]
  subnet_id = aws_subnet.private.id
  ebs_block_device {
    device_name = "/dev/sda1"
    volume_type = "gp2"
    throughput = "100"
  }
  user_data = <<EOF
#!/bin/bash
sudo yum install -y amazon-efs-utils
sudo mount -t efs fs-12345678:/ /mnt/efs
EOF
}

resource "aws_instance" "example2" {
  ami           = "ami-0c94855ba95c71c99" # Newest AWS Linux 2 AMI
  instance_type = "t2.micro"
  vpc_security_group_ids = [aws_security_group.example.id]
  subnet_id = aws_subnet.private.id
  ebs_block_device {
    device_name = "/dev/sda1"
    volume_type = "gp2"
    throughput = "100"
  }
  user_data = <<EOF
#!/bin/bash
sudo yum install -y amazon-efs-utils
sudo mount -t efs fs-12345678:/ /mnt/efs
EOF
}
```
Note that I've used the `aws_efs_file_system` resource to create an EFS file system, and the `aws_instance` resource to create the two EC2 instances. I've also used the `aws_security_group` resource to create a security group that allows incoming traffic on port 22 and allows all outgoing traffic. The `user_data` argument is used to mount the EFS file system on the EC2 instances.

