Here is a Terraform program that creates a Memcached Cluster in AWS.

### Terraform Configuration for Memcached Cluster

```hcl
# File: main.tf

# Configure the AWS Provider
provider "aws" {
  region                  = "us-west-2"
  shared_credentials_file = "~/.aws/credentials"
  profile                 = "default"
}

# Create an IAM role for the Memcached Cluster
resource "aws_iam_role" "memcached_cluster" {
  name        = "memcached-cluster-role"
  description = "IAM role for the Memcached Cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the Memcached Cluster
resource "aws_iam_policy" "memcached_cluster_policy" {
  name        = "memcached-cluster-policy"
  description = "IAM policy for the Memcached Cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "memcached:CreateCluster",
          "memcached:DescribeClusters",
          "memcached:ListClusters",
          "memcached:UpdateCluster",
          "memcached:DeleteCluster",
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "memcached_cluster_attach" {
  role       = aws_iam_role.memcached_cluster.name
  policy_arn = aws_iam_policy.memcached_cluster_policy.arn
}

# Create the Memcached Cluster
resource "aws_memcached_cluster" "example" {
  count      = 1
  cluster_id = "example-cluster"
  member_count = 1
  preferred_availability_zones = ["us-west-2a"]
  parameter = [
    {
      name = "maxconns"
      value = "1024"
    },
    {
      name = "no-block"
      value = "yes"
    }
  ]
  port = 11211

  vpc_endpoint {
    vpc_id       = "vpc-12345678"
  }

  iam_roleArn = aws_iam_role.memcached_cluster.arn
}
```

### Instructions

1. Make sure you have the AWS CLI installed and configured on your machine.
2. Replace `"vpc-12345678"` with the ID of your VPC.
3. Save this configuration in a file named `main.tf`.
4. Run `terraform init` to initialize the provider.
5. Run `terraform apply` to create the Memcached Cluster.

### Variables

* `aws_region`: The region in which to create the Memcached Cluster (default: `us-west-2`)
* `vpc_id`: The ID of the VPC in which to create the Memcached Cluster
* `preferred_availability_zones`: The preferred availability zones for the Memcached Cluster (default: `["us-west-2a", "us-west-2b"]`)
* `parameter`: A list of parameters for the Memcached Cluster (default: `[]`)
* `port`: The port number for the Memcached Cluster (default: `11211`)
* `member_count`: The number of nodes in the Memcached Cluster (default: `1`)

