Here is the Terraform program to create a Redis instance:

```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM Role for the Redis instance
resource "aws_iam_role" "redis_role" {
  name        = "redis-instance-role"
  description = "Role for the Redis instance"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redis.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM Policy for the Redis instance
resource "aws_iam_policy" "redis_policy" {
  name        = "redis-instance-policy"
  description = "Policy for the Redis instance"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "redis:Get"
        ]
        Effect = "Allow"
        Resource = "arn:aws:elasticache:us-west-2:*:cluster:my-redis-cluster"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "redis_attach" {
  role       = aws_iam_role.redis_role.name
  policy_arn = aws_iam_policy.redis_policy.arn
}

# Create a Redis instance
resource "aws_elasticache_cluster" "redis_instance" {
  cluster_id       = "my-redis-cluster"
  engine           = "redis"
  node_type        = "cache.t2.micro"
  num_cache_nodes  = 1
  parameter_group_name = "default.redis6.x"
  port              = 6379

  vpc_security_group_ids = [aws_security_group.redis_sg.id]
}

# Create a security group for the Redis instance
resource "aws_security_group" "redis_sg" {
  name        = "redis-security-group"
  description = "Security group for the Redis instance"

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Output the Redis instance details
output "redis_endpoint" {
  value = aws_elasticache_cluster.redis_instance.cache_cluster_id
}
```

This configuration creates:

* An IAM role and policy for the Redis instance
* A Redis instance with a single node and a security group to allow incoming connections
* Outputs the Redis instance details (cache cluster ID)

