      {
        Action = [
          "elasticache:CreateCacheCluster",
          "elasticache:CreateCacheParameterGroup",
          "elasticache:CreateCacheSubnetGroup",
          "elasticache:DescribeCacheClusters",
          "elasticache:DescribeCacheClusters",
          "elasticache:DescribeCacheParameters",
          "elasticache:DescribeCacheSubnetGroups",
          "elasticache:DescribeEngineDefaultParameters",
          "elasticache:ModifyCacheCluster",
          "elasticache:ModifyCacheParameterGroup",
          "elasticache:ModifyCacheSubnetGroup",
          "elasticache:RebootCacheCluster",
          "elasticache:UpdateCacheCluster",
          "elasticache:UpdateCacheParameterGroup",
          "elasticache:UpdateCacheSubnetGroup"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "cache-attachment" {
  role       = aws_iam_role.cache-role.name
  policy_arn = aws_iam_policy.cache-policy.arn
}

# Create an ElastiCache user with password
resource "aws_elasticache_user" "user" {
  name      = "myuser"
  password  = "mypass"
  cluster_id = aws_elasticache_cluster.cluster.id
}

# Create an ElastiCache cluster
resource "aws_elasticache_cluster" "cluster" {
  cluster_id           = "mycluster"
  engine               = "redis"
  port                 = 6379
  num_cache_nodes      = 1
  preferred_availability_zone = "us-west-2a"

  iam_role_name = aws_iam_role.cache-role.name
}
```
Note: This configuration assumes you have the AWS provider configured with the necessary credentials. Also, be sure to update the `cluster_id`, `name`, and `password` variables to suit your specific requirements.

