**Description of the Terraform Program**

This Terraform configuration will create a single-node Amazon RedShift cluster. The cluster will be created in the `us-east-1` region, which is one of the available regions for RedShift.

The configuration will create the following resources:

* A VPC to host the RedShift cluster
* An IAM role for the RedShift cluster to access S3
* An Amazon RedShift cluster with a single node
* The necessary security groups and cluster parameters

**Terraform HCL Program**
```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  default = "my-redshift-cluster"
}

variable "cluster_identifier" {
  default = "my-redshift-cluster"
}

variable "cluster_type" {
  default = "single-node"
}

variable "master_username" {
  default = "myuser"
}

variable "master_password" {
  default = "mypassword"
}

variable "node_type" {
  default = "dc2.large"
}

variable "cluster_database_name" {
  default = "mydb"
}

# Create a VPC to host the RedShift cluster
resource "aws_vpc" "redshift_vpc" {
  cidr_block = "10.0.0.0/16"
}

# Create an IAM role for the RedShift cluster to access S3
resource "aws_iam_role" "redshift_role" {
  name = "redshift-s3-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "redshift_s3_policy" {
  name = "redshift-s3-policy"
  role = aws_iam_role.redshift_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "s3:GetObject"
        Resource = "arn:aws:s3:::*"
      }
    ]
  })
}

# Create an Amazon RedShift cluster
resource "aws_redshift_cluster" "my_cluster" {
  cluster_identifier = var.cluster_identifier
  database_name      = var.cluster_database_name
  cluster_type       = var.cluster_type
  node_type          = var.node_type
  master_username    = var.master_username
  master_password    = var.master_password
  vpc_security_group_ids = [aws_security_group.redshift_security_group.id]
  vpc_id             = aws_vpc.redshift_vpc.id
  iam_roles = [aws_iam_role.redshift_role.arn]
}

# Create a security group for the RedShift cluster
resource "aws_security_group" "redshift_security_group" {
  name        = "redshift-security-group"
  description = "Security group for RedShift cluster"
  vpc_id      = aws_vpc.redshift_vpc.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```
Note that you should replace the default values of the variables (e.g., `cluster_name`, `master_username`, etc.) with your own values. Also, make sure to configure the provider and region as described above.

