  cluster_identifier      = var.redshift_cluster_identifier
  cluster_type            = "multi-node"
  cluster_instance_count  = 2
  cluster_parameter_group_name = "my-redshift-parameter-group"
  iam_role_arn            = aws_iam_role.redshift_role.arn
  vpc_security_group_ids = [aws_security_group.my_redshift_security_group.id]
  publicly_accessible     = true

  concurrency_scaling {
    enabled  = true
    threshold  = 60
  }
}

# Create a VPC security group for the RedShift cluster
