Here is the Terraform program to setup a 2 node RedShift cluster in us-east-1 and replicate it to us-east-2:

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-east-1"
}

# Define a variable for the cluster name
variable "cluster_name" {
  default = "my-redshift-cluster"
}

# Create a new IAM role for RedShift
resource "aws_iam_role" "redshift_role" {
  name        = "${var.cluster_name}-redshift-role"
  description = "For Amazon RedShift cluster"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Effect": "Allow",
      "Principal": {
        "Service": "redshift.amazonaws.com"
      }
    }
  ]
}
EOF
}

# Create a new IAM role policy for RedShift
resource "aws_iam_role_policy" "redshift_policy" {
  name   = "${var.cluster_name}-redshift-policy"
  role   = aws_iam_role.redshift_role.id

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "s3:GetObject",
      "Effect": "Allow",
      "Resource": "${aws_s3_bucket.cluster_bucket.arn}/*"
    },
    {
      "Action": "s3:PutObject",
      "Effect": "Allow",
      "Resource": "${aws_s3_bucket.cluster_bucket.arn}/*"
    }
  ]
}
EOF
}

# Create a new S3 bucket for RedShift
resource "aws_s3_bucket" "cluster_bucket" {
  bucket = "${var.cluster_name}-redshift-bucket"

  acl           = "private"
  versioning {
    enabled = true
  }
}

# Create a new RedShift cluster
resource "aws_redshift_cluster" "cluster" {
  cluster_identifier = var.cluster_name
  cluster_type      = "single-node"
  cluster_subnet_group_name = "default"
  node_type           = "ds2.xlarge"
  master_username     = "admin"
  master_password     = "your_master_password"

  iam_roles = [aws_iam_role.redshift_role.arn]

  tags = {
    Name        = var.cluster_name
    Environment = "dev"
  }
}

# Create a new RedShift cluster in us-east-2 (replica)
resource "aws_redshift_cluster" "cluster_replica" {
  provider = aws.us-east-2

  cluster_identifier = "${var.cluster_name}-replica"
  cluster_type      = "single-node"
  cluster_subnet_group_name = "default"
  node_type           = "ds2.xlarge"
  master_username     = "admin"
  master_password     = "your_master_password"

  iam_roles = [aws_iam_role.redshift_role.arn]

  tags = {
    Name        = "${var.cluster_name}-replica"
    Environment = "dev"
  }
}
```

This configuration creates a 2-node RedShift cluster in us-east-1, and a replica of the cluster in us-east-2. It also creates an IAM role and policy for RedShift, and an S3 bucket to store data. Please replace `your_master_password` with the actual password.

Please note that the password is hardcoded in the Terraform configuration for simplicity. In a real-world scenario, you should use a secret management system to store and retrieve sensitive data like passwords.

Also, the provider for the replica cluster is specified as `aws.us-east-2` to create the cluster in the us-east-2 region.

This configuration is deployable and should be used with caution. Make sure to test it in a non-production environment before deploying it to production.

