  name        = "redshift-policy"
  description = "RedShift cluster IAM policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "redshift:DescribeClusters",
          "redshift:DescribeClustersMembership",
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
