**Terraform Program Description**

The Terraform program will create the following AWS resources:

* An IAM role with a policy document that allows the role to be assumed by the Lambda function
* An AWS Lambda function with a specific runtime (nodejs18.x) and handler
* An archive file for the Lambda function code

**Terraform HCL Program**

```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the Lambda function
resource "aws_iam_role" "lambda_exec_role" {
  name        = "lambda-exec-role"
  description = "Execution role for Lambda function"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy document for the Lambda function
resource "aws_iam_policy" "lambda_exec_policy" {
  name        = "lambda-exec-policy"
  description = "Policy for Lambda function execution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "logs:CreateLogGroup"
        Effect = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      },
      {
        Action = "logs:CreateLogStream"
        Effect = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      },
      {
        Action = "logs:PutLogEvents"
        Effect = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

# Attach the IAM policy to the Lambda execution role
resource "aws_iam_role_policy_attachment" "lambda_exec_attach" {
  role       = aws_iam_role.lambda_exec_role.name
  policy_arn = aws_iam_policy.lambda_exec_policy.arn
}

# Create an AWS Lambda function
resource "aws_lambda_function" "lambda_function" {
  filename      = "lambda.js"
  function_name = "lambda-function"
  handler       = "lambda.handler"
  runtime       = "nodejs18.x"
  role          = aws_iam_role.lambda_exec_role.arn

  depends_on = [aws_iam_role_policy_attachment.lambda_exec_attach]
}

# Upload the Lambda function code
resource "aws_lambda_function" "lambda_function_code" {
  filename         = "lambda.js"
  function_name    = aws_lambda_function.lambda_function.function_name
  handler          = aws_lambda_function.lambda_function.handler
  runtime          = aws_lambda_function.lambda_function.runtime
  role             = aws_iam_role.lambda_exec_role.arn
  source_code_hash = filebase64sha256("lambda.js")
}

# Output the Lambda function ARN
output "lambda_function_arn" {
  value       = aws_lambda_function.lambda_function.arn
  description = "The ARN of the Lambda function"
}
```

**Note:**

* Make sure to replace `"lambda.js"` with the actual path to your Lambda function code file.
* This Terraform configuration assumes you have the AWS Provider configured with the correct credentials and region.
* This configuration creates an IAM role, policy, and policy attachment for the Lambda function. The Lambda function is created with a specific runtime, handler, and role.
* The `source_code_hash` attribute is set using the `filebase64sha256` function to upload the Lambda function code.

