  policy_arn = aws_iam_policy.lambda_policy.arn
}

# Create a Lambda function
resource "aws_lambda_function" "example_lambda" {
  filename      = "lambda_function_payload.zip"
  function_name = "example-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"

  role = aws_iam_role.lambda_exec.arn
}

# Create a DynamoDB table
resource "aws_dynamodb_table" "example_table" {
  name           = "example-table"
  billing_mode   = "PAY_PER_REQUEST"
  read_capacity_units = 5
  write_capacity_units = 5

  attribute {
    name = "id"
    type = "S"
  }
}

# Create an event source mapping for the Lambda function
resource "aws_lambda_event_source_mapping" "example_mapping" {
  event_source_arn = aws_dynamodb_table.example_table.stream_arn
  function_name    = aws_lambda_function.example_lambda.arn
  enabled          = true
}
```
Note that you will need to replace the `filename` attribute of the `aws_lambda_function` resource with the path to your own Lambda function code.

