Here is a Terraform program that creates an IAM role, triggers a Lambda function when an EC2 image is created, and provides a valid provider configuration.

### Terraform Configuration

```hcl
# File: main.tf

# Set AWS region and provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the Lambda function
resource "aws_iam_role" "lambda_role" {
  name = "lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the Lambda function
resource "aws_iam_policy" "lambda_policy" {
  name        = "lambda-execution-policy"
  description = "Policy for lambda execution"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "LambdaExecutionPolicy"
        Effect    = "Allow"
        Action    = ["logs:*"]
        Resource  = "*"
      }
    ]
  })
}

# Attach IAM policy to the role
resource "aws_iam_role_policy_attachment" "lambda_attach" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = aws_iam_policy.lambda_policy.arn
}

# Define the Lambda function
resource "aws_lambda_function" "test_lambda" {
  filename      = "lambda_function_payload.zip"
  function_name = "test-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_role.arn
}

# Trigger the Lambda function when an EC2 image is created
resource "aws_cloudwatch_event_target" "lambda_trigger" {
  rule      = "ec2-image-created"
  target_id = "LambdaFunction"
  arn       = aws_lambda_function.test_lambda.arn
}

# Create an event pattern for EC2 image creation
resource "aws_cloudwatch_event_rule" "ec2_event_rule" {
  name        = "ec2-image-created"
  event_pattern = jsonencode({
    source     = ["aws.ec2"]
    detail-type = ["EC2 Instance State-change Notification"]
    detail = jsonencode({
      state = ["pending"]
      detail-type = ["EC2 Instance State-change Notification"]
      detail = jsonencode({
        instance-id = "i-12345678"
      })
    })
  })
}

# Trigger the Lambda function on EC2 image creation
resource "aws_cloudwatch_event_target" "lambda_trigger_ec2" {
  rule      = aws_cloudwatch_event_rule.ec2_event_rule.name
  target_id = "LambdaFunctionEC2"
  arn       = aws_lambda_function.test_lambda.arn
}
```

### Important

- Make sure to replace `"lambda_function_payload.zip"` with the actual path to your Lambda function zip file.
- Replace `"us-west-2"` with your desired AWS region.
- Make sure you have the AWS CLI configured with your AWS credentials. 

This Terraform configuration will create an IAM role and policy for the Lambda function, define the Lambda function, and trigger it whenever an EC2 image is created.

