**Description:**
The Terraform program will create a CloudWatch Metric Alarm resource that monitors the CPU utilization of an EC2 instance. The alarm will send an email notification to the administrator when the CPU utilization exceeds 80%. The program will use AWS as the provider and specify the region as 'us-west-2'.

**Terraform HCL Program:**
```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an EC2 instance (assuming it already exists)
resource "aws_instance" "example" {
  ami           = "ami-abc123"
  instance_type = "t2.micro"
}

# Create a CloudWatch Metric Alarm
resource "aws_cloudwatch_metric_alarm" "example" {
  alarm_name                = "HighCPUAlarm"
  comparison_operator       = "GREATER_THAN_OR_EQUAL_TO"
  evaluation_periods        = 1
  metric_name               = "CPUUtilization"
  namespace                 = "AWS/EC2"
  period                    = 300
  statistic                 = "Average"
  threshold                 = 80
  actions_enabled           = true
  alarm_actions             = [aws_sns_topic.example.arn]
  insufficient_data_actions = []

  dimensions = {
    AutoScalingGroupName = aws_autoscaling_group.example.name
  }
}

# Create an SNS topic for notifications
resource "aws_sns_topic" "example" {
  name = "HighCPUAlarmTopic"
}

# Create an IAM role for the SNS topic
resource "aws_iam_role" "sns_topic_exec_role" {
  name        = "sns_topic_exec_role"
  description = "Execution role for SNS topic"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
      },
    ]
  })
}

# Attach the IAM role to the SNS topic
resource "aws_sns_topic_policy" "example" {
  arn = aws_sns_topic.example.arn

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sns:Publish"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
      },
    ]
  })
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sns:Publish"
        Effect = "Allow"
        Resource = aws_sns_topic.example.arn
        Condition = {
          StringEquals = {
            "aws:SourceArn" = aws_sns_topic.example.arn
          }
        }
      },
    ]
  })
}
```
This program creates a CloudWatch Metric Alarm that monitors the CPU utilization of an EC2 instance. The alarm sends an email notification to the administrator when the CPU utilization exceeds 80%. It uses AWS as the provider and specifies the region as 'us-west-2'. Note that this program assumes that an EC2 instance and an SNS topic already exist. If not, additional Terraform code is required to create them.

