This Terraform configuration defines an AWS CloudWatch metric alarm named 'foobar' that monitors the average CPU utilization of EC2 instances. The alarm triggers when the CPU utilization exceeds 80% for two consecutive 2-minute periods. If there's insufficient data, no action is taken.

```terraform
provider "aws" {
  region = "us-west-2"
}

# Define the necessary IAM role for CloudWatch to monitor EC2 instances
resource "aws_iam_role" "foobar_alarm" {
  name        = "foobar_alarm_role"
  description = "Role for CloudWatch to monitor EC2 instances"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "foobar_alarm" {
  role       = aws_iam_role.foobar_alarm.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchReadOnlyAccess"
}

resource "aws_cloudwatch_metric_alarm" "foobar" {
  alarm_name          = "foobar"
  comparison_operator = "GE"
  evaluation_periods  = "2"
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  period              = "2"
  statistic           = "Average"
  threshold           = "80"
  actions_enabled     = false

  dimensions = {
    AutoScalingGroupName = "default"
  }

  alarm_description = "Triggered when average CPU utilization exceeds 80% for 2 consecutive 2-minute periods"
  alarm_actions     = []
}
```

This Terraform configuration defines an IAM role for CloudWatch to monitor EC2 instances and an AWS CloudWatch metric alarm named 'foobar'. The alarm triggers when the average CPU utilization exceeds 80% for two consecutive 2-minute periods. No action is taken when there's insufficient data. The IAM role allows CloudWatch to read EC2 metrics.

