**Terraform Program Description:**
The Terraform program will create the necessary AWS resources to configure a Kinesis Streaming Destination for a specified DynamoDB table. This includes:

* A Kinesis stream to capture changes to the DynamoDB table
* A Kinesis stream consumer to read from the Kinesis stream
* An IAM role to allow Kinesis to read from the DynamoDB table
* A DynamoDB table (assuming it does not already exist)

**Terraform HCL Program:**
```hcl
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Define the DynamoDB table
resource "aws_dynamodb_table" "example_table" {
  name         = "example-table"
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "name"
    type = "S"
  }
}

# Define the Kinesis stream
resource "aws_kinesis_stream" "example_stream" {
  name = "example-stream"
  shard_count = 1
}

# Define the IAM role for Kinesis to read from DynamoDB
resource "aws_iam_role" "kinesis_dynamo_role" {
  name        = "kinesis-dynamo-role"
  description = "Allow Kinesis to read from DynamoDB"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesis.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policy to IAM role
resource "aws_iam_role_policy" "kinesis_dynamo_policy" {
  role = aws_iam_role.kinesis_dynamo_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "dynamodb:GetRecords"
        Effect = "Allow"
        Resource = aws_dynamodb_table.example_table.arn
      }
    ]
  })
}

# Define the Kinesis stream consumer
resource "aws_kinesis_stream_consumer" "example_consumer" {
  name       = "example-consumer"
  stream_name = aws_kinesis_stream.example_stream.name
  role_arn    = aws_iam_role.kinesis_dynamo_role.arn
}

# Configure the DynamoDB table to stream to Kinesis
resource "aws_dynamodb_table_stream" "example_stream" {
  table_name = aws_dynamodb_table.example_table.name
  enabled    = true

  dynamo_to_kinesis {
    destination_stream_arn = aws_kinesis_stream.example_stream.arn
    role_arn               = aws_iam_role.kinesis_dynamo_role.arn
  }
}
```
This Terraform program creates the necessary resources to configure a Kinesis Streaming Destination for the specified DynamoDB table. It defines the DynamoDB table, Kinesis stream, IAM role, and Kinesis stream consumer. The DynamoDB table is configured to stream to the Kinesis stream using the `dynamodb_to_kinesis` block.

