# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
  default_tags {
    Tags = {
      Environment = "dev"
    }
  }
}

# DynamoDB Table
resource "aws_dynamodb_table_item" "example" {
  table_name = "example-table"
  hash_key    = "id"

  # Attribute definitions
  attribute_definitions = [
    {
      attribute_name = "id"
      attribute_type = "S"
    },
    {
      attribute_name = "name"
      attribute_type = "S"
    },
    {
      attribute_name = "email"
      attribute_type = "S"
    },
