**Description of the Terraform Program:**

This Terraform program will create a DynamoDB Global Table, which is a feature of DynamoDB that allows you to replicate your table data across multiple regions. The program will first create a DynamoDB table in the primary region, and then create a replica of the table in a secondary region. The Terraform program will use the AWS provider to interact with the AWS services.

**Terraform HCL Program:**
```terraform
provider "aws" {
  region = "us-west-2" # primary region
}

variable "table_name" {
  default = "my-table"
}

variable "primary_region" {
  default = "us-west-2"
}

variable "replica_region" {
  default = "us-east-1"
}

resource "aws_dynamodb_table" "global_table" {
  name         = var.table_name
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "name"
    type = "S"
  }

  key_schema = [
    {
      attribute_name = "id"
      key_type       = "HASH"
    },
    {
      attribute_name = "name"
      key_type       = "RANGE"
    }
  ]

  table_status = "ACTIVE"
}

resource "aws_dynamodb_global_table" "global_table_replica" {
  name      = var.table_name
  primary   = aws_dynamodb_table.global_table.name
  regions = [
    var.replica_region
  ]

  replicas = [
    {
      region = var.replica_region
    }
  ]

  depends_on = [aws_dynamodb_table.global_table]
}

output "global_table_arn" {
  value = aws_dynamodb_table.global_table.arn
}

output "global_table_replica_arn" {
  value = aws_dynamodb_global_table.global_table_replica.replica[0].arn
}
```
This Terraform program uses the `aws` provider to create a DynamoDB table and a DynamoDB Global Table replica. The `aws_dynamodb_table` resource creates the primary table in the primary region, and the `aws_dynamodb_global_table` resource creates a replica of the table in the secondary region. The `depends_on` argument is used to ensure that the global table replica is created only after the primary table has been created. The output values are set to the ARNs of the global table and its replica.

