# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create a new IAM role for Sagemaker
resource "aws_iam_role" "sagemaker-execution-role" {
  name        = "SagemakerExecutionRole"
  description = "Execution role for Sagemaker"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

# Create a new IAM policy for Sagemaker
resource "aws_iam_policy" "sagemaker-execution-policy" {
  name        = "SagemakerExecutionPolicy"
  description = "Execution policy for Sagemaker"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect = "Allow"
        Resource = ["arn:aws:s3:::your-bucket-name"]
      }
    ]
  })
}

# Attach the IAM policy to the role
resource "aws_iam_role_policy_attachment" "sagemaker-execution-policy-attachment" {
  role       = aws_iam_role.sagemaker-execution-role.name
  policy_arn = aws_iam_policy.sagemaker-execution-policy.arn
}

# Create a new Sagemaker Space
resource "aws_sagemaker_space" "example-space" {
  name          = "example-space"
  description   = "Example Sagemaker Space"
  role_arn      = aws_iam_role.sagemaker-execution-role.arn
  kms_key_id    = "your-kms-key-id"
  tags          = {
    Environment = "dev"
  }
}

# Save your AWS credentials as environment variables
# AWS_ACCESS_KEY_ID
# AWS_SECRET_ACCESS_KEY
```
Note: Replace `"your-bucket-name"` with your actual S3 bucket name, and `"your-kms-key-id"` with your actual KMS key ID.

