# Configure the AWS Provider
provider "aws" {
  region = "us-east-1"
  version = "3.47.0"
}

# Create an IAM role for the pipeline
resource "aws_iam_role" "pipeline_role" {
  name        = "SageMakerPipelineRole"
  description = "Role for SageMaker Pipeline"

