**Terraform Program Description**

This Terraform program will create a SageMaker Human Task UI resource from a pre-defined template file. The template file, `sagemaker-human-task-ui-template.html`, will be uploaded to Amazon S3 and then used to create a Human Task UI resource in Amazon SageMaker. The Human Task UI resource will have a custom HTML template that displays the text "TEST" in an `<h1>` tag.

**Terraform HCL Program**
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an S3 bucket to store the template file
resource "aws_s3_bucket" "template_bucket" {
  bucket = "sagemaker-template-bucket"
  acl    = "private"

  tags = {
    Name = "SageMaker Template Bucket"
  }
}

# Upload the template file to S3
resource "aws_s3_object" "template" {
  bucket = aws_s3_bucket.template_bucket.id
  key    = "sagemaker-human-task-ui-template.html"
  source = file("${path.module}/sagemaker-human-task-ui-template.html")
  etag   = filemd5("${path.module}/sagemaker-human-task-ui-template.html")
}

# Create an IAM role for SageMaker
resource "aws_iam_role" "sagemaker_role" {
  name        = "SageMakerHumanTaskUIRole"
  description = "Role for SageMaker Human Task UI"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policies to the IAM role
resource "aws_iam_policy" "sagemaker_policy" {
  name        = "SageMakerHumanTaskUIPolicy"
  description = "Policy for SageMaker Human Task UI"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sagemaker:CreateHumanTaskUi",
          "sagemaker:CreateHumanTask",
          "sagemaker:CreateWorkteam",
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_attach" {
  role       = aws_iam_role.sagemaker_role.name
  policy_arn = aws_iam_policy.sagemaker_policy.arn
}

# Create a SageMaker Human Task UI resource
resource "aws_sagemaker_human_task_ui" "ui" {
  human_task_ui_name = "SageMaker Human Task UI"
  template_s3_uri = "s3://${aws_s3_bucket.template_bucket.id}/${aws_s3_object.template.id}"

  tags = {
    Name = "SageMaker Human Task UI"
  }
}
```
Note: Make sure to replace the `path.module` with the actual path to the `sagemaker-human-task-ui-template.html` file in your Terraform configuration.

