LLM Output #0:
**Terraform Program Description**

This Terraform program will create the following AWS resources:

1. An IAM role with execution role to run the Lambda function.
2. An IAM policy attached to the execution role to grant necessary permissions.
3. An AWS Lambda function with Node.js 18 runtime, source code stored in an S3 bucket, and an "index.js" handler.
4. An S3 bucket to store the Lambda function source code.

**Terraform HCL Program**
```terraform
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM execution role for the Lambda function
resource "aws_iam_role" "lambda_exec_role" {
  name        = "lambda-exec-role"
  description = "Execution role for the Lambda function"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy attached to the execution role
resource "aws_iam_policy" "lambda_exec_policy" {
  name        = "lambda-exec-policy"
  description = "Policy for the Lambda function execution role"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach the IAM policy to the execution role
resource "aws_iam_role_policy_attachment" "lambda_exec_policy_attach" {
  role       = aws_iam_role.lambda_exec_role.name
  policy_arn = aws_iam_policy.lambda_exec_policy.arn
}

# Create an S3 bucket to store the Lambda function source code
resource "aws_s3_bucket" "lambda_source_code" {
  bucket = "lambda-source-code-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }
}

# Upload the Lambda function source code to the S3 bucket
resource "aws_s3_object" "lambda_source_code_upload" {
  bucket = aws_s3_bucket.lambda_source_code.id
  key    = "lambda.js"
  source = "${path.module}/lambda.js"
  etag   = filemd5("${path.module}/lambda.js")
}

# Create the Lambda function
resource "aws_lambda_function" "lambda_function" {
  filename      = "${path.module}/lambda.js"
  function_name = "lambda-function"
  handler       = "index.handler"
  runtime       = "nodejs18.x"
  role          = aws_iam_role.lambda_exec_role.arn
  s3_bucket     = aws_s3_bucket.lambda_source_code.id
  s3_key        = aws_s3_object.lambda_source_code_upload.key
}
```
This Terraform program creates the necessary IAM role, policy, and attachments, as well as an S3 bucket to store the Lambda function source code. The Lambda function is then created with the specified handler and runtime. Make sure to replace the `path.module` with the actual path to the `lambda.js` and `index.js` files on your local machine.

