To reduce the number of database calls, we can use a Redis in-memory data store as a cache layer between the application and the database. This will store frequently accessed data in memory, allowing the application to retrieve it quickly without having to query the database.

Here is the Terraform HCL program to create a Redis instance:

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create a VPC for the Redis instance
resource "aws_vpc" "redis_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "Redis VPC"
  }
}

# Create a subnet for the Redis instance
resource "aws_subnet" "redis_subnet" {
  vpc_id            = aws_vpc.redis_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "Redis Subnet"
  }
}

# Create an IAM role for the Redis instance
resource "aws_iam_role" "redis_role" {
  name        = "RedisRole"
  description = "Redis IAM role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the Redis instance
resource "aws_iam_policy" "redis_policy" {
  name        = "RedisPolicy"
  description = "Redis IAM policy"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "redis:Get",
          "redis:Set",
          "redis:Delete",
        ]
        Effect = "Allow"
        Resource = "${aws_elasticache_cluster.redis_cluster.cache_nodes.0.address}:6379"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "redis_attach" {
  role       = aws_iam_role.redis_role.name
  policy_arn = aws_iam_policy.redis_policy.arn
}

# Create a Redis cluster
resource "aws_elasticache_cluster" "redis_cluster" {
  cluster_id          = "redis-cluster"
  engine               = "redis"
  node_type            = "cache.t2.micro"
  num_cache_nodes      = 1
  parameter_group_name = "default.redis6.x"
  port                 = 6379
  vpc_security_group_ids = [aws_security_group.redis_sg.id]
  subnet_group_name = "redis-subnet-group"
}

# Create a security group for the Redis instance
resource "aws_security_group" "redis_sg" {
  name        = "RedisSecurityGroup"
  description = "Redis Security Group"

  vpc_id = aws_vpc.redis_vpc.id

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }
}
```

This configuration creates a VPC, subnet, IAM role, IAM policy, and Redis cluster. The Redis cluster uses a cache.t2.micro node type and has one cache node. The IAM policy allows Redis operations on the cache node. The security group allows incoming traffic on port 6379 from the VPC's CIDR block. The Redis cluster is created in the specified VPC and subnet.

