Here is a Terraform HCL program that defines an Amazon DynamoDB Global Table cluster with dax.r4.large instances and a replication factor of 1.

```hcl
# Define the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Define the DynamoDB table
resource "aws_dynamodb_table" "example" {
  name           = "example-table"
  billing_mode   = "PAY_PER_REQUEST"
  read_capacity  = 1
  write_capacity = 1
  hash_key       = "id"
  attribute {
    name = "id"
    type = "S"
  }
}

# Define the DAX cluster
resource "aws_dax_cluster" "example" {
  name            = "example-cluster"
  dax_cluster_instance_type = "dax.r4.large"
  iam_role_name  = "example-dax-iam-role"
  iam_role_arn  = aws_iam_role.example.arn
  replication_factor = 1
  s3_key_prefix = "dax-cluster-example"
}

# Define the DAX cluster IAM role
resource "aws_iam_role" "example" {
  name        = "example-dax-iam-role"
  description = "DAX cluster IAM role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
      },
    ]
  })
}

# Policy for DAX cluster IAM role
resource "aws_iam_policy" "example" {
  name        = "example-dax-policy"
  description = "DAX cluster IAM policy"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem",
        ]
        Resource = aws_dynamodb_table.example.arn
        Effect    = "Allow"
      },
    ]
  })
}

# Attach policy to IAM role
resource "aws_iam_role_policy_attachment" "example" {
  role       = aws_iam_role.example.name
  policy_arn = aws_iam_policy.example.arn
}
```

This configuration will create an Amazon DynamoDB Global Table cluster with dax.r4.large instances and a replication factor of 1. It defines the necessary IAM roles, policies, and attachments to allow DAX to interact with the DynamoDB table.

