```hcl
# Define the AWS provider
provider "aws" {
  region = "us-west-2"
  default_tags {
    Environment = "dev"
  }
}

# Define the MSK cluster
resource "aws_msk_cluster" "example" {
  cluster_name           = "example-msk-cluster"
  number_of_broker_nodes = 3
  kafka_version          = "KAFKA_2_6_0"
  instance_type          = "kafka.m5.large"

  vpc_settings {
    subnet_ids = [
      aws_subnet.example-a.id,
      aws_subnet.example-b.id,
      aws_subnet.example-c.id
    ]
  }
}

# Define the subnets for the VPC
resource "aws_subnet" "example-a" {
  cidr_block = "10.0.1.0/24"
  vpc_id     = aws_vpc.example.id
  availability_zone = "us-west-2a"

  tags = {
    Name = "example-a"
  }
}

resource "aws_subnet" "example-b" {
  cidr_block = "10.0.2.0/24"
  vpc_id     = aws_vpc.example.id
  availability_zone = "us-west-2b"

  tags = {
    Name = "example-b"
  }
}

resource "aws_subnet" "example-c" {
  cidr_block = "10.0.3.0/24"
  vpc_id     = aws_vpc.example.id
  availability_zone = "us-west-2c"

  tags = {
    Name = "example-c"
  }
}

# Define the VPC
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "example"
  }
}
```

This Terraform configuration defines a single MSK cluster with 3 broker nodes, using AWS as the provider. The configuration also defines the necessary subnets and VPC for the MSK cluster. Make sure to replace the `aws_vpc.example.id` with the correct VPC ID in the `aws_subnet` resources if you already have a VPC created.

