Here is the Terraform program that creates a managed MSK cluster with 3 broker nodes in the us-east1 region:

```
# Configure the AWS provider
provider "aws" {
  region = "us-east1" # Note: us-east1 is not a valid region in AWS, but it will be used as a placeholder for demonstration purposes.
  version = "3.28.0"
}

# Define a variable for the MSK cluster name
variable "cluster_name" {
  type        = string
  default     = "managed-msk-cluster"
  description = "The name of the MSK cluster"
}

# Create an IAM role for the MSK cluster
resource "aws_iam_role" "msk_role" {
  name        = "${var.cluster_name}-msk-role"
  description = "The IAM role for the MSK cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}

# Create an IAM policy for the MSK cluster
resource "aws_iam_policy" "msk_policy" {
  name        = "${var.cluster_name}-msk-policy"
  description = "The IAM policy for the MSK cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kafka:CreateCluster",
          "kafka:DeleteCluster",
          "kafka:UpdateCluster",
          "kafka:DescribeCluster",
          "kafka:ListClusters",
        ]
        Resource = "arn:aws:kafka:us-east1:*:cluster:${var.cluster_name}"
        Effect    = "Allow"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "msk_attach" {
  role       = aws_iam_role.msk_role.name
  policy_arn = aws_iam_policy.msk_policy.arn
}

# Create a managed MSK cluster
resource "aws_msk_cluster" "example" {
  cluster_name         = var.cluster_name
  kafka_version        = "KAFKA_2.6.1_2.7.0"
  number_of_broker_nodes = 3
  vpc_ids              = [aws_vpc.default.id]
  availability_zones  = ["us-east1a", "us-east1b", "us-east1c"]
  storage_info {
    sns_topic_arn = aws_sns_topic.example.arn
  }
}

# Note: The above resources require AWS SNS topic to be created manually.
# It will not create SNS topic, instead, you should use the existing one.
```
Please note that the region should be set to "us-east1b" or "us-east1c" as these are the valid regions for AWS Managed MSK in AWS. "us-east1" is not a valid region in AWS. I have kept it as a placeholder for demonstration purposes.

