Here is the Terraform HCL program to create a managed MSK cluster with 3 broker nodes in us-east-2:

```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-east-2"
}

# Define the variables
variable "cluster_name" {
  type        = string
  default     = "msk-cluster"
  description = "The name of the MSK cluster"
}

# Create the IAM role for the MSK cluster
resource "aws_iam_role" "msk_role" {
  name        = "${var.cluster_name}-msk-role"
  description = "The IAM role for the MSK cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

# Create the IAM policy for the MSK cluster
resource "aws_iam_policy" "msk_policy" {
  name        = "${var.cluster_name}-msk-policy"
  description = "The IAM policy for the MSK cluster"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kafka:CreateCluster",
          "kafka:DeleteCluster",
          "kafka:DescribeCluster",
          "kafka:DescribeClusterInstance",
          "kafka:GetConfiguration",
          "kafka:ListClusters",
          "kafka:UpdateCluster",
          "kafka:CreateConfiguration",
          "kafka:DescribeConfiguration",
          "kafka:GetConfiguration",
          "kafka:ListConfigurations",
          "kafka:UpdateConfiguration",
          "kafka:CreateSnapshot",
          "kafka:DescribeSnapshot",
          "kafka:GetSnapshot",
          "kafka:ListSnapshots",
          "kafka:DeleteSnapshot",
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "msk_attach" {
  role       = aws_iam_role.msk_role.name
  policy_arn = aws_iam_policy.msk_policy.arn
}

# Create the MSK cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name       = var.cluster_name
  kafka_version      = "2.6.1"
  number_of_broker_nodes = 3
  broker_node_type    = "kafka.server.m5d.2xlarge"
  kafka_cluster_id   = "msk-cluster"
  encrypt_data_at_rest {
    enabled = true
  }
  vpc_settings {
    subnet_ids = [aws_subnet.msk_subnet.id]
  }
  configuration {
    configuration_name = "msk-cluster-config"
    config     = jsonencode({
      "property": {
        "retention.bytes": "5368709120"
      }
    })
  }
}

# Create a subnet for the MSK cluster
resource "aws_subnet" "msk_subnet" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-2a"
}

# Create a VPC for the MSK cluster
resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
}
```

This configuration creates a managed MSK cluster with 3 broker nodes in the us-east-2 region. It also creates the necessary IAM role and policy for the MSK cluster, as well as a subnet and VPC for the cluster.

