Here is the Terraform HCL program that creates a managed MSK cluster in us-east1 logging to an S3 bucket:

```hcl
provider "aws" {
  region = "us-east1"
}

variable "msk_cluster_name" {
  type        = string
  default     = "msk-cluster"
  description = "The name of the MSK cluster"
}

variable "msk_cluster_description" {
  type        = string
  default     = "MSK cluster created with Terraform"
  description = "The description of the MSK cluster"
}

variable "s3_bucket_name" {
  type        = string
  default     = "msk-logs"
  description = "The name of the S3 bucket for MSK logs"
}

resource "aws_msk_cluster" "example" {
  cluster_name          = var.msk_cluster_name
  description           = var.msk_cluster_description
  kafka_version         = "2.6.1"
  number_of_node_groups = 1
  node_group_properties {
    instance_type    = "kafka.m5.large"
    ebs_volume_config {
      volume_type = "gp2"
      size        = 10
    }
  }
  encryption_in_transit {
    use_server_ssid = true
  }
  vpc_config {
    security_group_ids = [aws_security_group.msk_sg.id]
    subnet_ids         = aws_subnet.msk_subnet.*.id
  }
  depends_on = [aws_security_group_rule.allow_egress_to_cluster]
}

resource "aws_s3_bucket" "msk_logs" {
  bucket = var.s3_bucket_name
  acl    = "log-delivery-write"

  versioning {
    enabled = true
  }
}

resource "aws_s3_bucket_logging" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id
  target_bucket = aws_s3_bucket.msk_logs.id
  target_prefix = "msk-logs/"
}

resource "aws_security_group" "msk_sg" {
  name        = "msk-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.msk_vpc.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group_rule" "allow_egress_to_cluster" {
  type              = "egress"
  from_port         = 9092
  to_port           = 9092
  protocol          = "tcp"
  source_security_group_id = aws_security_group.msk_sg.id
  security_group_id = aws_security_group.msk_sg.id
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "msk_subnet" {
  count = 2

  vpc_id     = aws_vpc.msk_vpc.id
  cidr_block = "10.0.1.${count.index}.0/24"
  availability_zone = "us-east1-a"
}

resource "aws_iam_role" "msk_role" {
  name        = "msk-role"
  description = "IAM role for MSK cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "msk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_policy" {
  name        = "msk-policy"
  description = "IAM policy for MSK cluster"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:PutObjectAcl",
        ]
        Effect = "Allow"
        Resource = aws_s3_bucket.msk_logs.arn
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_attach" {
  role       = aws_iam_role.msk_role.name
  policy_arn = aws_iam_policy.msk_policy.arn
}
```
