Here is a Terraform program that defines a managed MSK cluster in us-east1 and logs to a Kinesis Firehose:

**main.tf**
```terraform
# Provider configuration
provider "aws" {
  region = "us-east1"
}

# Create an IAM role for MSK cluster
resource "aws_iam_role" "mks-cluster-role" {
  name        = "mks-cluster-role"
  description = "Managed MSK cluster IAM role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      },
    ]
  })
}

# Attach IAM role to MSK cluster
resource "aws_msk_cluster" "mks-cluster" {
  name                      = "mks-cluster"
  kafka_version            = "2.3.0"
  num_broker_nodes         = 3
  broker_node_group_info = [
    {
      instance_type = "kafka.m5.large"
      ebs_volume_size = 64
      ebs_volume_type = "gp2"
      num_instances = 3
    }
  ]
  client_authentication = "DISABLED"
  vpc_config = {
    subnet_ids = [
      aws_subnet.subnet1.id,
      aws_subnet.subnet2.id,
      aws_subnet.subnet3.id,
    ]
  }
  iam_role_arn = aws_iam_role.mks-cluster-role.arn
}

# Create VPC subnets for MSK cluster
resource "aws_subnet" "subnet1" {
  cidr_block = "10.0.1.0/24"
  vpc_id     = aws_vpc.vpc.0.id
  availability_zone = "us-east1-a"
}

resource "aws_subnet" "subnet2" {
  cidr_block = "10.0.2.0/24"
  vpc_id     = aws_vpc.vpc.0.id
  availability_zone = "us-east1-b"
}

resource "aws_subnet" "subnet3" {
  cidr_block = "10.0.3.0/24"
  vpc_id     = aws_vpc.vpc.0.id
  availability_zone = "us-east1-c"
}

# Create VPC for MSK cluster
resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
}

# Create Kinesis Firehose delivery stream
resource "aws_kinesis_firehose_delivery_stream" "mks-firehose" {
  name        = "mks-firehose"
  destination = "kinesis-destination"
  kinesis_stream_name = aws_kinesis_stream.mks-stream.name

  # Define firehose configuration
  s3_bucket_arn = aws_s3_bucket.mks-bucket.arn
  s3_configuration = {
    role_arn   = aws_iam_role.firehose-role.arn
    compression_format = "GZIP"
  }
}

# Create S3 bucket for firehose delivery stream
resource "aws_s3_bucket" "mks-bucket" {
  bucket = "mks-bucket"
}

# Create IAM role for Kinesis Firehose
resource "aws_iam_role" "firehose-role" {
  name        = "firehose-role"
  description = "Kinesis Firehose IAM role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      },
    ]
  })
}

# Attach IAM role to Kinesis Firehose
resource "aws_kinesis_firehose_delivery_stream" "mks-firehose" {
  depends_on = [aws_s3_bucket.mks-bucket]
}

# Create Kinesis stream for firehose delivery stream
resource "aws_kinesis_stream" "mks-stream" {
  name        = "mks-stream"
  shard_count = 1
  retention_period = 86400

  # Define kinesis stream configuration
  data_shard_spec {
    shard_id = "shard1"
    retention_period = 86400
  }
}

# Output the MSK cluster and firehose delivery stream ARNs
output "mks_cluster_arn" {
  value = aws_msk_cluster.mks-cluster.arn
}

output "firehose_delivery_stream_arn" {
  value = aws_kinesis_firehose_delivery_stream.mks-firehose.arn
}
```
