```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_name" {
  type = string
  default = "my-msk-cluster"
}

variable "instance_type" {
  type = string
  default = "kafka.m5.large"
}

variable "num_broker_nodes" {
  type = number
  default = 3
}

variable "vpc_id" {
  type = string
}

variable "subnet_ids" {
  type = list(string)
}

variable "iam_role_arn" {
  type = string
}

resource "aws_msk_cluster" "this" {
  name                 = var.cluster_name
  kafka_version       = "KAFKA_2_6_0"
  number_of_broker_nodes   = var.num_broker_nodes
  broker_node_type        = var.instance_type
  vpc_id               = var.vpc_id
  subnet_ids           = var.subnet_ids
  enhanced_monitoring_config {
    client_user_data = "{\"properties\":{\"kafka.cluster.id\":\"${var.cluster_name}\"}}"
  }
  encryption_info {
    key_arn = aws_kms_key.this.arn
  }
  logging_info {
    cloudwatch_log_group_info {
      log_group_name = aws_cloudwatch_log_group.this.name
    }
  }
  IAM_role_arn = var.iam_role_arn
  configuration {
    arn               = aws_msk_configuration.this.arn
    revision           = aws_msk_configuration.this.latest_revision
    configuration_name = aws_msk_configuration.this.name
  }
}

resource "aws_msk_configuration" "this" {
  name  = var.cluster_name
  kafka_cluster_id = aws_msk_cluster.this.id
  configuration {
    arn               = aws_msk_configuration.this.arn
    revision           = aws_msk_configuration.this.latest_revision
    configuration_name = aws_msk_configuration.this.name
    server_properties = jsonencode({
      "monitoring.interpolation.interval.seconds" = 300
      "jmx_exporter.enabled" = "true"
      "jmx_exporter.host" = "localhost"
      "jmx_exporter.port" = "1100"
      "node_exporter.enabled" = "true"
      "node_exporter.service.name" = "node-exporter"
    })
  }
}

resource "aws_kms_key" "this" {
  description             = "Managed MSK Key"
  deletion_window_in_days = 10
}

resource "aws_cloudwatch_log_group" "this" {
  name = "${var.cluster_name}-logs"
}

resource "aws_iam_role" "this" {
  name        = "${var.cluster_name}-msk-role"
  description = "Role for MSK cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.${data.aws_region.current.name}.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "this" {
  name        = "${var.cluster_name}-msk-policy"
  description = "Policy for MSK cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "logs:CreateLogGroup"
        Resource = aws_cloudwatch_log_group.this.arn
        Effect = "Allow"
      },
      {
        Action = "logs:CreateLogStream"
        Resource = "${aws_cloudwatch_log_group.this.arn}:*"
        Effect = "Allow"
      },
      {
        Action = "logs:PutLogEvents"
        Resource = "${aws_cloudwatch_log_group.this.arn}:*"
        Effect = "Allow"
      },
      {
        Action = "kms:DescribeKey"
        Resource = aws_kms_key.this.arn
        Effect = "Allow"
      },
      {
        Action = "kms:Encrypt"
        Resource = aws_kms_key.this.arn
        Effect = "Allow"
      },
      {
        Action = "kms:ReEncrypt"
        Resource = aws_kms_key.this.arn
        Effect = "Allow"
      },
      {
        Action = "kms:Decrypt"
        Resource = aws_kms_key.this.arn
        Effect = "Allow"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "this" {
  role       = aws_iam_role.this.name
  policy_arn = aws_iam_policy.this.arn
}
