Here is a Terraform HCL program to create a serverless MSK cluster in us-east1:

```hcl
provider "aws" {
  region = "us-east1"
}

variable "msk_cluster_name" {
  default = "my-msk-cluster"
}

variable "msk_cluster_encryption" {
  default = "KMS"
}

variable "msk_cluster_vpc" {
  default = "vpc-12345678"
}

variable "msk_cluster_security_group" {
  default = "sg-12345678"
}

resource "aws_kafka_cluster" "msk_cluster" {
  name        = var.msk_cluster_name
  environment = "DEV"
  kafka_version = "2.6.1"
  number_of_broker_nodes = 3

  enhanced_monitoring_config {
    client_user_name = "terraform"
  }

  encryption_in_transit {
    use_server_side_encryption = true
    in_transit_properties {
      client_broker = var.msk_cluster_encryption
    }
  }

  encryption_at_rest {
    use_aws_managed_acm = true
    key_store {
      kms_master_key_id = "arn:aws:kms:us-east-1:123456789012:key/12345678"
    }
  }

  tags = {
    "Name"       = var.msk_cluster_name
    "Environment" = "DEV"
  }

  vpc_id          = var.msk_cluster_vpc
  security_groups = [var.msk_cluster_security_group]
}

resource "aws_kafka_connect_cluster" "msk_connect_cluster" {
  name                      = var.msk_cluster_name
  environment              = "DEV"
  kafka_version           = "2.6.1"
  vpc_id                  = var.msk_cluster_vpc
  security_groups         = [var.msk_cluster_security_group]

  depends_on = [aws_kafka_cluster.msk_cluster]
}
```

Note: Replace `us-east1` with the actual AWS region name you are using. Replace `vpc-12345678` and `sg-12345678` with your actual VPC ID and Security Group ID. Also, replace `arn:aws:kms:us-east-1:123456789012:key/12345678` with your actual KMS Key ARN.

This configuration will create an AWS MSK cluster with a Kafka version of 2.6.1, 3 broker nodes, and use the server-side encryption with KMS. It will also create an AWS MSK Connect cluster with the same configuration.

