**Description:**

This Terraform program will create a serverless Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes, along with the necessary IAM roles and configuration. The MSK cluster will be created in a specified region, and the program will provide default values for any variables used.

**Terraform HCL Program:**
```terraform
provider "aws" {
  region = "us-west-2"
}

variable "msk_cluster_name" {
  type = string
  default = "example-msk-cluster"
}

variable "msk_cluster_vpc_id" {
  type = string
  default = "vpc-0123456789abcdef0"
}

variable "msk_cluster_vpc_cidr" {
  type = string
  default = "10.0.0.0/16"
}

variable "msk_cluster_availability_zones" {
  type = list(string)
  default = ["us-west-2a", "us-west-2b", "us-west-2c"]
}

resource "aws_iam_role" "msk_cluster_role" {
  name               = "${var.msk_cluster_name}-msk-cluster-role"
  description        = "MSK cluster execution role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "msk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "msk_cluster_policy" {
  name   = "${var.msk_cluster_name}-msk-cluster-policy"
  role   = aws_iam_role.msk_cluster_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kafka:CreateCluster",
          "kafka:CreateConfiguration",
          "kafka:CreateTopic",
          "kafka:DescribeCluster",
          "kafka:DescribeConfiguration",
          "kafka:DescribeTopic"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_msk_cluster" "example" {
  name          = var.msk_cluster_name
  kafka_version = "KAFKA_2_3_0"
  number_of_broker_nodes = 3
  broker_node_properties {
    instance_type = "kafka.m5.large"
    ebs_volume_size = 100
  }
  vpc_id    = var.msk_cluster_vpc_id
  subnet_ids = [
    aws_subnet.msk_cluster_subnet[0].id,
    aws_subnet.msk_cluster_subnet[1].id
  ]
  cloud_watch_logs_role_arn = aws_iam_role.msk_cluster_role.arn

  tags = {
    Environment = "example"
  }
}

resource "aws_subnet" "msk_cluster_subnet" {
  count = 2
  vpc_id = var.msk_cluster_vpc_id
  cidr_block = cidrsubnet(var.msk_cluster_vpc_cidr, 8, count.index + 1)
  availability_zone = var.msk_cluster_availability_zones[count.index]
}

output "msk_cluster_arn" {
  value = aws_msk_cluster.example.arn
}
```
This Terraform program defines an AWS provider, sets up IAM roles and policies for MSK, and creates a serverless MSK cluster with 3 broker nodes. The `aws_msk_cluster` resource is used to create the MSK cluster, and the `aws_subnet` resource is used to create the necessary subnets. The `output` block is used to output the ARN of the MSK cluster.

Note: This program assumes that you have the necessary credentials set up to deploy resources to AWS. You will need to replace the `msk_cluster_name`, `msk_cluster_vpc_id`, `msk_cluster_vpc_cidr`, and `msk_cluster_availability_zones` variables with your own values.

