Here is the Terraform configuration for a serverless MSK cluster with 3 broker nodes in the us-east1 region:

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-east1"
}

# Create a VPC for the MSK cluster
resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
}

# Create a subnet for the MSK cluster
resource "aws_subnet" "msk_subnet" {
  cidr_block = "10.0.1.0/24"
  vpc_id     = aws_vpc.msk_vpc.id
  availability_zone = "us-east1a"
}

# Create an MSK cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name    = "msk-cluster"
  number_of_broker_nodes = 3
  kafka_version  = "2.6.1"
  vpc_id        = aws_vpc.msk_vpc.id
  subnet_id     = aws_subnet.msk_subnet.id
  role_arn      = aws_iam_role.msk_exec_role.arn
  ebs_volume_size_per_instance = 64

  tags = {
    Name = "msk-cluster"
  }
}

# Create an IAM role for the MSK cluster
resource "aws_iam_role" "msk_exec_role" {
  name               = "msk-exec-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "msk.mws.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the MSK cluster
resource "aws_iam_policy" "msk_policy" {
  name        = "msk-policy"
  description = "Policy for MSK cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kafka:CreateConfiguration",
          "kafka:DeleteConfiguration",
          "kafka:DescribeConfiguration",
          "kafka:GetConfiguration",
          "kafka:ListConfigurations",
          "kafka:UpdateConfiguration",
          "kafka:CreateTopic",
          "kafka:DeleteTopic",
          "kafka:DescribeTopic",
          "kafka:GetTopic",
          "kafka:ListTopics",
          "kafka:UpdateTopic",
        ]
        Resource = "*"
        Effect    = "Allow"
      }
    ]
  })
}

# Attach the IAM policy to the MSK role
resource "aws_iam_role_policy_attachment" "msk_attach" {
  role       = aws_iam_role.msk_exec_role.name
  policy_arn = aws_iam_policy.msk_policy.arn
}
```

This configuration creates a VPC, a subnet, an MSK cluster with 3 broker nodes, and an IAM role with the necessary permissions for the MSK cluster. It also creates an IAM policy for the MSK cluster and attaches it to the IAM role.

