Here is the Terraform HCL program that will create a serverless MSK cluster in us-east2:
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-east-2"
  default_tags {
    Tags = {
      Environment = "dev"
    }
  }
}

# Create an IAM role for MSK
resource "aws_iam_role" "msk_service_linked_role" {
  name               = "msk_service_linked_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the IAM role to the MSK cluster
resource "aws_kafka_cluster" "example" {
  count               = 1
  name                = "example-msk-cluster"
  kafka_version       = "KAFKA_2.6_2.2_7.3.10"
  instance_type       = "kafka.t3.medium"
  number_of_node_groups = 1
  subnet_ids          = aws_subnet.example.*.id
  vpc_security_group_ids = aws_security_group.example.*.id
  iam_role_arn        = aws_iam_role.msk_service_linked_role.arn
  serverless        = true

  node_groups {
    id          = "ng-1"
    instance_type = "kafka.t3.medium"
    ebs_storage_config {
      volume_size = 100
    }
  }
}

# Create a VPC and subnets
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example" {
  count             = 4
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.${count.index}.0.0/20"
  availability_zone = "${var.region}a"
  map_public_ip_on_launch = true
}

# Create a security group for the MSK cluster
resource "aws_security_group" "example" {
  name        = "example-msk-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.example.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Output the MSK cluster ARN
output "msk_cluster_arn" {
  value = aws_kafka_cluster.example[0].arn
}
```
Note that I've assumed a region of "us-east-2" and created a simple VPC and subnets. I've also created an IAM role for MSK and attached it to the MSK cluster. The `serverless` attribute is set to `true` to create a serverless MSK cluster.

