```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
  version = "4.27.0"
}

# Create an S3 bucket to store the CloudWatch log files
resource "aws_s3_bucket" "cloudwatch_logs" {
  bucket = "cloudwatch-logs-bucket"
  acl    = "log-delivery-write"
}

# Create a CloudWatch log group
resource "aws_cloudwatch_log_group" "msk_logs" {
  name              = "msk-logs"
  retention_in_days = 14
}

# Create a VPC for the MSK cluster
resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
}

# Create a subnet for the MSK cluster
resource "aws_subnet" "msk_subnet" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create an IAM role for the MSK cluster
resource "aws_iam_role" "msk_role" {
  name        = "msk-role"
  description = "MSK role for Kinesis"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesis.amazonaws.com"
        }
      },
    ]
  })
}

# Create an IAM policy for the MSK cluster
resource "aws_iam_policy" "msk_policy" {
  name        = "msk-policy"
  description = "Policy for MSK cluster"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutRecord",
        ]
        Effect = "Allow"
        Resource = "${aws_cloudwatch_log_group.msk_logs.arn}:*"
      },
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "msk_attach" {
  role       = aws_iam_role.msk_role.name
  policy_arn = aws_iam_policy.msk_policy.arn
}

# Create an MSK cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = "msk-cluster"
  kafka_version = "2.6.1"
  number_of_broker_nodes = 3
  enhanced_monitoring_config {
    name = "standard"
    role_arn = aws_iam_role.msk_role.arn
  }
  logging_info {
    elasticsearch_endpoint = "https://search-my-cluster.us-west-2.es.amazonaws.com"
    elasticsearch_role_arn = aws_iam_role.msk_role.arn
  }
  encryption_in_transit {
    use_server_side_encryption = true
  }
}

# Create a Kinesis Firehose delivery stream
resource "aws_kinesis_firehose_delivery_stream" "msk_firehose" {
  name        = "msk-firehose"
  destination = "s3"
  s3_bucket_arn = aws_s3_bucket.cloudwatch_logs.arn

  kinesis_stream_source {
    enabled = true
    delivery_stream_name = aws_msk_cluster.msk_cluster.name
  }

  dynamic "s3_configuration" {
    for_each = ["true"]
    content {
      role_arn = aws_iam_role.msk_role.arn
      compression_format = "GZIP"
    }
  }
}
```

This Terraform configuration creates the following resources:

*   An S3 bucket to store CloudWatch log files
*   A CloudWatch log group to store MSK logs
*   A VPC and a subnet for the MSK cluster
*   An IAM role for the MSK cluster with the necessary permissions
*   An MSK cluster with 3 broker nodes and open monitoring enabled
*   A Kinesis Firehose delivery stream to forward MSK logs to the S3 bucket

This configuration assumes that you have the necessary credentials set up to use the AWS provider in Terraform.

