Here is a Terraform HCL program to create an Aurora PostgresQL cluster.

### Description
This Terraform program will create an Aurora PostgresQL cluster in AWS. The cluster will be created in the specified region, and the cluster and database instances will be provisioned with the desired configuration.

### Code

```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM Role for the Aurora Cluster
resource "aws_iam_role" "aurora_cluster_role" {
  name        = "aurora-cluster-role"
  description = "Role for Aurora Cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM Policy for the Aurora Cluster
resource "aws_iam_policy" "aurora_cluster_policy" {
  name        = "aurora-cluster-policy"
  description = "Policy for Aurora Cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "rds:DescribeClusters"
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = "rds:DescribeDbInstances"
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the Policy to the Role
resource "aws_iam_role_policy_attachment" "aurora_cluster_attach" {
  role       = aws_iam_role.aurora_cluster_role.name
  policy_arn = aws_iam_policy.aurora_cluster_policy.arn
}

# Create an Aurora Cluster
resource "aws_rds_cluster" "aurora_cluster" {
  cluster_identifier        = "aurora-cluster"
  database_name             = "mydatabase"
  master_username           = "admin"
  master_user_password      = "password"
  engine                    = "aurora-postgres"
  engine_version            = "10.7"
  instance_count            = 1
  db_subnet_group_name      = "aurora-cluster-subnet"
  skip_final_snapshot       = true
  iam_authentication_enabled = true
  apply_immediately         = true
  vpc_security_group_ids    = [aws_security_group.aurora_cluster_sg.id]
  iam_roles                 = [aws_iam_role.aurora_cluster_role.arn]
}

# Create a Security Group for the Aurora Cluster
resource "aws_security_group" "aurora_cluster_sg" {
  name        = "aurora-cluster-sg"
  description = "Security Group for Aurora Cluster"

  vpc_id = "vpc-12345678"

  ingress {
    description = "Allow inbound traffic from RDS"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Output the Aurora Cluster Details
output "aurora_cluster_endpoint" {
  value = aws_rds_cluster.aurora_cluster.endpoint
}

output "aurora_cluster_id" {
  value = aws_rds_cluster.aurora_cluster.id
}

output "aurora_cluster_arn" {
  value = aws_rds_cluster.aurora_cluster.arn
}
```

This configuration will create an Aurora PostgresQL cluster in the `us-west-2` region with a database named `mydatabase`. The cluster will be provisioned with a single instance and will be attached to a security group named `aurora-cluster-sg`. The IAM role `aurora-cluster-role` will be created and attached to the cluster, and the IAM policy `aurora-cluster-policy` will be created and attached to the role.

Note that you should replace the `vpc-id` and `subnet-ids` with your actual VPC and subnet IDs.

Also, you can modify the `output` blocks to include any other details you need.

Please let me know if you have any questions or need further assistance!

