```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create a variable for the MySQL cluster name
variable "mysql_cluster_name" {
  default = "mysql-cluster"
}

# Create a variable for the MySQL instance size
variable "mysql_instance_size" {
  default = "db.r5.xlarge"
}

# Create a variable for the number of zones
variable "num_zones" {
  default = 3
}

# Create a variable for the instance type
variable "instance_type" {
  default = "db.r5.xlarge"
}

# Create a VPC for the MySQL cluster
resource "aws_vpc" "mysql_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "${var.mysql_cluster_name}-vpc"
  }
}

# Create a subnet for each zone
resource "aws_subnet" "mysql_subnet" {
  count             = var.num_zones
  vpc_id            = aws_vpc.mysql_vpc.id
  cidr_block        = "10.0.${count.index}.0/24"
  availability_zone = "${element(aws_availability_zone.zone.*.name, count.index)}"
  tags = {
    Name = "${var.mysql_cluster_name}-subnet-${count.index}"
  }
}

# Create a security group for the MySQL cluster
resource "aws_security_group" "mysql_sg" {
  name        = "${var.mysql_cluster_name}-sg"
  description = "Security group for MySQL cluster"
  vpc_id      = aws_vpc.mysql_vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a DB instance for each zone
resource "aws_rds_cluster_instance" "mysql_instance" {
  count              = var.num_zones
  cluster_identifier = aws_rds_cluster.mysql_cluster.id
  instance_class     = var.instance_type
  engine             = "mysql"
  engine_version     = "8.0.21"
  port               = 3306
  vpc_security_group_ids = [aws_security_group.mysql_sg.id]
  db_subnet_group_name = aws_db_subnet_group.mysql_subnet_group.name
  availability_zone = "${element(aws_availability_zone.zone.*.name, count.index)}"
}

# Create a DB subnet group
resource "aws_db_subnet_group" "mysql_subnet_group" {
  name       = "${var.mysql_cluster_name}-subnet-group"
  subnet_ids = aws_subnet.mysql_subnet.*.id
}

# Create a DB cluster
resource "aws_rds_cluster" "mysql_cluster" {
  cluster_identifier = var.mysql_cluster_name
  database_name      = "mysql"
  master_username    = "mysql"
  master_password    = "mysql"
  vpc_security_group_ids = [aws_security_group.mysql_sg.id]
  db_subnet_group_name = aws_db_subnet_group.mysql_subnet_group.name
  final_db_snapshot_identifier = "mysql-cluster-snapshot"

  timeouts {
    create = "10m"
    delete = "5m"
  }
}

# Create a IAM role for the RDS cluster
resource "aws_iam_role" "mysql_role" {
