**Terraform Program Description**

The Terraform program will create a PostgresQL instance on Amazon RDS. The instance will be created in the us-west-2 (Oregon) region. The program will define an AWS IAM role to be used by the RDS instance, which will allow it to access the database. The role will have a policy that grants necessary permissions to the RDS instance. Additionally, the program will define a network security group (SG) that will control inbound and outbound traffic to the RDS instance.

**Terraform HCL Program**

```hcl
# Define the AWS provider configuration
provider "aws" {
  region = "us-west-2"
}

# Define a variable for the RDS instance identifier
variable "rds_instance_identifier" {
  default = "my-postgres-instance"
}

# Define a variable for the database instance class
variable "rds_instance_class" {
  default = "db.t2.micro"
}

# Define a variable for the database username
variable "rds_username" {
  default = "postgres"
}

# Define a variable for the database password
variable "rds_password" {
  default = "postgres"
}

# Create an IAM role for the RDS instance
resource "aws_iam_role" "rds_role" {
  name        = "${var.rds_instance_identifier}-role"
  description = "Role for RDS instance ${var.rds_instance_identifier}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Create a policy for the RDS instance
resource "aws_iam_policy" "rds_policy" {
  name        = "${var.rds_instance_identifier}-policy"
  description = "Policy for RDS instance ${var.rds_instance_identifier}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "arn:aws:logs:${aws_region}:*:log-group:/aws/rds/*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "rds_attach" {
  role       = aws_iam_role.rds_role.name
  policy_arn = aws_iam_policy.rds_policy.arn
}

# Create a VPC
resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
}

# Create a subnet
resource "aws_subnet" "subnet" {
  vpc_id     = aws_vpc.vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create a security group
resource "aws_security_group" "sg" {
  name        = "${var.rds_instance_identifier}-sg"
  description = "Security group for RDS instance ${var.rds_instance_identifier}"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a database instance
resource "aws_db_instance" "rds_instance" {
  identifier              = var.rds_instance_identifier
  engine                  = "postgres"
  instance_class          = var.rds_instance_class
  username                = var.rds_username
  password                = var.rds_password
  vpc_security_group_ids  = [aws_security_group.sg.id]
  allocated_storage       = 20
  storage_type            = "gp2"
  db_subnet_group_name    = aws_db_subnet_group.db_subnet_group.name
  skip_final_snapshot     = true
  publicly_accessible     = true
}

# Create a DB subnet group
resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "${var.rds_instance_identifier}-subnet-group"
  description = "DB subnet group for RDS instance ${var.rds_instance_identifier}"
  subnet_ids = [aws_subnet.subnet.id]
}
```

This Terraform program creates a PostgresQL instance on Amazon RDS. It defines an IAM role to be used by the RDS instance, which allows it to access the database. The program also defines a network security group (SG) that controls inbound and outbound traffic to the RDS instance

