**Description**

This Terraform program will create a Amazon DynamoDB Accelerator (DAX) cluster, a fully managed in-memory cache for DynamoDB. The DAX cluster will be created in a specified region, and IAM roles will be created for the cluster's replication nodes.

**Terraform HCL Program**
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
  version = "3.27.0"
}

# Create an IAM role for the DAX cluster
resource "aws_iam_role" "dax_role" {
  name        = "dax-cluster-role"
  description = "IAM role for DAX cluster replication nodes"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
      }
    ]
  })
}

# Create the DAX cluster
resource "aws_dax_cluster" "example" {
  cluster_name        = "dax-cluster"
  iam_roleArn         = aws_iam_role.dax_role.arn
  capacity             = "1.d2.xlarge"
  port                = 8111
  preferredMaintenanceWindow = "sun:06:00-sun:12:00"
  notificationTopicArn = "arn:aws:sns:us-west-2:123456789012:dax-cluster-notification"
}

# Create an IAM role for the DAX replication nodes
resource "aws_iam_role" "dax_replication_node_role" {
  name        = "dax-replication-node-role"
  description = "IAM role for DAX replication nodes"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create a DAX parameter group
resource "aws_dax_parameter_group" "example" {
  name        = "dax-parameter-group"
  description = "DAX parameter group"
  family      = "daxparametergroup1"
}

# Output the DAX cluster ARN
output "dax_cluster_arn" {
  value = aws_dax_cluster.example.arn
}
```
This Terraform program creates a DAX cluster with 1 d2.xlarge capacity, a preferred maintenance window, and a notification topic ARN. It also creates two IAM roles: one for the DAX cluster and another for the replication nodes. The program uses the AWS provider version 3.27.0 and assumes that the AWS region is set to `us-west-2`.

