The Terraform program will create a DynamoDB table named "customer-data" in the specified region with data encryption at rest enabled. The table will have two attributes: "id" and "name", and a primary key defined on the "id" attribute. Additionally, the program will define an IAM role with the necessary permissions to interact with the DynamoDB table.

Here is the Terraform HCL program:
```terraform
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for DynamoDB access
resource "aws_iam_role" "dynamodb_role" {
  name        = "dynamodb-role"
  description = "Role for DynamoDB access"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
      }
    ]
  })
}

# Attach a policy to the IAM role
resource "aws_iam_role_policy" "dynamodb_policy" {
  name   = "dynamodb-policy"
  role   = aws_iam_role.dynamodb_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem",
        ]
        Effect = "Allow"
        Resource = "arn:aws:dynamodb:us-west-2:*:table/customer-data"
      }
    ]
  })
}

# Create the DynamoDB table
resource "aws_dynamodb_table" "customer_data" {
  name           = "customer-data"
  billing_mode   = "PROVISIONED"
  read_capacity_units = 5
  write_capacity_units = 5

  hash_key = "id"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "name"
    type = "S"
  }

  tags = {
    Name = "Customer Data Table"
  }

  # Enable data encryption at rest
  server_side_encryption = "AES256"
}
```
Note: The `dynamodb-role` and `dynamodb-policy` resources are created to provide the necessary IAM permissions for the DynamoDB table. The `aws_dynamodb_table` resource is used to create the table with the specified attributes and encryption settings.

