Here is a Terraform program that creates two AWS VPCs and establishes a peering connection between them:

**main.tf**
```terraform
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Define variables for VPC settings
variable "vpc1_cidr" {
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc1_name" {
  type        = string
  default     = "vpc1"
}

variable "vpc2_cidr" {
  type        = string
  default     = "10.1.0.0/16"
}

variable "vpc2_name" {
  type        = string
  default     = "vpc2"
}

# Create VPC 1
resource "aws_vpc" "vpc1" {
  cidr_block = var.vpc1_cidr
  tags = {
    Name = var.vpc1_name
  }
}

# Create VPC 2
resource "aws_vpc" "vpc2" {
  cidr_block = var.vpc2_cidr
  tags = {
    Name = var.vpc2_name
  }
}

# Create a peering connection between VPC 1 and VPC 2
resource "aws_vpc_peering_connection" "vpc_peering" {
  vpc_id        = aws_vpc.vpc1.id
  peer_vpc_id   = aws_vpc.vpc2.id
  peer_owner_id = "self"
  auto_accept    = true

  tags = {
    Name = "vpc-peering"
  }
}
```
This configuration creates two VPCs in the `us-west-2` region, each with a specific CIDR block and name. It then creates a peering connection between the two VPCs, automatically accepting the connection on both sides.

