**Description of the Terraform Program**

This Terraform configuration will create a basic AWS Neptune cluster with a custom parameter group. The configuration includes the following components:

* An IAM role with the necessary permissions to interact with AWS Neptune
* A custom parameter group with specific configuration settings
* A Neptune cluster with the custom parameter group attached
* The Neptune cluster is configured with a single instance and a basic DB subnet group

**Terraform HCL Program**

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM Role for Neptune
resource "aws_iam_role" "neptune_role" {
  name        = "neptune-cluster-role"
  description = "Role for Neptune Cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}

# Create an IAM Policy for Neptune
resource "aws_iam_policy" "neptune_policy" {
  name        = "neptune-cluster-policy"
  description = "Policy for Neptune Cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "neptune:CreateDBCluster",
          "neptune:CreateDBInstance",
          "neptune:CreateDBParameterGroup",
          "neptune:ModifyDBClusterParameterGroup",
          "neptune:ModifyDBInstance",
          "neptune:DescribeDBClusters",
          "neptune:DescribeDBInstances",
          "neptune:DescribeDBParameterGroups"
        ]
        Resource = "*"
        Effect    = "Allow"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "neptune_attach" {
  role       = aws_iam_role.neptune_role.name
  policy_arn = aws_iam_policy.neptune_policy.arn
}

# Create a custom parameter group
resource "aws_neptune_cluster_parameter_group" "custom_param_group" {
  name        = "custom-param-group"
  family      = "neptune-10.2.0"
  description = "Custom Parameter Group"

  parameter {
    name  = "tunables.ratio"
    value = "0.5"
  }
  parameter {
    name  = "tunables.min_memory_for_sort"
    value = "1048576"
  }
}

# Create a Neptune cluster
resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier        = "neptune-cluster"
  engine                     = "neptune"
  instance_class             = "db.r5.large"
  port                       = 8182
  vpc_security_group_ids     = [aws_security_group.neptune.id]
  db_subnet_group_name       = aws_db_subnet_group.neptune_subnet_group.name
  parameter_group_name       = aws_neptune_cluster_parameter_group.custom_param_group.name

  iam_roles = [aws_iam_role.neptune_role.arn]
}

# Create a DB subnet group
resource "aws_db_subnet_group" "neptune_subnet_group" {
  name       = "neptune-subnet-group"
  description = "Subnet group for Neptune"

  subnet_ids = [
    "subnet-12345678",
    "subnet-90123456",
  ]
}

# Create a security group
resource "aws_security_group" "neptune" {
  name        = "neptune-sg"
  description = "Security group for Neptune"

  vpc_id = "vpc-12345678"

  ingress {
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```

Note that you'll need to replace the `subnet-12345678` and `vpc-12345678` placeholders with your actual subnet and VPC IDs. Also, make sure to update the `region` variable in the `provider` block to match your desired AWS region.

