**Terraform Program Description**

This Terraform program will create an AWS Chime Voice Connector and a Voice Connector Logging resource within the AWS organization. The program will utilize the AWS provider to create the required resources. The Voice Connector will be created with default settings, and the Voice Connector Logging resource will have the `enable_sip_logs` attribute disabled and the `enable_media_metric_logs` attribute enabled.

**Terraform HCL Program**
```terraform
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the Chime Voice Connector
resource "aws_iam_role" "chime_voice_connector_role" {
  name        = "chime-voice-connector-role"
  description = "Role for the Chime Voice Connector"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "chime.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the Chime Voice Connector
resource "aws_iam_policy" "chime_voice_connector_policy" {
  name        = "chime-voice-connector-policy"
  description = "Policy for the Chime Voice Connector"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${aws_s3_bucket.chime-voice-connector-log-storage.arn}/*"
        Effect    = "Allow"
      }
    ]
  })
}

# Create an IAM role policy attachment
resource "aws_iam_role_policy_attachment" "chime_voice_connector_policy_attachment" {
  role       = aws_iam_role.chime_voice_connector_role.name
  policy_arn = aws_iam_policy.chime_voice_connector_policy.arn
}

# Create the Chime Voice Connector
resource "aws_chime_voice_connector" "chime_voice_connector" {
  name                     = "chime-voice-connector"
  require creating_phone_number_id = true
  enable_sip_logging = true
}

# Create the Voice Connector Logging resource
resource "aws_chime_voice_connector_logging" "chime_voice_connector_logging" {
  voice_connector_id = aws_chime_voice_connector.chime_voice_connector.id

  enable_sip_logs = false
  enable_media_metric_logs = true
}

# Create an S3 bucket for log storage
resource "aws_s3_bucket" "chime-voice-connector-log-storage" {
  bucket = "chime-voice-connector-log-storage"
  acl    = "private"

  versioning {
    enabled = true
  }
}
```
