**Program Description**

This Terraform program will create an AWS Chime Voice Connector with encryption and log media metrics in the specified AWS account and region.

**Terraform HCL Program**

```terraform
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
  version = "3.26.0"
}

# Create a Chime Voice Connector
resource "aws_chime_voice_connector" "example" {
  name        = "example-voice-connector"
  host_name   = "example-voice-connector.example.com"
  tags = {
    Environment = "dev"
  }
}

# Create an IAM role for the Voice Connector
resource "aws_iam_role" "voice_connector_role" {
  name        = "voice_connector_role"
  description = "IAM role for the Chime Voice Connector"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "chime.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the IAM role to the Voice Connector
resource "aws_chime_voice_connector_identity" "example" {
  voice_connector_id = aws_chime_voice_connector.example.id
  iam_role_id       = aws_iam_role.voice_connector_role.id
}

# Create a Chime Voice Connector instance
resource "aws_chime_voice_connector_instance" "example" {
  voice_connector_id = aws_chime_voice_connector.example.id
  instance_type      = "tiny"
}

# Configure encryption for the Voice Connector
resource "aws_chime_voice_connector_encryption" "example" {
  voice_connector_id = aws_chime_voice_connector.example.id
  mode               = "ENCRYPTED"
}

# Configure media metrics for the Voice Connector
resource "aws_chime_voice_connector_media_metrics" "example" {
  voice_connector_id = aws_chime_voice_connector.example.id
  enabled            = true
}
```

