}

# Create an IAM policy for the Redshift cluster
resource "aws_iam_policy" "redshift_cluster_policy" {
  name        = "redshift-cluster-policy"
  description = "Policy for Redshift cluster to access S3 and other AWS resources"

  policy = jsonencode({
