  database_name              = "exampledb"
  master_username            = "exampleuser"
  master_password            = "password123"

  node_type = "dc2.large"

  iam_roles {
    role_arn = aws_iam_role.redshift.arn
  }

  tags = {
    Name        = "example-cluster"
    Environment = "dev"
  }
}

# Create an IAM Role for Redshift
resource "aws_iam_role" "redshift" {
  name        = "redshift-execution-role"
  description = "Redshift execution role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM Policy for Redshift
resource "aws_iam_policy" "redshift" {
  name        = "redshift-execution-policy"
  description = "Redshift execution policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Resource = "arn:aws:s3:::example-bucket/*"
      }
    ]
  })
}

# Attach the IAM Policy to the IAM Role
resource "aws_iam_role_policy_attachment" "redshift" {
  role       = aws_iam_role.redshift.name
  policy_arn = aws_iam_policy.redshift.arn
}

# Create a Redshift Event Subscription
resource "aws_redshift_event_subscription" "example" {
  name        = "example-event-subscription"
  enabled     = true
  event_categories = ["REDSHIFT_CLUSTER_JOINED", "REDSHIFT_CLUSTER_LEFT"]
  cluster_identifiers = [aws_redshift_cluster.example.cluster_identifier]
  iam_role_arn = aws_iam_role.redshift.arn
}
```
