================================

This Terraform configuration will create an Amazon Web Services (AWS) S3 bucket with an example name. The S3 bucket will be created in the specified region and IAM roles will be created as needed for access. The Terraform configuration will include a valid provider configuration and default values for variables.

**Terraform HCL Program**
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM Role for S3 Access
resource "aws_iam_role" "s3_access_role" {
  name        = "s3-access-role"
  description = "Role for accessing S3 Bucket"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM Policy for S3 Access
resource "aws_iam_policy" "s3_access_policy" {
  name        = "s3-access-policy"
  description = "Policy for accessing S3 Bucket"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.example.name}"
      }
    ]
  })
}

# Attach IAM Policy to Role
resource "aws_iam_role_policy_attachment" "s3_access_attachment" {
  role       = aws_iam_role.s3_access_role.name
  policy_arn = aws_iam_policy.s3_access_policy.arn
}

# Create S3 Bucket
