**Program Description:**
This Terraform program will create two AWS S3 buckets, `s3-bucket-inventory` and `s3-bucket-reports`. The program will then configure an AWS S3 bucket policy to allow the `s3-bucket-reports` bucket to store the inventory reports. Finally, the program will use the AWS S3 Inventory feature to generate a CSV report every week of all current object versions in the `s3-bucket-inventory` bucket and store it in the `s3-bucket-reports` bucket.

And here is the Terraform HCL program:
```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create the S3 bucket for inventory
resource "aws_s3_bucket" "s3-bucket-inventory" {
  bucket = "s3-bucket-inventory"
  acl    = "private"

  versioning {
    enabled = true
  }

  lifecycle_rule {
    enabled = true

    expiration {
      days = 365
    }
  }
}

# Create the S3 bucket for reports
resource "aws_s3_bucket" "s3-bucket-reports" {
  bucket = "s3-bucket-reports"
  acl    = "private"
}

# Create an IAM role for the S3 Inventory
resource "aws_iam_role" "s3-inventory-role" {
  name        = "s3-inventory-role"
  description = "Role for S3 Inventory"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      },
    ]
  })
}

# Create an IAM policy for the S3 Inventory
resource "aws_iam_policy" "s3-inventory-policy" {
  name        = "s3-inventory-policy"
  description = "Policy for S3 Inventory"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetInventoryConfiguration"
        Effect = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.s3-bucket-inventory.id}"
      },
      {
        Action = "s3:GetInventoryHistogram"
        Effect = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.s3-bucket-inventory.id}"
      },
      {
        Action = "s3:PutInventoryConfiguration"
        Effect = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.s3-bucket-inventory.id}"
      },
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "s3-inventory-role-policy-attachment" {
  role       = aws_iam_role.s3-inventory-role.name
  policy_arn = aws_iam_policy.s3-inventory-policy.arn
}

# Configure the S3 Inventory
resource "aws_s3_bucket_inventory" "s3-bucket-inventory" {
  bucket = aws_s3_bucket.s3-bucket-inventory.id
  enabled = true

  schedule {
    frequency = "Weekly"
  }

  report {
    format = "CSV"
    prefix = "inventory-reports/"
  }
}

# Configure the S3 Bucket policy
resource "aws_s3_bucket_policy" "s3-bucket-reports" {
  bucket = aws_s3_bucket.s3-bucket-reports.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowInventoryReports"
        Effect    = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action    = "s3:GetObject"
        Resource = "arn:aws:s3:::${aws_s3_bucket.s3-bucket-reports.id}/inventory-reports/*"
      },
    ]
  })
}
```
This program defines all the necessary resources and policies to create an S3 bucket for inventory, an S3 bucket for reports, an IAM role for the S3 Inventory, an IAM policy for the S3 Inventory, and an S3 Bucket policy to allow the reports bucket to store the inventory reports. The S3 Inventory is configured to generate a CSV report every week and store it in the reports bucket.

