```
# Define the AWS provider
provider "aws" {
  region = "us-west-2" # specify the AWS region
}

# Define the KMS key resource
resource "aws_kms_key" "my_key" {
  description             = "My KMS key for S3 encryption"
  key_usage               = "ENCRYPT_DECRYPT"
  is_enabled               = true
  deletion_window_in_days = 10
}

# Create an alias for the KMS key
resource "aws_kms_alias" "my_key_alias" {
  name          = "alias/MyS3Key"
  target_key_id = aws_kms_key.my_key.key_id
}

# Define the S3 bucket resource with KMS server-side encryption
resource "aws_s3_bucket" "my_bucket" {
  bucket = "my-s3-bucket-${random_string.unique.result}"
  acl    = "private"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "aws:kms"
        kms_master_key_id = aws_kms_key.my_key.key_id
      }
    }
  }

  versioning {
    enabled = true
  }
}

# Use a random string to ensure the bucket name is unique
resource "random_string" "unique" {
  length  = 8
  special = false
  upper   = false
}
```

