**Terraform Program Description:**

This Terraform program will create a single AWS S3 bucket with a static website configuration. The bucket will be created in a specified AWS region and will have a unique name. The website configuration will include an index document and an error document, both set to "index.html" and "error.html" respectively.

**Terraform HCL Program:**
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Define a variable for the S3 bucket name
variable "bucket_name" {
  type        = string
  default     = "my-example-bucket"
  description = "The name of the S3 bucket"
}

# Create an IAM role for the S3 bucket
resource "aws_iam_role" "s3_bucket_role" {
  name        = "${var.bucket_name}-role"
  description = "IAM role for the S3 bucket"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

# Create the S3 bucket
resource "aws_s3_bucket" "example" {
  bucket = var.bucket_name
  acl    = "public-read"

  # Enable static website hosting
  website {
    index_document = "index.html"
    error_document = "error.html"
  }

  # Create the IAM policy for the S3 bucket
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Principal = "*"
        Resource = "${aws_s3_bucket.example.arn}/*"
      }
    ]
  })
}

# Output the S3 bucket URL
output "bucket_url" {
  value       = "https://${aws_s3_bucket.example.bucket}.s3.${aws_region.current.name}"
  description = "The URL of the S3 bucket"
}
```
Note: The `aws_region` variable is assumed to be set to the current region, and the `aws_iam_role` resource is created with a policy that grants public read access to the S3 bucket.

This configuration should be deployable and create a working S3 bucket with a static website configuration.

