resource "aws_iam_role" "logging_role" {
  name        = "S3LoggingAccess"
  description = "Allows S3 to write server access logs"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

# Create IAM Policy for logging
resource "aws_iam_policy" "logging_policy" {
  name        = "S3LoggingPolicy"
  description = "Policy for S3 to write server access logs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Effect = "Allow"
        Resource = aws_cloudwatch_log_group.logging_group.arn
      }
    ]
  })
}

# Create IAM Policy Attachment for logging
