I'll create a Terraform program that sets up the necessary infrastructure for the autograder.

**Description:**

This Terraform configuration will create the following resources:

1. An S3 bucket to store student code and results
2. An IAM role for the CodeBuild service to access the S3 bucket
3. An IAM policy for the CodeBuild service to access the S3 bucket
4. A CodeBuild project to run student code in a specific environment
5. An S3 bucket policy to allow CodeBuild to read from and write to the S3 bucket

**Terraform Program:**
```terraform
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Create an S3 bucket for student code and results
resource "aws_s3_bucket" "student_code" {
  bucket = "student-code-${random_string.random_id}"
  acl    = "private"

  versioning {
    enabled = true
  }
}

# Create an IAM role for CodeBuild
resource "aws_iam_role" "codebuild_role" {
  name        = "codebuild-role-${random_string.random_id}"
  description = "CodeBuild service role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for CodeBuild to access S3
resource "aws_iam_policy" "codebuild_policy" {
  name        = "codebuild-policy-${random_string.random_id}"
  description = "CodeBuild policy to access S3"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        Effect = "Allow"
        Resource = "${aws_s3_bucket.student_code.arn}/*"
      },
    ]
  })
}

# Attach the IAM policy to the CodeBuild role
resource "aws_iam_role_policy_attachment" "codebuild_attach" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_policy.arn
}

# Create a CodeBuild project
resource "aws_codebuild_project" "autograder" {
  name = "autograder-project"

  source {
    type     = "GITHUB"
    location = "https://github.com/your-username/your-repo.git"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/python3.8-ubuntu"
  }

  artifacts {
    type = "S3"
    paths = ["**/*"]
    name  = "autograder-${random_string.random_id}"
  }

  source_versions_to_build = ["main"]

  environment_variable {
    name  = "S3_BUCKET_NAME"
    value = aws_s3_bucket.student_code.id
  }
}

# Create an S3 bucket policy to allow CodeBuild to read from and write to the S3 bucket
resource "aws_s3_bucket_policy" "student_code_policy" {
  bucket = aws_s3_bucket.student_code.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCodeBuildRead"
        Effect    = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        Resource = "${aws_s3_bucket.student_code.arn}/*"
      },
    ]
  })
}
```
This configuration assumes you have a GitHub repository set up for the CS class. You'll need to replace the `your-username` and `your-repo` placeholders with the actual values for your repository.

Note that this configuration uses a `random_string` resource to generate a unique name for the S3 bucket and CodeBuild project. This is to ensure that the resources are created with a unique name and can be deleted without conflicts.

