**Terraform Program Description:**

This Terraform program will create the necessary AWS infrastructure for an autograder system that integrates with GitHub. The program will:

1. Create an S3 bucket to store student code and results.
2. Create an IAM role for the CodeBuild project to assume, which will allow CodeBuild to access the S3 bucket.
3. Create an IAM policy that grants the CodeBuild project permission to read from the S3 bucket.
4. Create an IAM role for the CodeBuild project to run in, which will allow CodeBuild to access AWS services.
5. Create an AWS CodeBuild project that will run student code in a Docker environment.
6. Configure the CodeBuild project to use a Docker image that includes the necessary dependencies for the autograder.

**Terraform HCL Program:**
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an S3 Bucket
resource "aws_s3_bucket" "autograder_bucket" {
  bucket = "autograder-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }
}

# Create an IAM Role for CodeBuild to assume
resource "aws_iam_role" "codebuild_role" {
  name        = "autograder-codebuild-role"
  description = "Role for CodeBuild to assume"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM Policy for CodeBuild to read from S3
resource "aws_iam_policy" "s3_policy" {
  name        = "autograder-s3-policy"
  description = "Policy for CodeBuild to read from S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Resource = aws_s3_bucket.autograder_bucket.arn
      }
    ]
  })
}

# Attach the IAM Policy to the CodeBuild Role
resource "aws_iam_role_policy_attachment" "s3_policy_attach" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.s3_policy.arn
}

# Create an IAM Role for CodeBuild to run in
resource "aws_iam_role" "codebuild_run_role" {
  name        = "autograder-codebuild-run-role"
  description = "Role for CodeBuild to run in"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the IAM Policy to the CodeBuild Run Role
resource "aws_iam_role_policy_attachment" "codebuild_run_policy_attach" {
  role       = aws_iam_role.codebuild_run_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonCodeBuildServiceRole"
}

# Create an AWS CodeBuild Project
resource "aws_codebuild_project" "autograder_project" {
  name         = "autograder-project"
  description  = "Autograder project"

  source {
    type     = "GITHUB"
    location = "https://github.com/your-username/your-repo-name"
  }

  environment {
    type              = "DOCKER"
    dockerImageName  = "your-docker-image-name"
  }
}
```
Note that you should replace the placeholders (`your-username`, `your-repo-name`, and `your-docker-image-name`) with the actual values for your GitHub repository and Docker image.

