Description:
The Terraform program will create an AWS infrastructure to support an autograder for a CS class. It will consist of the following components:
- A VPC with a public and private subnet.
- An IAM role for CodeBuild with permissions to access the GitHub repository and read the environment variables from the CodeBuild project.
- A CodeBuild project that runs students' code in a specific environment and stores the result.
- A CodeBuild project environment that prevents the students' code from reaching the internet.

Here is the Terraform HCL program that defines the infrastructure:

```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "autograder_vpc" {
  cidr_block = "10.0.0.0/16"
}

# Create a public subnet
resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = true
}

# Create a private subnet
resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = false
}

# Create a route table for the public subnet
resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.autograder_vpc.id
}

# Create a route to the public subnet
resource "aws_route" "public_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.autograder_igw.id
}

# Create an internet gateway
resource "aws_internet_gateway" "autograder_igw" {
  vpc_id = aws_vpc.autograder_vpc.id
}

# Create a security group for the CodeBuild project
resource "aws_security_group" "autograder_sg" {
  name        = "autograder-sg"
  description = "Security group for the CodeBuild project"
  vpc_id      = aws_vpc.autograder_vpc.id

  ingress {
    description = "Allow traffic from the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.autograder_vpc.cidr_block]
  }
}

# Create an IAM role for CodeBuild
resource "aws_iam_role" "autograder_role" {
  name        = "autograder-role"
  description = "IAM role for the CodeBuild project"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the IAM role policy to the role
resource "aws_iam_role_policy" "autograder_policy" {
  role   = aws_iam_role.autograder_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "codecommit:GetCommit",
          "codecommit:GetRepository",
          "codecommit:GetBlob",
          "codecommit:GetGitReferences",
          "codecommit:GetRepositoryPermissions",
        ]
        Effect = "Allow"
        Resource = aws_codecommit_repository.autograder_repo.arn
      },
      {
        Action = [
          "codebuild:GetProject",
          "codebuild:GetSourceCredentials",
          "codebuild:GetBuilds",
          "codebuild:StartBuild",
          "codebuild:GetProjectReports",
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Create a CodeBuild project
