**Main Configuration File: main.tf**
```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create a VPC for the autograder
resource "aws_vpc" "autograder_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "Autograder VPC"
  }
}

# Create a subnet for the autograder
resource "aws_subnet" "autograder_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "Autograder Subnet"
  }
}

# Create a security group for the autograder
resource "aws_security_group" "autograder_sg" {
  name        = "autograder-sg"
  description = "Security group for autograder"
  vpc_id      = aws_vpc.autograder_vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an IAM role for the CodeBuild project
resource "aws_iam_role" "codebuild_role" {
  name        = "autograder-codebuild-role"
  description = "IAM role for autograder CodeBuild project"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the CodeBuild project
resource "aws_iam_policy" "codebuild_policy" {
  name        = "autograder-codebuild-policy"
  description = "IAM policy for autograder CodeBuild project"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect = "Allow"
        Resource = "${aws_s3_bucket.autograder_bucket.arn}/*"
      },
      {
        Action = "codebuild:StartBuild"
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

