```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an S3 bucket to store code build output
resource "aws_s3_bucket" "codebuild_output" {
  bucket = "codebuild-output-1234567890"
  acl    = "private"
  versioning {
    enabled = true
  }
}

# Create an AWS VPC with cidr_block "10.0.0.0/16"
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

# Create an AWS VPC subnet with cidr_block "10.0.0.0/24"
resource "aws_subnet" "example" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.0.0/24"
  availability_zone = "us-west-2a"
}

# Create an AWS Security Group linked to the VPC, with no ingress and egress
resource "aws_security_group" "example" {
  name        = "example-sg"
  description = "Allow inbound traffic"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = []
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = []
  }
}

# Create an AWS CodeBuild project resource
resource "aws_codebuild_project" "example" {
  name         = "example-codebuild"
  source      = "GITHUB"
  source_info {
    type     = "GITHUB"
    location = "github.com/source-location"
  }
  environment {
    type            = "LINUX_CONTAINER"
    compute_type    = "BUILD_GENERAL1_SMALL"
    image           = "alpine"
  }
  artifacts {
    type = "S3"
    location = aws_s3_bucket.codebuild_output.bucket
  }
  vpc_config {
    vpc_id = aws_vpc.example.id
    subnets = [aws_subnet.example.id]
  }
}
```
This Terraform configuration creates the following AWS resources:
- An S3 bucket named `codebuild-output-1234567890` with versioning enabled
- An AWS VPC with cidr_block `10.0.0.0/16`
- An AWS VPC subnet with cidr_block `10.0.0.0/24`
- An AWS Security Group linked to the VPC, with no ingress and egress rules
- An AWS CodeBuild project named `example-codebuild`, which builds from a GitHub repository at `github.com/source-location`. The CodeBuild project uses an Alpine Linux image, with a small compute type, and stores artifacts in the S3 bucket `codebuild-output-1234567890`. The VPC and subnets from the example VPC and subnet resources are used for the CodeBuild project's VPC configuration.

