Here is a description of the Terraform program I will define:

**Program Description:**

The Terraform program will create an AWS IAM role for the EC2 instance, an EC2 instance itself, and configure AWS Backup to back up the EC2 instance every day at midnight. The program will also create an IAM role for AWS Backup to use for the backup operations.

Here is the Terraform HCL program:

```hcl
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the EC2 instance
resource "aws_iam_role" "ec2_role" {
  name               = "ec2-role"
  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

# Create an IAM policy for the EC2 instance
resource "aws_iam_policy" "ec2_policy" {
  name        = "ec2-policy"
  description = "EC2 policy"

  policy      = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": "s3:*",
      "Resource": "*"
    }
  ]
}
EOF
}

# Attach the IAM policy to the EC2 role
resource "aws_iam_role_policy_attachment" "ec2_attach" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = aws_iam_policy.ec2_policy.arn
}

# Create an EC2 instance
resource "aws_instance" "example" {
  ami           = "ami-0c94855ba95c71c99"
  instance_type = "t2.micro"
  vpc_security_group_ids = [aws_security_group.example.id]
  iam_instance_profile = aws_iam_instance_profile.ec2_profile.name
}

# Create an IAM role for AWS Backup
resource "aws_iam_role" "backup_role" {
  name               = "backup-role"
  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "backup.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

# Create an IAM policy for AWS Backup
resource "aws_iam_policy" "backup_policy" {
  name        = "backup-policy"
  description = "Backup policy"

  policy      = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": "backup:*",
      "Resource": "*"
    }
  ]
}
EOF
}

# Attach the IAM policy to the AWS Backup role
resource "aws_iam_role_policy_attachment" "backup_attach" {
  role       = aws_iam_role.backup_role.name
  policy_arn = aws_iam_policy.backup_policy.arn
}

# Create an IAM instance profile for the EC2 instance
resource "aws_iam_instance_profile" "ec2_profile" {
  name = "ec2-profile"
  role = aws_iam_role.ec2_role.name
}

# Create an AWS Backup vault
resource "aws_backup_vault" "example" {
  name = "example-vault"
}

# Create a backup plan for the EC2 instance
resource "aws_backup_plan" "example" {
  name = "example-plan"

  rule {
    rule_name         = "daily-backup"
    target_backup_vault_name = aws_backup_vault.example.name
    schedule            = "cron(0 0 * * ? *)"
    backup_options {
      Lifecycle {
        DeleteAfter = 7
      }
    }
    iam_role_arn = aws_iam_role.backup_role.arn
    id = "daily-backup"
  }
}
```

This program creates the necessary IAM roles, policies, and instance profile for the EC2 instance. It also creates an AWS Backup vault and a backup plan that backs up the EC2 instance every day at midnight. Note that you need to replace the `ami-0c94855ba95c71c99` with a valid Amazon Machine Image (AMI) in your region.

