Here is the description of the Terraform program:

The Terraform program will create the following AWS resources:

* An EC2 instance with a specified AMI and instance type
* An EC2 key pair for secure SSH access
* An AWS Backup vault for storing backups
* An AWS Backup plan to schedule daily backups of the EC2 instance

Here is the Terraform HCL program:
```
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
  access_key = var.aws_access_key
  secret_key = var.aws_secret_key
}

# Create an AWS Backup vault
resource "aws_backup_vault" "example" {
  name = "example-vault"
}

# Create an AWS Backup plan
resource "aws_backup_plan" "example" {
  name         = "example-plan"
  backup_window {
    start = "00:00"
    end   = "02:00"
  }
  schedule {
    frequency = "Daily"
  }
}

# Create an EC2 instance
resource "aws_instance" "example" {
  ami           = "ami-abc123"
  instance_type = "t2.micro"
  key_name      = aws_key_pair.example.id
}

# Create an EC2 key pair
resource "aws_key_pair" "example" {
  key_name   = "example-key"
  public_key = file("${path.module}/id_rsa.pub")
}

# Add the EC2 instance to the Backup plan
resource "aws_backup_selection" "example" {
  name       = "example-selection"
  iam_role   = aws_iam_role.example.arn
  plan       = aws_backup_plan.example.id
  backup_selection {
    target {
      backup_vault_name = aws_backup_vault.example.id
      iis {
        instance_type = "EC2"
        selection_tag {
          key    = "Backup"
          value  = "Enabled"
        }
      }
    }
  }
}

# Create an IAM role for the Backup plan
resource "aws_iam_role" "example" {
  name        = "example-role"
  description = "For Backup plan"
}

resource "aws_iam_policy" "example" {
  name        = "example-policy"
  description = "For Backup plan"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "BackupPlanPolicy"
        Effect    = "Allow"
        Action    = ["backup:StartBackupJob", "backup:ListBackupJobs", "backup:ListBackupVaults", "backup:CreateBackupVault", "backup:StartBackupJob"]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "example" {
  role       = aws_iam_role.example.id
  policy_arn = aws_iam_policy.example.arn
}
```
Note that you will need to provide the `aws_access_key` and `aws_secret_key` variables, and create an SSH key pair (e.g. `id_rsa`) in the same directory as the Terraform configuration.

