  name        = "backup-role"
  description = "IAM role for AWS Backup"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the AWS Backup service
resource "aws_iam_policy" "backup_policy" {
  name        = "backup-policy"
  description = "IAM policy for AWS Backup"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "backup:*"
        Effect = "Allow"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "backup_attach" {
  role       = aws_iam_role.backup_role.name
  policy_arn = aws_iam_policy.backup_policy.arn
}

# Create a new AWS Backup vault
resource "aws_backup_vault" "example_vault" {
  name = "example-vault"
}

# Create a new AWS Backup plan
resource "aws_backup_plan" "example_plan" {
  name = "example-plan"

  rule {
    RuleName         = "daily-rule"
    EnableBackup     = true
    BackupOptions    = "IncludeRecoveryPointTags=tag1,tag2"
    TargetVaultName  = aws_backup_vault.example_vault.name
    Lifecycle {
      DeleteAfter = 7
    }
    AdvancedBackupSettings {
      ResourceType = "EC2"
    }
    Schedule {
      Name = "daily-schedule"
      Frequency = "Daily"
      StartTime = "23:59"
      Timezone = "UTC"
    }
  }
}

# Create a new AWS EC2 key pair
resource "aws_key_pair" "example_key" {
  key_name   = "example-key"
  public_key = file("./key.pub")
}

# Create a new AWS EC2 instance
resource "aws_instance" "example_instance" {
  ami           = "ami-0c94855ba95c71c99"
  instance_type = "t2.micro"
  key_name      = aws_key_pair.example_key.key_name
}

# Create a new AWS Backup selection
resource "aws_backup_selection" "example_selection" {
  name = "example-selection"
  iam_role_arn = aws_iam_role.backup_role.arn
  plan      = aws_backup_plan.example_plan.name
  target_vault_name = aws_backup_vault.example_vault.name
  lifecycle {
    delete_after = 7
  }
  advanced_backup_settings {
    resource_type = "EC2"
  }
  selection_tag {
    key   = "aws:resource-type"
    value = "EC2"
  }
}
```

