# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for EventBridge
resource "aws_iam_role" "eventbridge_role" {
  name        = "eventbridge-role"
  description = "Role for EventBridge"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for EventBridge
resource "aws_iam_policy" "eventbridge_policy" {
  name        = "eventbridge-policy"
  description = "Policy for EventBridge"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = "*"
        Effect    = "Allow"
      }
    ]
  })
}

# Attach IAM policy to the role
resource "aws_iam_role_policy_attachment" "eventbridge_attach" {
  role       = aws_iam_role.eventbridge_role.name
  policy_arn = aws_iam_policy.eventbridge_policy.arn
}

# Create EventBridge schedule
resource "aws_cloudwatch_event_rule" "daily_rule" {
  name                = "daily-rule"
  description         = "Rule to trigger daily at 7 UTC"
  schedule_expression = "cron(0 7 * * ? *)"
}

# Create EventBridge target
resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.daily_rule.name
  target_id = "lambda-id"
  arn       = "arn:aws:lambda:us-west-2:123456789012:function:your-lambda-function-name" // replace with your Lambda function ARN
}

# Create EventBridge rule and target
resource "aws_cloudwatch_event_rule" "daily_rule_target" {
  name                = "daily-rule-target"
  description         = "Rule to trigger daily at 7 UTC and target Lambda"
  schedule_expression = "cron(0 7 * * ? *)"

  depends_on = [
    aws_cloudwatch_event_rule.daily_rule,
    aws_cloudwatch_event_target.lambda_target,
  ]
}
```

