The Terraform program will create the necessary AWS resources to run a code every day at 7 UTC using AWS EventBridge and AWS Lambda.

Here is the Terraform HCL program:
```
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
  default_tags {
    tags = {
      Environment = "dev"
    }
  }
}

# Create a new IAM role for the Lambda function
resource "aws_iam_role" "lambda_exec" {
  name        = "lambda-exec-role"
  description = "Execution role for the Lambda function"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })
}

# Create a new IAM policy for the Lambda function
resource "aws_iam_policy" "lambda_policy" {
  name        = "lambda-policy"
  description = "Policy for the Lambda function"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "logs:CreateLogGroup"
        Effect = "Allow"
        Resource = aws_cloudwatch_log_group.lambda_log.arn
      },
      {
        Action = "logs:CreateLogStream"
        Effect = "Allow"
        Resource = "${aws_cloudwatch_log_group.lambda_log.arn}:*"
      },
      {
        Action = "logs:PutLogEvents"
        Effect = "Allow"
        Resource = "${aws_cloudwatch_log_group.lambda_log.arn}:*"
      },
    ]
  })
}

# Create a new IAM role policy attachment for the Lambda function
resource "aws_iam_role_policy_attachment" "lambda_attach" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = aws_iam_policy.lambda_policy.arn
}

# Create a new Lambda function
resource "aws_lambda_function" "lambda_func" {
  filename      = "lambda_function_payload.zip"
  function_name = "lambda-function"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
}

# Create a new CloudWatch log group for the Lambda function
resource "aws_cloudwatch_log_group" "lambda_log" {
  name              = "/aws/lambda/${aws_lambda_function.lambda_func.function_name}"
  retention_in_days = 30
}

# Create a new EventBridge rule to trigger the Lambda function every day at 7 UTC
resource "aws_cloudwatch_event_rule" "daily_event" {
  name        = "daily-event"
  description = "Triggers the Lambda function every day at 7 UTC"

  schedule_expression = "cron(0 7 * * ? *)"
}

# Create a new EventBridge target to invoke the Lambda function
resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.daily_event.name
  target_id = "lambda-target"
  arn       = aws_lambda_function.lambda_func.arn
}

# Create a new EventBridge permission for the Lambda function
resource "aws_cloudwatch_event_permission" "lambda_permission" {
  rule      = aws_cloudwatch_event_rule.daily_event.name
  target_id = aws_cloudwatch_event_target.lambda_target.id
  action    = "lambda:InvokeFunction"
}
```
