**Terraform Program Description:**

This Terraform program will create an AWS EventBridge event rule named "cron" that triggers a Lambda function every day at 7 UTC. The Lambda function will be deployed using a deployment package from the specified path "./supplement/lambda_func.zip".

**Terraform HCL Program:**
```terraform
provider "aws" {
  region = "us-west-2"
}

variable "lambda_zip_path" {
  default = "./supplement/lambda_func.zip"
}

variable "lambda_function_name" {
  default = "my_lambda_func"
}

variable "event_rule_name" {
  default = "cron"
}

variable "event_rule_schedule_expression" {
  default = "cron(0 7 * * ? *)"
}

resource "aws_iam_role" "lambda_exec" {
  name        = "lambda-exec-role"
  description = "Execution role for Lambda function"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_lambda_function" "my_lambda" {
  filename      = var.lambda_zip_path
  function_name = var.lambda_function_name
  handler       = "index.handler"
  role          = aws_iam_role.lambda_exec.arn

  depends_on = [aws_iam_role_policy_attachment.lambda_policy]
}

resource "aws_iam_role_policy_attachment" "lambda_policy" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_eventbridge_rule" "cron" {
  name                = var.event_rule_name
  schedule_expression = var.event_rule_schedule_expression

  target {
    arn    = aws_lambda_function.my_lambda.arn
    input  = "{\"key\":\"value\"}"
    id     = "lambda-target"
  }
}
```
