  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM Policy for CloudFront
resource "aws_iam_policy" "cloudfront_s3_policy" {
  name        = "CloudFrontS3Policy"
  description = "Policy for CloudFront to access S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Resource = aws_s3_bucket.video_bucket.arn
      },
      {
        Action = "s3:ListBucket"
        Effect = "Allow"
        Resource = aws_s3_bucket.video_bucket.arn
      }
