```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
  access_key = var.aws_access_key
  secret_key = var.aws_secret_key
}

# Create an S3 bucket for storing video content
resource "aws_s3_bucket" "video_bucket" {
  bucket = "video-streaming-site"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# Create an S3 bucket for storing videos in different regions
resource "aws_s3_bucket" "video_bucket_region" {
  count  = 2
  bucket = "video-streaming-site-region-${count.index}"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  depends_on = [aws_s3_bucket.video_bucket]
}

# Create an IAM role for CloudFront
resource "aws_iam_role" "cloudfront_role" {
  name        = "cloudfront-role"
  description = "Role for CloudFront to access S3 bucket"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      },
    ]
  })
}

# Create an IAM policy for CloudFront
resource "aws_iam_policy" "cloudfront_policy" {
  name        = "cloudfront-policy"
  description = "Policy for CloudFront to access S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Resource = aws_s3_bucket.video_bucket.arn
      },
    ]
  })
}

# Attach IAM policy to IAM role
resource "aws_iam_role_policy_attachment" "cloudfront_attach" {
  role       = aws_iam_role.cloudfront_role.name
  policy_arn = aws_iam_policy.cloudfront_policy.arn
}
```

