provider "aws" {
  region = "us-west-2"
}

# Create an S3 bucket for storing video content
resource "aws_s3_bucket" "video_bucket" {
  bucket = "my-video-streaming-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }

  lifecycle_rule {
    enabled = true

    expiration {
      days = 365
    }
  }
}

# Create an S3 bucket policy for granting CloudFront access
resource "aws_s3_bucket_policy" "video_bucket_policy" {
  bucket = aws_s3_bucket.video_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFront"
        Effect    = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.video_bucket.arn}/*"
        Condition = {
          Bool   = "aws:SourceIpAddress"
        }
      }
    ]
  })
}

# Create an AWS Route53 zone
resource "aws_route53_zone" "video_streaming_zone" {
  name = "example.com"
}

# Create an AWS CloudFront distribution
resource "aws_cloudfront_distribution" "video_distribution" {
  origin {
    domain_name = aws_s3_bucket.video_bucket.bucket_regional_domain_name
    origin_id   = aws_s3_bucket.video_bucket.id
    custom_origin_config {
      http_port  = 80
      https_port = 443
      origin_protocol_policy = "http-only"
      origin_ssl_protocols = ["TLSv1"]
    }
  }

  enabled = true
  comment  = "Video Streaming Distribution"

  default_cache_behavior {
    allowed_methods = ["GET", "HEAD", "PUT", "POST", "DELETE"]
    target_origin_id = aws_s3_bucket.video_bucket.id

    forwarded_values {
      query_string = true

      cookies {
        forward = "all"
      }
    }

    viewer_protocol_policy = "allow-all"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations        = ["US", "CA", "GB", "FR", "DE"]
    }
  }

  viewer_certificate {
    acm_certificate_arn = ""
    ssl_support_method  = "sni-only"
    iam_certificate_id  = ""
  }
}

# Create an AWS CloudFront origin access control
resource "aws_cloudfront_origin_access_control" "video_origin_access_control" {
  name   = "video-origin-access-control"
  cloudfront_distribution_arn = aws_cloudfront_distribution.video_distribution.arn
  origin_access_control_policy {
    allow_s3_reference_accounts = false
    origins = [
      {
        id   = aws_s3_bucket.video_bucket.id
        domains = ["${aws_s3_bucket.video_bucket.bucket_regional_domain_name}"]
      }
    ]
  }
}

# Create an AWS Route53 record set
resource "aws_route53_record" "video_streaming_record" {
  zone_id = aws_route53_zone.video_streaming_zone.id
  name    = "example.com"
  type    = "CNAME"
  ttl     = 300
  records = [aws_cloudfront_distribution.video_distribution.domain_name]
}
```

This Terraform configuration creates the necessary resources for a video streaming site that distributes video content globally using AWS CloudFront, S3, and Route53. It includes:

*   An S3 bucket for storing video content
*   An S3 bucket policy for granting CloudFront access
*   An AWS Route53 zone
*   An AWS CloudFront distribution
*   An AWS CloudFront origin access control
*   An AWS Route53 record set

