**Description:**
This Terraform configuration creates an AWS CloudFront distribution that serves content from an S3 bucket. The distribution is configured to use an origin access control, which controls access to the S3 bucket. Additionally, the configuration creates an AWS Route53 zone and two Route53 records that point to the CloudFront distribution. The CloudFront origin access control is also created.

**Terraform Configuration:**

```terraform
provider "aws" {
  region = "us-east-1"
}

variable "s3_bucket_name" {
  default = "my-s3-bucket"
}

variable "cloudfront_distribution_name" {
  default = "my-cloudfront-distribution"
}

variable "route53_zone_name" {
  default = "netflix.com"
}

resource "aws_cloudfront_distribution" "main" {
  enabled         = true
  comment         = "CloudFront distribution for S3 bucket"
  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = aws_cloudfront_origin_access_control.main.s3_origin_access_control_cloudfront_distribution_origin_id
    viewer_protocol_policy = "allow-all"
  }
  origin {
    domain_name = aws_s3_bucket.main.website_endpoint
    origin_id   = "s3_video_content_origin"
    origin_access_control_id = aws_cloudfront_origin_access_control.main.id
  }
  price_class = "PriceClass_200"
  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations        = ["US", "CA", "GB", "DE"]
    }
  }
  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

resource "aws_cloudfront_origin_access_control" "main" {
  name              = "my-origin-access-control"
  origin_type       = "s3"
  signing_behavior = "always"
  signing_protocol = "sigv4"
}

resource "aws_s3_bucket" "main" {
  bucket = var.s3_bucket_name
  acl    = "public-read"
}

resource "aws_s3_bucket_website_configuration" "main" {
  bucket = aws_s3_bucket.main.id
  index_document {
    suffix = "index.html"
  }
}

resource "aws_route53_zone" "main" {
  name = var.route53_zone_name
}

resource "aws_route53_record" "main" {
  zone_id = aws_route53_zone.main.id
  name    = var.route53_zone_name
  type    = "A"
  alias {
    name                   = aws_cloudfront_distribution.main.domain_name
    zone_id                = aws_cloudfront_distribution.main.hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "main2" {
  zone_id = aws_route53_zone.main.id
  name    = "www.${var.route53_zone_name}"
  type    = "A"
  alias {
    name                   = aws_cloudfront_distribution.main.domain_name
    zone_id                = aws_cloudfront_distribution.main.hosted_zone_id
    evaluate_target_health = false
  }
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.main.id
}

output "cloudfront_distribution_domain_name" {
  value = aws_cloudfront_distribution.main.domain_name
}
```

