Here's a Terraform configuration that sets up an AWS Load Balancing infrastructure with multiple servers to balance load:

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM Role for the EC2 Instances
resource "aws_iam_role" "ec2_role" {
  name = "ec2-load-balancer-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM Policy for the EC2 Instances
resource "aws_iam_policy" "ec2_policy" {
  name        = "ec2-load-balancer-policy"
  description = "Policy for EC2 Instances"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        Resource = [
          "arn:aws:s3:::my-bucket/*",
        ]
        Effect = "Allow"
      },
      {
        Action = [
          "cloudwatch:PutMetricData",
        ]
        Resource = [
          "*",
        ]
        Effect = "Allow"
      },
    ]
  })
}

# Attach the IAM Policy to the IAM Role
resource "aws_iam_role_policy_attachment" "ec2_attach" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = aws_iam_policy.ec2_policy.arn
}

# Create a VPC
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

# Create a Subnet
resource "aws_subnet" "example" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create a Security Group
resource "aws_security_group" "example" {
  name        = "allow_ssh_http"
  description = "Allow SSH and HTTP"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an EC2 Instance
resource "aws_instance" "example" {
  ami           = "ami-0c94855ba95c71c99"
  instance_type = "t2.micro"
  vpc_security_group_ids = [aws_security_group.example.id]
  subnet_id = aws_subnet.example.id
}

# Create an ELB
resource "aws_elb" "example" {
  name            = "example-elb"
  subnets         = [aws_subnet.example.id]
  security_groups = [aws_security_group.example.id]

  listener {
    instance_port      = 80
    instance_protocol  = "http"
    lb_port            = 80
    lb_protocol        = "http"
  }
}

# Attach the EC2 Instance to the ELB
resource "aws_elb_attachment" "example" {
  elb      = aws_elb.example.id
  instance = aws_instance.example.id
}

# Output the ELB DNS
output "elb_dns" {
  value = aws_elb.example.dns_name
}
```

This Terraform configuration will create the following resources in AWS:

*   A VPC with a CIDR block of 10.0.0.0/16.
*   A subnet with a CIDR block of 10.0.1.0/24 in the us-west-2a zone.
*   An IAM role for the EC2 instances.
