Here is a Terraform configuration to deploy the infrastructure for the video streaming site using AWS services:

**Terraform Program Description:**

This Terraform program will create the following infrastructure:

* A VPC with public and private subnets
* An Internet Gateway (IGW) for the VPC to access the internet
* A Public Load Balancer (ELB) to distribute incoming traffic across multiple EC2 instances
* A Route 53 hosted zone for the video streaming site
* A set of EC2 instances to run the video streaming application
* A set of Security Groups to control inbound and outbound traffic

**Terraform HCL Program:**
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create a VPC with public and private subnets
module "vpc" {
  source = "terraform-aws-modules/vpc/aws"

  name            = "video-streaming-vpc"
  cidr            = "10.0.0.0/16"
  public_subnets  = ["10.0.1.0/24", "10.0.2.0/24"]
  private_subnets = ["10.0.3.0/24", "10.0.4.0/24"]

  azs             = ["us-west-2a", "us-west-2b"]

  tags = {
    Name        = "video-streaming-vpc"
    Environment = "dev"
  }
}

# Create an Internet Gateway (IGW) for the VPC
resource "aws_internet_gateway" "igw" {
  vpc_id = module.vpc.vpc_id

  tags = {
    Name        = "video-streaming-igw"
    Environment = "dev"
  }
}

# Create a Public Load Balancer (ELB)
resource "aws_elb" "elb" {
  name            = "video-streaming-elb"
  subnets         = module.vpc.public_subnets
  security_groups = [aws_security_group.elb.id]

  tags = {
    Name        = "video-streaming-elb"
    Environment = "dev"
  }
}

# Create a Route 53 hosted zone
resource "aws_route53_zone" "zone" {
  name = "video-streaming.example.com"

  tags = {
    Name        = "video-streaming-zone"
    Environment = "dev"
  }
}

# Create a set of EC2 instances to run the video streaming application
resource "aws_instance" "instance" {
  ami           = "ami-abc123"
  instance_type = "t2.micro"
  vpc_security_group_ids = [aws_security_group.instance.id]
  subnet_id        = module.vpc.private_subnets[0]

  tags = {
    Name        = "video-streaming-instance"
    Environment = "dev"
  }
}

# Create a set of Security Groups to control inbound and outbound traffic
resource "aws_security_group" "elb" {
  name        = "video-streaming-elb-sg"
  description = "Security Group for the ELB"
  vpc_id      = module.vpc.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "instance" {
  name        = "video-streaming-instance-sg"
  description = "Security Group for the EC2 instance"
  vpc_id      = module.vpc.vpc_id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```
Note that this is just one possible way to configure the infrastructure for the video streaming site. You may need to modify the configuration to fit your specific requirements.

Also, you will need to create an AWS credentials file to authenticate with the AWS provider. You can do this by running `aws configure` and following the prompts to enter your AWS access key and secret key.

Once you have created the Terraform configuration, you can run `terraform init` to initialize the working directory and `terraform apply` to deploy the infrastructure.

