**Description of Terraform Program**

The Terraform program will create the following resources:

1. A VPC with two public subnets in different availability zones.
2. Two security groups: one for database access and another for PostgreSQL instance.
3. A PostgreSQL database instance within the VPC, accessible and secured by the designated security group.

**Terraform HCL Program**
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Set default values for variables
variable "vpc_cidr" {
  type        = string
  default     = "10.0.0.0/16"
  description = "CIDR block for the VPC"
}

variable "subnet_cidr" {
  type        = string
  default     = "10.0.1.0/24"
  description = "CIDR block for the public subnet"
}

variable "db_instance_class" {
  type        = string
  default     = "db.t2.micro"
  description = "Instance class for the PostgreSQL database"
}

# Create VPC with public subnets
resource "aws_vpc" "example" {
  cidr_block = var.vpc_cidr
}

resource "aws_subnet" "public" {
  vpc_id     = aws_vpc.example.id
  cidr_block = var.subnet_cidr
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "public_2" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

# Create security groups
resource "aws_security_group" "db_access" {
  name        = "db-access-sg"
  description = "Security group for database access"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "postgres_instance" {
  name        = "postgres-instance-sg"
  description = "Security group for PostgreSQL instance"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.db_access.id]
  }
}

# Create PostgreSQL database instance
resource "aws_db_instance" "example" {
  allocated_storage     = 20
  engine                = "postgres"
  engine_version        = "12.4"
  instance_class        = var.db_instance_class
  name                  = "exampledb"
  username              = "exampleuser"
  password              = "examplepassword"
  vpc_security_group_ids = [aws_security_group.postgres_instance.id]
  vpc_id                = aws_vpc.example.id
  skip_final_snapshot  = true
}
```
