**Terraform Program Description:**
This Terraform program will create a VPC with public subnets, a security group for database access, and a PostgreSQL database instance within the VPC. The PostgreSQL instance will be version 17.1, have a capacity of 5GB, and will be accessible and secured by a designated security group.

**Terraform HCL Program:**
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
  access_key = "YOUR_ACCESS_KEY"
  secret_key = "YOUR_SECRET_KEY"
}

# Set variables
variable "vpc_cidr" {
  type = string
  default = "10.0.0.0/16"
}

variable "subnet_cidr" {
  type = string
  default = "10.0.1.0/24"
}

variable "security_group_name" {
  type = string
  default = "db-security-group"
}

variable "postgres_instance_name" {
  type = string
  default = "my-postgres-instance"
}

variable "postgres_username" {
  type = string
  default = "myusername"
}

variable "postgres_password" {
  type = string
  sensitive = true
}

# Create VPC
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
}

# Create public subnets
resource "aws_subnet" "public" {
  cidr_block = var.subnet_cidr
  vpc_id     = aws_vpc.main.id
  availability_zone = "us-west-2a"
}

# Create security group for database access
resource "aws_security_group" "db" {
  name        = var.security_group_name
  description = "Security group for database access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create PostgreSQL instance
resource "aws_rds_instance" "main" {
  allocated_storage = 5
  engine           = "postgres"
  engine_version  = "17.1"
  instance_class   = "db.t2.micro"
  name             = var.postgres_instance_name
  username         = var.postgres_username
  password         = var.postgres_password
  vpc_security_group_ids = [aws_security_group.db.id]
  db_subnet_group_name = aws_db_subnet_group.main.name
}

# Create database subnet group
resource "aws_db_subnet_group" "main" {
  name       = "main"
  description = "Database subnet group"
  subnet_ids = [aws_subnet.public.id]
}

# Output the PostgreSQL instance endpoint
output "postgres_endpoint" {
  value = aws_rds_instance.main.endpoint
}
```
