**Terraform HCL Program:**
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Define variables
variable "vpc_cidr" {
  type        = string
  default     = "10.0.0.0/16"
  description = "The CIDR block for the VPC"
}

variable "subnet_cidr" {
  type        = string
  default     = "10.0.1.0/24"
  description = "The CIDR block for the public subnet"
}

variable "database_instance_name" {
  type        = string
  default     = "mysql-instance"
  description = "The name of the MySQL database instance"
}

variable "database_username" {
  type        = string
  default     = "admin"
  description = "The username for the MySQL database instance"
}

variable "database_password" {
  type        = string
  sensitive   = true
  default     = "password"
  description = "The password for the MySQL database instance"
}

