Here is the Terraform program that meets the specified requirements:

```hcl
# Provider configuration
provider "aws" {
  region = "us-west-2"
}

# Variables
variable "db_instance_class" {
  type = string
  default = "db.t3.micro"
}

variable "db_storage_size" {
  type = number
  default = 20
}

variable "db_engine_version" {
  type = string
  default = "12.6"
}

variable "db_backup_retention_period" {
  type = string
  default = "7"
}

# Create a new VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

# Create subnets
resource "aws_subnet" "subnet1" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "subnet1"
  }
}

resource "aws_subnet" "subnet2" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "subnet2"
  }
}

# Create a KMS key for encryption
resource "aws_kms_key" "database_key" {
  description = "KMS key for database encryption"
  deletion_window_in_days = 10
  tags = {
    Name = "database-key"
  }
}

# Create a custom parameter group
resource "aws_rds_cluster_parameter_group" "database" {
  name        = "custom-parameter-group"
  family      = "postgres12"
  description = "Custom parameter group for PostgreSQL"

  parameter {
    name  = "logging_collector"
    value = "on"
  }

  parameter {
    name  = "log_min_messages"
    value = "warning"
  }
}

# Create a security group
resource "aws_security_group" "database" {
  name        = "database-sg"
  description = "Security group for database access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an RDS instance
resource "aws_rds_cluster" "database" {
  cluster_identifier      = "database-cluster"
  engine                  = "postgres"
  engine_version          = var.db_engine_version
  instance_class          = var.db_instance_class
  database_name           = "mydatabase"
  master_username         = "mydatabaseuser"
  master_password         = "mydatabasepassword"
  vpc_security_group_ids  = [aws_security_group.database.id]
  db_subnet_group_name    = "database-subnet-group"
  parameter_group_name    = aws_rds_cluster_parameter_group.database.name
  backup_retention_period = var.db_backup_retention_period
  port                    = 5432
  skip_final_snapshot     = true

  lifecycle {
    prevent_destroy = true
  }

  # Enable multi-AZ deployment
  apply_immediately = true

  # Enable encryption
  kms_key_id = aws_kms_key.database_key.arn

  # Enable storage
  storage_type = "gp2"
  allocated_storage = var.db_storage_size
}

# Create a database instance
resource "aws_rds_cluster_instance" "database" {
  count           = 1
  cluster_id      = aws_rds_cluster.database.id
  instance_class  = var.db_instance_class
  engine          = "postgres"
  engine_version  = var.db_engine_version
  identifier      = "database-instance-${count.index}"
  instance_type = "db.t3.micro"
  vpc_security_group_ids = [aws_security_group.database.id]
}
```

This Terraform program provisions a secure PostgreSQL database instance within a specified AWS VPC. The database instance is configured with specifications like storage size, engine version, multi-AZ deployment for high availability, and encryption using a KMS key. The database instance is also configured with a custom parameter group for PostgreSQL settings, and a security group to manage access.

