```hcl
provider "aws" {
  region = "us-west-2"
}

# Creating KMS key for database encryption
resource "aws_kms_key" "pg_key" {
  description             = "KMS Key for PostgreSQL database"
  deletion_window_in_days = 10
  is_enabled               = true
}

# Creating Key policy for the KMS key
resource "aws_kms_key_policy" "pg_key_policy" {
  key_id = aws_kms_key.pg_key.key_id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "Enable IAM User Permissions"
        Effect    = "Allow"
        Principal = {"AWS": "arn:aws:iam::123456789012:root"}
        Action    = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
        Resource  = "*"
      }
    ]
  })
}

# Creating VPC for database
resource "aws_vpc" "pg_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
}

# Creating subnets for the database
resource "aws_subnet" "pg_subnet1" {
  vpc_id            = aws_vpc.pg_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = true
}

resource "aws_subnet" "pg_subnet2" {
  vpc_id            = aws_vpc.pg_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  map_public_ip_on_launch = true
}

# Creating RDS cluster parameter group
resource "aws_rds_cluster_parameter_group" "pg_param_group" {
  name        = "pg-parameter-group"
  family      = "postgres14"
  description = "Custom parameter group for PostgreSQL"

  parameter {
    name  = "rds.force_ssl"
    value = "1"
  }
}

# Creating RDS cluster
resource "aws_rds_cluster" "pg_cluster" {
  cluster_identifier = "pg-cluster"
  engine             = "postgres"
  engine_version     = "14.2"
  instance_class     = "db.t2.micro"
  vpc_security_group_ids = [aws_security_group.pg_sg.id]
  database_name     = "pg-database"
  parameter_group_name = aws_rds_cluster_parameter_group.pg_param_group.name
  skip_final_snapshot = true
  final_db_snapshot_identifier = "pg-snapshot"
  kms_key_id = aws_kms_key.pg_key.key_id
  vpc_id = aws_vpc.pg_vpc.id
}

# Creating RDS instance
resource "aws_rds_cluster_instance" "pg_instance" {
  instance_class = "db.t2.micro"
  engine         = "postgres"
  engine_version = "14.2"
  cluster_identifier = aws_rds_cluster.pg_cluster.id
  identifier = "pg-instance"
  db_instance_parameter_group_name = aws_rds_cluster_parameter_group.pg_param_group.name
}

# Creating security group for database
resource "aws_security_group" "pg_sg" {
  name        = "pg-sg"
  description = "Security group for PostgreSQL database"
  vpc_id      = aws_vpc.pg_vpc.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```

