```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
  version = "4.30.0"
}

# Define variables
variable "vpc_id" {
  type = string
  default = "vpc-12345678"
}

variable "public_subnets" {
  type = list(string)
  default = ["subnet-12345678a", "subnet-12345678b"]
}

variable "instance_class" {
  type = string
  default = "db.r5.large"
}

variable "username" {
  type = string
  default = "airbyte"
}

variable "password" {
  type = string
  sensitive = true
  default = "airbyte123"
}

# Create a RDS instance
resource "aws_db_instance" "airbyte_postgres" {
  identifier           = "airbyte-postgres"
  instance_class       = var.instance_class
  engine               = "postgres"
  engine_version       = "15.1"
  username             = var.username
  password             = var.password
  port                 = 5432
  publicly_accessible = true
  vpc_security_group_ids = [aws_security_group.airbyte_postgres.id]
  subnet_ids           = var.public_subnets
}

# Create a security group
resource "aws_security_group" "airbyte_postgres" {
  name        = "airbyte-postgres"
  description = "Allow inbound traffic for airbyte-postgres"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Output the RDS instance endpoint
output "airbyte_postgres_endpoint" {
  value = aws_db_instance.airbyte_postgres.endpoint
}
```

Please replace `vpc-12345678` with your actual VPC ID and `subnet-12345678a` and `subnet-12345678b` with your actual public subnets IDs.

