# Provider Configuration
provider "aws" {
  region = "us-west-2"
}

# Variable Configuration
variable "environment" {
  type        = string
  default     = "dev"
  description = "Environment (dev, prod, etc.)"
}

variable "instance_class" {
  type        = string
  default     = "db.t2.micro"
  description = "Instance class (db.t2.micro, db.t2.small, etc.)"
}

variable "instance_size" {
  type        = string
  default     = "20"
  description = "Instance size in GB"
}

# VPC and Subnet Configuration
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Security Group Configuration
resource "aws_security_group" "example" {
  name        = "example-sg"
  description = "Example security group"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# IAM Role Configuration
resource "aws_iam_role" "example" {
  name        = "example-iam-role"
  description = "Example IAM role for PostgreSQL instance"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "example" {
  role       = aws_iam_role.example.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}

# RDS PostgreSQL Instance Configuration
resource "aws_rds_cluster" "example" {
  cluster_identifier        = "example-cluster"
  engine                    = "postgres"
  instance_class            = var.instance_class
  database_name             = "example"
  master_username           = "admin"
  master_password           = "password"
  vpc_security_group_ids    = [aws_security_group.example.id]
  vpc_id                    = aws_vpc.example.id
  backup_retention_period   = "5"  # Days
  preferred_backup_window   = "03:00-06:00"  # UTC
  skip_final_snapshot       = true
}

output "cluster_endpoint" {
  value = aws_rds_cluster.example.endpoint
}

output "cluster_username" {
  value = aws_rds_cluster.example.master_username
}

output "cluster_password" {
  value = aws_rds_cluster.example.master_password
  sensitive = true
}
```

