Here is the Terraform HCL program to set up a PostgreSQL database instance in AWS:
```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create a VPC with a custom CIDR block
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
  tags       = {
    Name = "example-vpc"
  }
}

# Create a subnet within the VPC
resource "aws_subnet" "example" {
  cidr_block              = "10.0.1.0/24"
  vpc_id                  = aws_vpc.example.id
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = false
  tags                    = {
    Name = "example-subnet"
  }
}

# Create a security group for the database instance
resource "aws_security_group" "example" {
  name        = "example-sg"
  description = "Allow inbound traffic from the VPC"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.example.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a database instance in the VPC
resource "aws_rds_instance" "example" {
  allocated_storage     = 20
  instance_class        = "db.t2.micro"
  engine                = "postgres"
  engine_version        = "12.6"
  username              = "admin"
  password              = "password"
  vpc_security_group_ids = [aws_security_group.example.id]
  db_subnet_group_name  = aws_db_subnet_group.example.name
  skip_final_snapshot   = true
  publicly_accessible   = false

  maintenance_window {
    preferred_maintenance_window = "sun:06:00-sun:08:00"
  }
}

# Create a database subnet group
resource "aws_db_subnet_group" "example" {
  name       = "example-subnet-group"
  subnet_ids = [aws_subnet.example.id]
}

# Create a database parameter group with major version upgrade enabled
resource "aws_db_parameter_group" "example" {
  name      = "example-param-group"
  family    = "postgres12"
  parameters = [
    {
      name  = "rds.force_ssl"
      value = "1"
    },
  ]
  version_requirement {
    name     = "12.6"
    strictness = "MAJOR"
  }
}
```
Note: This configuration assumes you are using AWS region `us-west-2`. You can change the region in the `provider` block to match your needs.

