  count             = 2
  cidr_block        = "10.0.1.${count.index}.0/24"
  availability_zone = "us-west-2a"  # Replace with your desired AZ
  vpc_id            = aws_vpc.rds_vpc.id
  tags = {
    Name = "RDS-Subnet-${count.index}"
  }
}

# Create a security group for the RDS cluster
