  name        = "RDS-SG"
  description = "Allow inbound RDS traffic"
  vpc_id      = aws_vpc.rds_vpc.id

  ingress {
    description = "RDS MySQL"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

