Here is a description of the Terraform program I will define:

The Terraform program will create a basic Amazon Lightsail instance with user data. The program will:

* Create an Amazon Lightsail instance with a t2.micro instance type
* Configure the instance to use a public IP address
* Set user data to a script that will be executed on first boot
* Create a new Lightsail key pair for SSH access
* Create a new Lightsail instance from an Amazon Machine Image (AMI)

And here is the Terraform HCL program:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "instance_name" {
  type        = string
  default     = "my-lightsail-instance"
  description = "Name of the Lightsail instance"
}

variable "user_data" {
  type        = string
  default     = "#!/bin/bash\necho 'Hello World!' > /tmp/test.txt"
  description = "User data script to run on first boot"
}

variable "key_name" {
  type        = string
  default     = "my-lightsail-key"
  description = "Name of the Lightsail key pair"
}

resource "aws_lightsail_instance" "this" {
  name              = var.instance_name
  availability_zone = "us-west-2a"
  blueprints        = ["amazon-linux-2"]
  instance_size    = "micro"
  user_data         = base64encode(var.user_data)
}

resource "aws_lightsail_key_pair" "this" {
  name       = var.key_name
  public_key = file("~/.ssh/id_rsa.pub")
}

output "instance_public_ip" {
  value       = aws_lightsail_instance.this.public_ip
  description = "Public IP address of the Lightsail instance"
}
```

This program creates a Lightsail instance with a t2.micro instance type and uses the public IP address. The user data script is executed on first boot and creates a test file in the `/tmp` directory. A new Lightsail key pair is created and used for SSH access. The public IP address of the Lightsail instance is output as an attribute.

