  default = "example-ssh-key"
}

resource "aws_lightsail_instance" "example" {
  name              = var.instance_name
  source_name       = var.instance_size
  availability_zone = var.region
  snapshot_enable  = true

  connection {
    type        = "ssh"
    host        = self.assigned_public_ip
    user        = "ubuntu"
    private_key = file("~/.ssh/${var.ssh_key_name}.pem")
  }
}

output "lightsail_instance_public_ip" {
  value = aws_lightsail_instance.example.assigned_public_ip
}
```

Note that this program assumes you have the AWS CLI configured and the necessary permissions to create a Lightsail instance and SSH key. Also, you need to replace `~/.ssh/${var.ssh_key_name}.pem` with your actual path to the private key file.

