```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
  version = "4.27.0"
}

# Set up the Lightsail instance
resource "aws_lightsail_instance" "example" {
  name               = "example-lightsail-instance"
  source_name        = "Amazon Linux 2 3.x"
  blueprints         = ["amazon-linux-2"]
  bundle_id          = "nano_1_0"
  user_data           = <<-EOF
    #!/bin/bash
    echo "Hello, World!"
  EOF
}

# Allocate a static IP
