  name = "example-static-ip"
}

# Attach the static IP to the Lightsail instance
resource "aws_lightsail_instance_static_ip_attachment" "example" {
  instance_name = aws_lightsail_instance.example.name
  static_ip_name = aws_lightsail_static_ip.example.name
}

variable "instance_name" {
  default = "example-lightsail-instance"
}

variable "static_ip_name" {
  default = "example-static-ip"
}
```

Please note that you need to replace "us-west-2" with your preferred AWS region, and "nano_1_0" with the desired bundle size for your Lightsail instance.

