resource "aws_iam_role" "lightsail_instance_role" {
  name        = "lightsail_instance_role"
  description = "IAM role for Lightsail instance"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

# Create a Lightsail instance with a database
resource "aws_lightsail_instance" "database_instance" {
  name           = "managed-database"
  instance_type  = "dev.db-d"
  key_pair_name = "my_key_pair"
  user_data       = base64encode(data.template_file.user_data.rendered)

  iam_instance_profile  = aws_iam_role.lightsail_instance_role.arn

