I'll create a Terraform program that creates an AWS Lightsail database, configures daily backups, and schedules maintenance tasks.

Here's the Terraform HCL program that accomplishes this:

```hcl
# Configure the AWS Lightsail provider
provider "aws" {
  region = "us-west-2"
}

# Create an AWS Lightsail database
resource "aws_lightsail_database" "example" {
  name              = "example-mysql"
  username          = "exampleuser"
  password          = "examplepassword"
  master_user_name  = "exampleuser"
  master_user_password = "examplepassword"
  engine            = "mysql"
  min_connections   = 10
  max_connections   = 50
}

# Create an IAM role for the Lightsail database
resource "aws_iam_role" "example" {
  name = "example-lightsail-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      },
    ]
  })
}

# Create an IAM policy for the Lightsail database
resource "aws_iam_policy" "example" {
  name        = "example-lightsail-policy"
  description = "Policy for Lightsail database"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "lightsail:GetDbInstance",
        Effect = "Allow"
        Resource = "arn:aws:lightsail:*:*:db-instance/example-mysql"
      },
      {
        Action = "lightsail:GetDbSnapshot",
        Effect = "Allow"
        Resource = "arn:aws:lightsail:*:*:db-snapshot/example-mysql-snapshot"
      },
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "example" {
  role       = aws_iam_role.example.name
  policy_arn = aws_iam_policy.example.arn
}

# Configure daily backups
resource "aws_lightsail_database_backup" "example" {
  database_name = aws_lightsail_database.example.name
  schedule      = "daily at 16:00:00 to 16:30:00"
}

# Configure maintenance window
resource "aws_lightsail_db_instance" "example" {
  depends_on = [aws_lightsail_database.example]

  name              = "example-mysql"
  username          = "exampleuser"
  password          = "examplepassword"
  master_user_name  = "exampleuser"
  master_user_password = "examplepassword"
  engine            = "mysql"
  min_connections   = 10
  max_connections   = 50
  maintenance_window {
    day_of_week = "tuesday"
    from        = "17:00"
    to          = "17:30"
  }
}
```

This Terraform program creates an AWS Lightsail database, configures daily backups to take place between 16:00 and 16:30 each day, and schedules maintenance tasks to take place on Tuesdays between 17:00 and 17:30. The IAM role and policy are created to allow Lightsail to perform the necessary actions.

**Terraform Program Description:**

The Terraform program will create an AWS Lightsail PostgreSQL database instance. When the instance is deleted, Terraform will trigger a final snapshot of the database to be created, allowing for easy database recovery or migration.

**Terraform HCL Program:**
```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_instance_name" {
  type        = string
  default     = "my-postgres-instance"
  description = "Name of the Lightsail PostgreSQL instance"
}

variable "db_username" {
  type        = string
  default     = "mydbuser"
  description = "Username for the PostgreSQL instance"
}

variable "db_password" {
  type        = string
  sensitive   = true
  default     = "mydbpassword"
  description = "Password for the PostgreSQL instance"
}

variable "db_port" {
  type        = number
  default     = 5432
  description = "Port for the PostgreSQL instance"
}

resource "aws_lightsail_database" "this" {
  name           = var.db_instance_name
  username       = var.db_username
  password       = var.db_password
  master_user_name = var.db_username
  master_user_password = var.db_password
  port            = var.db_port

  lifecycle {
    prevent_destroy = true
  }
}

resource "null_resource" "db_snapshot" {
  triggers = {
    instance_id = aws_lightsail_database.this.id
  }

  provisioner "local-exec" {
    command = <<EOT
      aws lightsail get-instance-access-keys --instance-arn ${aws_lightsail_database.this.arn} | jq '.instance_access_keys[0].access_key_id'
    EOT
  }

  provisioner "local-exec" {
    command = <<EOT
      aws lightsail create-db-snapshot --instance-arn ${aws_lightsail_database.this.arn} --db-snapshot-name ${aws_lightsail_database.this.name}-snapshot
    EOT
  }
}

resource "null_resource" "destroy_trigger" {
  triggers = {
    instance_id = aws_lightsail_database.this.id
  }

  provisioner "local-exec" {
    when    = destroy
    command = <<EOT
      aws lightsail delete-db-snapshot --db-snapshot-name ${aws_lightsail_database.this.name}-snapshot
    EOT
  }
}
```
In this Terraform program:

* We define an AWS provider with region set to `us-west-2`.
* We declare three variables for database instance name, username, and password. Note that the password is marked as sensitive.
* We create a Lightsail PostgreSQL database instance using the `aws_lightsail_database` resource.
* We use two `null_resource` blocks to create a final snapshot of the database on deletion. The first `null_resource` block creates a snapshot when the instance is updated. The second `null_resource` block creates a snapshot when the instance is deleted.

Please note that you need to run `terraform init` and `terraform apply` to deploy the infrastructure. Also, replace the sensitive variables with your own values.

**Description of Terraform Program:**
The Terraform program will be named "aws_lightsail_postgres" and will create a Postgres database instance on AWS Lightsail. The program will use the AWS provider to create the database instance, and will also configure the database to enable immediate apply, allowing changes to be applied immediately instead of waiting for a maintenance window.

**Terraform HCL Program:**
```terraform
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Create a new Lightsail database instance
resource "aws_lightsail_database" "example" {
  name     = "example-postgres"
  username = "exampleuser"
  password = "examplepassword"
  bundle   = "dev"

  # Enable immediate apply
  maintenance_window_preference = "immediate"

  # Use a custom port for PostgreSQL
  port {
    port_number = 5432
  }
}

# Create a new Lightsail instance to run the database
resource "aws_lightsail_instance" "example" {
  name              = "example-instance"
  availability_zone = "us-west-2a"
  blueprint_id      = "postgis-ubuntu"
  bundle_id        = "dev"
  user_data        = "#!/bin/bash\n apt-get update -y\n apt-get install -y postgresql postgresql-contrib\n"

  // Assign the database instance to this instance
  database_name = aws_lightsail_database.example.name
  username      = aws_lightsail_database.example.username
  password      = aws_lightsail_database.example.password
}

# Create an IAM role for the instance
resource "aws_iam_role" "example" {
  name        = "example-role"
  description = "Role for the example instance"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

// Attach the IAM role to the instance
resource "aws_lightsail_instance_attachment" "example" {
  instance_name = aws_lightsail_instance.example.name
  role_name      = aws_iam_role.example.name
}

// Output the database connection information
output "database_connection_info" {
  value = "host=${aws_lightsail_database.example.hostname} port=${aws_lightsail_database.example.port} user=${aws_lightsail_database.example.username} password=${aws_lightsail_database.example.password}"
}
```
This Terraform program creates a new Postgres database instance on AWS Lightsail, a new Lightsail instance to run the database, and an IAM role for the instance. The database instance is configured to enable immediate apply, and the instance is attached to the IAM role. The program also outputs the database connection information.

