Here is a Terraform configuration to create an AWS storage for long-term data and backup:

**main.tf**
```terraform
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
  access_key = var.aws_access_key
  secret_key = var.aws_secret_key
}

# Create an S3 bucket for long-term data storage
resource "aws_s3_bucket" "long_term_data" {
  bucket = "long-term-data-storage"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# Create an IAM role for S3 access
resource "aws_iam_role" "s3_access" {
  name        = "s3-access-role"
  description = "Allow access to S3 bucket for long-term data storage"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# Attach a policy to the IAM role for S3 access
resource "aws_iam_role_policy" "s3_access_policy" {
  name   = "s3-access-policy"
  role   = aws_iam_role.s3_access.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        Effect = "Allow"
        Resource = "${aws_s3_bucket.long_term_data.arn}/*"
      },
    ]
  })
}

# Create an EC2 instance to serve as a data backup node
resource "aws_instance" "data_backup_node" {
  ami           = "ami-abcd1234"
  instance_type = "t2.micro"
  vpc_security_group_ids = [aws_security_group.data_backup_node.id]

  connection {
    type        = "ssh"
    host        = self.public_ip
    user        = "ec2-user"
    private_key = file("~/.ssh/your-private-key")
  }

  provisioner "remote-exec" {
    inline = [
      "sudo apt-get update -y",
      "sudo apt-get install aws-cli -y",
    ]
  }
}

# Create a security group for the data backup node
resource "aws_security_group" "data_backup_node" {
  name        = "data-backup-node-sg"
  description = "Allow inbound traffic on port 22 for SSH access"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Output the S3 bucket name and ARN
output "s3_bucket_name" {
  value = aws_s3_bucket.long_term_data.id
}

output "s3_bucket_arn" {
  value = aws_s3_bucket.long_term_data.arn
}
```

You'll need to provide the AWS access key and secret key as variables:

**variables.tf**
```terraform
variable "aws_access_key" {
  type = string
  default = ""
}

variable "aws_secret_key" {
  type = string
  default = ""
}
```

This configuration creates an S3 bucket with versioning enabled and server-side encryption, an IAM role and policy for S3 access, and an EC2 instance as a data backup node. Make sure to replace the `ami-abcd1234` with the correct AMI ID for your region and update the private key file path in the `aws_instance` resource.

