Here is a Terraform configuration that creates an S3 Glacier vault with notification service.

**Terraform Configuration**
```hcl
provider "aws" {
  region = "us-west-2"
}

# Define a variable for the S3 bucket name
variable "bucket_name" {
  default = "my-glacier-vault"
}

# Create an S3 bucket for Glacier vault
resource "aws_s3_bucket" "glacier_vault" {
  bucket = var.bucket_name
  acl    = "private"

  versioning {
    enabled = true
  }
}

# Create an S3 Glacier vault
resource "aws_s3controlvault" "glacier_vault" {
  name      = "${var.bucket_name}-glacier"
  access_type = "DEEP_ARCHIVE"
}

# Create an S3 Glacier vault notification configuration
resource "aws_s3controlvault_notification_configuration" "glacier_vault" {
  vault_name = aws_s3controlvault.glacier_vault.name

  eventBridge_configuration {
    role_arn = aws_iam_role.glacier_vault.arn
  }
}

# Create an IAM role for Glacier vault notifications
resource "aws_iam_role" "glacier_vault" {
  name        = "${var.bucket_name}-glacier-notification-role"
  description = "IAM role for Glacier vault notifications"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policy to the IAM role for S3 access
resource "aws_iam_policy" "glacier_vault_policy" {
  name        = "${var.bucket_name}-glacier-notification-policy"
  description = "IAM policy for Glacier vault notifications"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Resource = "${aws_s3_bucket.glacier_vault.arn}/*"
      },
      {
        Action = "s3:PutObject"
        Effect = "Allow"
        Resource = "${aws_s3_bucket.glacier_vault.arn}/*"
      }
    ]
  })
}

# Attach policy to the IAM role
resource "aws_iam_role_policy_attachment" "glacier_vault_attach" {
  role       = aws_iam_role.glacier_vault.name
  policy_arn = aws_iam_policy.glacier_vault_policy.arn
}
```
This configuration creates:

* An S3 bucket for storing Glacier vault metadata
* An S3 Glacier vault with deep archive access
* An IAM role for Glacier vault notifications
* An IAM policy for S3 access attached to the IAM role

Please note that you should update the `bucket_name` variable to a unique value for your Glacier vault.

You can apply this configuration using `terraform init` and `terraform apply`.

