**Terraform Configuration: S3 Glacier Vault with Access Policy**

This Terraform configuration will create an S3 Glacier vault with a custom access policy.

### Description

This configuration creates:

1. An S3 bucket to store the Glacier vault.
2. An S3 Glacier vault within the bucket.
3. An access policy for the Glacier vault, granting read and write access to the specified IAM role.

### Terraform Configuration (main.tf)
```hcl
# Provider Configuration
provider "aws" {
  region = "us-west-2"
}

# Variable: Glacier Vault Name
variable "glacier_vault_name" {
  type        = string
  default     = "my-glacier-vault"
  description = "Name of the S3 Glacier vault"
}

# Variable: IAM Role ARN
variable "iam_role_arn" {
  type        = string
  default     = "arn:aws:iam::123456789012:role/my-glacier-access-role"
  description = "ARN of the IAM role with access to the Glacier vault"
}

# Create S3 Bucket
resource "aws_s3_bucket" "glacier_bucket" {
  bucket = "my-glacier-bucket"
  acl    = "private"

  tags = {
    Name        = "S3 Glacier Bucket"
    Environment = "Dev"
  }
}

# Create S3 Glacier Vault
resource "aws_glacier_vault" "vault" {
  name        = var.glacier_vault_name
  account_id  = data.aws_caller_identity.current.account_id
  description = "S3 Glacier Vault for storing backups"

  access_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "",
      "Effect": "Allow",
      "Principal": {
        "AWS": "${var.iam_role_arn}"
      },
      "Action": "glacier:InitiateVaultLock",
      "Resource": "${aws_glacier_vault.vault.id}"
    }
  ]
}
EOF
}

# Data Source: AWS Caller Identity
data "aws_caller_identity" "current" {}

# Output: S3 Glacier Vault ID
output "glacier_vault_id" {
  value = aws_glacier_vault.vault.id
}
```
Note: This configuration uses the `aws_caller_identity` data source to retrieve the current AWS account ID. Also, the `iam_role_arn` variable should be replaced with the actual ARN of the IAM role with access to the Glacier vault.

