Here is a description of the Terraform program I will define:

**Program Description:**
This Terraform program will create an S3 Glacier vault with a Vault Lock, which is a feature that helps protect sensitive data stored in Glacier by enforcing a set of policies and access controls. The program will create the following resources:

* An S3 Glacier vault
* An S3 bucket to store the Glacier vault metadata
* An IAM role for the Glacier vault
* A Vault Lock configuration to enforce policies and access controls on the Glacier vault

And here is the Terraform HCL program that implements this description:
```hcl
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
  access_key = var.aws_access_key
  secret_key = var.aws_secret_key
}

# Create an S3 bucket to store Glacier vault metadata
resource "aws_s3_bucket" "glacier_bucket" {
  bucket = "glacier-vault-metadata"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# Create an S3 Glacier vault
resource "aws_glacier_vault" "example_vault" {
  name = "example-glacier-vault"
  depends_on = [aws_s3_bucket.glacier_bucket]
}

# Create an IAM role for the Glacier vault
resource "aws_iam_role" "glacier_vault_role" {
  name        = "glacier-vault-role"
  description = "Role for the Glacier vault"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the IAM role to the Glacier vault
resource "aws_iam_role_policy_attachment" "glacier_vault_attach" {
  role       = aws_iam_role.glacier_vault_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonGlacierServiceRolePolicyForAWSCloudHSM"
}

# Create a Vault Lock configuration
resource "aws_glacier_vault_lock_configuration" "example_lock" {
  vault_name = aws_glacier_vault.example_vault.name
  rule {
    event_type  = "ALL"
    event_status = "ENABLING"
    permission = "DENY"
  }
}
```
Note: You will need to provide your AWS access key and secret key as variables (`aws_access_key` and `aws_secret_key`) for this program to work.

