  name        = "glacier-vault-policy"
  description = "Policy for S3 Glacier Vault"
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "glacier:GetVaultAccessPolicy",
          "glacier:PutVaultAccessPolicy"
        ]
        Resource = "*"
        Effect    = "Allow"
      }
    ]
  })
}

# Create a new IAM Policy Document for the S3 Glacier Vault
