  statement {
    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:DeleteObject",
      "s3:ListBucket"
    ]
    resources = [
      "arn:aws:s3:::my-glacier-vault",
      "arn:aws:s3:::my-glacier-vault/*"
    ]
  }
}

# Attach the IAM Policy to the IAM Role
