Here is a Terraform configuration that creates an S3 Glacier vault and sets up a notification configuration to send an email when the archive retrieval is completed.

**Terraform Configuration**
```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an S3 Glacier vault
resource "aws_s3_glacier_vault" "example" {
  name = "example-vault"
}

# Create an S3 bucket to store notifications
resource "aws_s3_bucket" "example" {
  bucket = "example-notifications"

  # Enable versioning
  versioning {
    enabled = true
  }

  # Enable server-side encryption
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# Create an IAM role for the S3 bucket notification
resource "aws_iam_role" "example" {
  name        = "example-bucket-notification-role"
  description = "Role for S3 bucket notification"

  # Trust relationship with S3
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      },
    ]
  })
}

# Attach a policy to the IAM role for S3 bucket notification
resource "aws_iam_policy" "example" {
  name        = "example-bucket-notification-policy"
  description = "Policy for S3 bucket notification"

  # Policy document
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.example.id}/NOTIFICATIONS/"
      },
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "example" {
  role       = aws_iam_role.example.name
  policy_arn = aws_iam_policy.example.arn
}

# Set up a notification configuration for the S3 Glacier vault
resource "aws_s3_bucket_notification" "example" {
  bucket = aws_s3_bucket.example.id

  depends_on = [aws_s3_bucket.example]

  # Set up a notification event for archive retrieval completion
  event = "archive-retrieval-complete"

  # Set up a notification configuration
  notification {
    topic {
      sns_topic = aws_sns_topic.example.arn
    }

    filter {
      prefix = "archive-retrieval-complete"
    }
  }
}

# Create an SNS topic to send notifications
resource "aws_sns_topic" "example" {
  name = "example-notifications"
}

# Create an SNS topic policy to allow the IAM role to publish to the topic
resource "aws_sns_topic_policy" "example" {
  topic = aws_sns_topic.example.arn

  # Policy document
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowPublish"
        Effect    = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sns:Publish"
      },
    ]
  })
}

# Output the S3 Glacier vault ARN
output "glacier_vault_arn" {
  value       = aws_s3_glacier_vault.example.arn
  description = "The ARN of the S3 Glacier vault"
}

# Output the S3 bucket ARN
output "s3_bucket_arn" {
  value       = aws_s3_bucket.example.arn
  description = "The ARN of the S3 bucket"
}

# Output the SNS topic ARN
output "sns_topic_arn" {
  value       = aws_sns_topic.example.arn
  description = "The ARN of the SNS topic"
}
```
This Terraform configuration creates an S3 Glacier vault, an S3 bucket to store notifications, an IAM role for the S3 bucket notification, an IAM policy for the S3 bucket notification, and an SNS topic to send notifications. The configuration also sets up a notification event for archive retrieval completion and attaches the necessary policies to the IAM role.

Note that this configuration assumes that you have the necessary credentials and permissions to create the resources in your AWS account. Additionally, this configuration uses the `aws` provider version 3.x, so make sure to update your Terraform version if you're using an older version.

