Here is a Terraform program that establishes an Network Load Balancer (NLB) in AWS:

**Description:**
This Terraform program will create the following resources:
- An Internet-facing Network Load Balancer (NLB) in a specified AWS region
- A target group for the NLB
- An IAM role for the NLB to assume
- A VPC and subnet for the NLB to use
- A security group for the NLB to use

**Terraform HCL Program:**
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Define the VPC and subnet for the NLB
resource "aws_vpc" "nlb_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "nlb_subnet" {
  cidr_block = "10.0.1.0/24"
  vpc_id     = aws_vpc.nlb_vpc.id
  availability_zone = "us-west-2a"
}

# Define the security group for the NLB
resource "aws_security_group" "nlb_sg" {
  name        = "nlb-sg"
  description = "Security group for the NLB"
  vpc_id      = aws_vpc.nlb_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Define the target group for the NLB
resource "aws_lb_target_group" "nlb_tg" {
  name     = "nlb-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.nlb_vpc.id
}

# Define the NLB
resource "aws_lb" "nlb" {
  name               = "nlb"
  internal           = false
  load_balancer_type = "network"
  subnets            = [aws_subnet.nlb_subnet.id]
  security_groups    = [aws_security_group.nlb_sg.id]

  depends_on = [aws_lb_target_group.nlb_tg]
}

# Define the IAM role for the NLB
resource "aws_iam_role" "nlb_iam_role" {
  name        = "nlb-iam-role"
  description = "IAM role for the NLB"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "nlb.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the IAM role to the NLB
resource "aws_lb_attachment" "nlb_attachment" {
  alb_target_group_arn = aws_lb_target_group.nlb_tg.arn
  target_group_arn     = aws_lb_target_group.nlb_tg.arn
  target_id            = aws_lb.nlb.id
  target_type          = "instance"
  load_balancer_arn    = aws_lb.nlb.arn
}

# Output the NLB DNS name
output "nlb_dns_name" {
  value = aws_lb.nlb.dns_name
}
```
This Terraform program creates all the necessary resources to establish an Network Load Balancer in AWS. The NLB is created in a specified region, and it uses a target group, security group, VPC, and subnet. The IAM role for the NLB is also created and attached to the NLB. The NLB DNS name is output as an attribute.

