Here is a Terraform configuration that creates a Load Balancer (ELB) that forwards traffic to a Network Load Balancer (NLB):

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the NLB
resource "aws_iam_role" "nlb_role" {
  name        = "nlb-role"
  description = "NLB execution role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "nlb.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the NLB
resource "aws_iam_policy" "nlb_policy" {
  name        = "nlb-policy"
  description = "NLB policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:ModifyNetworkInterfaceAttribute",
          "ec2:AttachNetworkInterface",
          "ec2:DetachNetworkInterface",
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "nlb_attach" {
  role       = aws_iam_role.nlb_role.name
  policy_arn = aws_iam_policy.nlb_policy.arn
}

# Create the NLB
resource "aws_lb" "nlb" {
  name               = "nlb"
  internal           = false
  load_balancer_type = "application"
  subnets            = ["subnet-12345678", "subnet-90123456"]
}

# Create the target group
resource "aws_lb_target_group" "nlb_tg" {
  name     = "nlb-tg"
  port     = 80
  protocol = "HTTP"
  target_type = "ip"
  vpc_id = "vpc-12345678"
}

# Create the target group attachment
resource "aws_lb_target_group_attachment" "nlb_attach" {
  target_group_arn = aws_lb_target_group.nlb_tg.arn
  target_id        = "instance-12345678"
  port             = 80
}

# Create the ELB
resource "aws_elb" "elb" {
  name            = "elb"
  subnets         = ["subnet-12345678", "subnet-90123456"]
  security_groups = ["sg-12345678"]

  listener {
    instance_port      = 80
    instance_protocol  = "http"
    lb_port            = 80
    lb_protocol        = "http"
  }

  # Forward traffic from the ELB to the NLB
  connection_draining = true
  cross_zone_load_balancing = true

  health_check {
    healthy_threshold   = 3
    unhealthy_threshold = 10
    timeout             = 5
    target              = "HTTP:80/"
    interval            = 30
  }
}
```

This configuration creates:

*   An IAM role for the NLB
*   An IAM policy for the NLB
*   An IAM role policy attachment for the NLB
*   A Network Load Balancer (NLB)
*   A target group for the NLB
*   A target group attachment for the NLB
*   An Elastic Load Balancer (ELB) that forwards traffic to the NLB

Please note that you need to replace the subnet IDs, security group IDs, and instance ID with your actual resources. Also, make sure to update the region in the provider configuration to match your AWS region.

