Here is a Terraform configuration that creates an Elastic Load Balancer (ELB) with a redirect action using the ALB (Application Load Balancer) in AWS.

**Description:**
This configuration creates an ALB with a target group, listener, and redirect action. The ALB will listen on port 80 (HTTP) and redirect any traffic to a target group with a URL path of "/redir" on port 8080. The redirect action will be enabled for all HTTP requests.

**Terraform Configuration:**
```hcl
provider "aws" {
  region = "us-west-2"
}

variable "lb_name" {
  type        = string
  default     = "redirect-lb"
  description = "The name of the load balancer"
}

variable "target_group_name" {
  type        = string
  default     = "redirect-target-group"
  description = "The name of the target group"
}

variable "listener_port" {
  type        = number
  default     = 80
  description = "The port number of the listener"
}

variable "redirect_port" {
  type        = number
  default     = 8080
  description = "The port number for the redirect"
}

variable "redirect_path" {
  type        = string
  default     = "/redir"
  description = "The URL path for the redirect"
}

resource "aws_alb" "redirect-lb" {
  name            = var.lb_name
  subnets         = ["subnet-01234567", "subnet-89abcdef"]
  security_groups = [aws_security_group.redirect-sg.id]

  tags = {
    Name = var.lb_name
  }
}

resource "aws_alb_target_group" "redirect-target-group" {
  name     = var.target_group_name
  port     = var.redirect_port
  protocol = "HTTP"
  vpc_id   = "vpc-01234567"

  health_check {
    interval            = 30
    path                = "/"
    port                = var.redirect_port
    protocol            = "HTTP"
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = var.target_group_name
  }
}

resource "aws_alb_listener" "redirect-listener" {
  load_balancer_arn = aws_alb.redirect-lb.arn
  port              = var.listener_port
  protocol          = "HTTP"

  default_action {
    target_group_arn = aws_alb_target_group.redirect-target-group.arn
    type             = "forward"
  }
}

resource "aws_alb_listener_rule" "redirect-listener-rule" {
  listener_arn = aws_alb_listener.redirect-listener.arn
  priority     = 1

  action {
    type = "redirect"

    redirect {
      port        = var.redirect_port
      protocol    = "HTTP"
      status_code = "301"
      path        = var.redirect_path
    }
  }
}

resource "aws_security_group" "redirect-sg" {
  name        = "redirect-sg"
  description = "Security group for the load balancer"

  vpc_id = "vpc-01234567"

  ingress {
    from_port   = var.listener_port
    to_port     = var.listener_port
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```
This configuration creates:

* An ALB with a name "redirect-lb" in the us-west-2 region.
* A target group with a name "redirect-target-group" and a URL path of "/redir" on port 8080.
* A listener with a name "redirect-listener" that listens on port 80 (HTTP) and forwards traffic to the target group.
* A listener rule with a priority of 1 that redirects all HTTP requests to the target group with a URL path of "/redir".
* A security group "redirect-sg" with a rule that allows inbound traffic on port 80 (HTTP) from any IP address.

Note: This configuration assumes that you have already set up an AWS account with a VPC and subnets. You will need to replace the placeholder values with your own AWS resource IDs.

