Here is a Terraform HCL program that defines a Load Balancer with a fixed-response action:

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an S3 bucket for the Load Balancer's fixed-response content
resource "aws_s3_bucket" "fixed_response_bucket" {
  bucket = "fixed-response-bucket-1234567890"
  acl    = "private"

  # Enable versioning to track changes to the bucket's contents
  versioning {
    enabled = true
  }
}

# Create an IAM role for the Load Balancer
resource "aws_iam_role" "load_balancer_role" {
  name        = "load-balancer-role-1234567890"
  description = "Role for the Load Balancer"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancer.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the Load Balancer
resource "aws_iam_policy" "load_balancer_policy" {
  name        = "load-balancer-policy-1234567890"
  description = "Policy for the Load Balancer"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect = "Allow"
        Resource = "${aws_s3_bucket.fixed_response_bucket.arn}/*"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "load_balancer_policy_attachment" {
  role       = aws_iam_role.load_balancer_role.name
  policy_arn = aws_iam_policy.load_balancer_policy.arn
}

# Create an ALB (Application Load Balancer) for the fixed-response action
resource "aws_lb" "fixed_response_alb" {
  name               = "fixed-response-alb-1234567890"
  load_balancer_type = "application"
  internal           = false
  security_groups    = [aws_security_group.load_balancer_sg.id]
  subnets            = [aws_subnet.load_balancer_subnet.id]
}

# Create a fixed-response action for the Load Balancer
resource "aws_lb_action" "fixed_response_action" {
  load_balancer_arn = aws_lb.fixed_response_alb.arn
  target_group_arn  = aws_lb_target_group.fixed_response_tg.arn
  type             = "fixed-response"

  fixed_response {
    content = "Hello, World!"
    status_code = "200"
  }
}

# Create a security group for the Load Balancer
resource "aws_security_group" "load_balancer_sg" {
  name        = "load-balancer-sg-1234567890"
  description = "Security group for the Load Balancer"

  # Allow inbound traffic on port 80
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Allow all outbound traffic
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a subnet for the Load Balancer
resource "aws_subnet" "load_balancer_subnet" {
  name            = "load-balancer-subnet-1234567890"
  cidr_block      = "10.0.1.0/24"
  vpc_id          = "vpc-1234567890"
  availability_zone = "us-west-2a"
}

# Create a target group for the Load Balancer
resource "aws_lb_target_group" "fixed_response_tg" {
  name     = "fixed-response-tg-1234567890"
  port     = 80
  protocol = "HTTP"
  vpc_id   = "vpc-1234567890"
}
```

This Terraform configuration creates:

1. An S3 bucket to store the fixed-response content.
2. An IAM role and policy for the Load Balancer.
3. An Application Load Balancer (ALB) to handle incoming requests.
4. A security group for the Load Balancer to allow incoming traffic on port 80.
5. A subnet for the Load Balancer to host the ALB.
6. A target group for the Load Balancer to route requests to the fixed-response action

