Here is a Terraform program that creates an Elastic Load Balancer (ELB) with an authentication action using Amazon Cognito:

**Description:**
This Terraform program creates an ELB with a path-based routing rule. The ELB listens on port 80 and routes traffic to a target group. We also create an authentication action that uses Amazon Cognito to authenticate users.

**Terraform Program:**
```hcl
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the ELB
resource "aws_iam_role" "elb_role" {
  name        = "elb-auth-role"
  description = "Role for ELB with authentication action"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancer.amazonaws.com"
        }
      }
    ]
  })
}

# Attach a policy to the ELB role
resource "aws_iam_role_policy" "elb_policy" {
  name   = "elb-auth-policy"
  role   = aws_iam_role.elb_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "cognito-idp:GetUserPoolClient",
          "cognito-idp:GetUserPool",
          "cognito-idp:AdminGetUser",
        ]
        Resource = "*"
        Effect    = "Allow"
      }
    ]
  })
}

# Create an ELB
resource "aws_elb" "example" {
  name            = "example-elb"
  subnets         = ["subnet-12345678", "subnet-90123456"]
  security_groups = [aws_security_group.example.id]

  # Create an authentication action using Amazon Cognito
  authentication_action {
    type = "authenticate-cognito"
    cognito_user_pool {
      id              = aws_cognito_user_pool.example.id
      cognito_user_pool_client {
        id = aws_cognito_user_pool_client.example.id
      }
    }
  }
}

# Create a security group for the ELB
resource "aws_security_group" "example" {
  name        = "example-elb-sg"
  description = "Security group for ELB"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an Amazon Cognito user pool
resource "aws_cognito_user_pool" "example" {
  name = "example-user-pool"
}

# Create an Amazon Cognito user pool client
resource "aws_cognito_user_pool_client" "example" {
  name = "example-user-pool-client"
  user_pool_id = aws_cognito_user_pool.example.id
}
