**Program Description:**
This Terraform program will create an Amazon Elastic Load Balancer (ELB) with an Authenticate-OIDC (OpenID Connect) action enabled. The ELB will be configured to use an IAM role for authentication with an OpenID Connect (OIDC) provider. The program will also define the necessary IAM roles, security groups, and other resources required for the ELB to function.

Here is the Terraform HCL program:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the ELB to assume
resource "aws_iam_role" "elb_oidc_role" {
  name        = "elb-oidc-role"
  description = "ELB OIDC role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elb.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the ELB OIDC role
resource "aws_iam_policy" "elb_oidc_policy" {
  name        = "elb-oidc-policy"
  description = "ELB OIDC policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRoleWithWebIdentity"
        Effect = "Allow"
        Resource = "*"
        Condition = {
          StringEquals = {
            "oidc.provider" = "oidc.eks.us-west-2.amazonaws.com/id/${aws_iam_openidconnectprovider.example.oidcprovider_arn}"
          }
        }
      }
    ]
  })
}

# Attach the IAM policy to the ELB OIDC role
resource "aws_iam_role_policy_attachment" "elb_oidc_attach" {
  role       = aws_iam_role.elb_oidc_role.name
  policy_arn = aws_iam_policy.elb_oidc_policy.arn
}

# Create an IAM OpenID Connect provider
resource "aws_iam_openidconnectprovider" "example" {
  url = "https://${aws_eks_cluster.example.name}.${aws_eks_cluster.example.endpoint}"
  client_id_list = [
    "sts.amazonaws.com"
  ]
  thumbprint_list = [
    "your_eks_cluster_oidc_fingerprint"
  ]
}

# Create an Amazon Elastic Load Balancer (ELB)
resource "aws_elb" "example" {
  name            = "example-elb"
  subnets         = [aws_subnet.example.id]
  security_groups = [aws_security_group.example.id]

  listener {
    instance_port      = 80
    lb_port            = 80
    protocol           = "HTTP"
    instance_protocol  = "HTTP"
    ssl_certificate_id = "arn:aws:acm:us-west-2:123456789012:certificate/your-certificate-arn"
  }

  health_check {
    healthy_threshold   = 3
    unhealthy_threshold = 10
    timeout             = 5
    target              = "HTTP:80/"
    interval            = 30
  }
}

# Create an IAM role for the ELB to assume
resource "aws_iam_role" "elb_role" {
  name        = "elb-role"
  description = "ELB role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elb.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the IAM policy to the ELB role
resource "aws_iam_role_policy_attachment" "elb_attach" {
  role       = aws_iam_role.elb_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonElasticLoadBalancingServiceRole"
}

