Here is a Terraform configuration to create a Gateway Load Balancer:

**Terraform Configuration:**
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
  version = "4.25.0"
}

# Create an IAM role for the Load Balancer
resource "aws_iam_role" "lb_role" {
  name        = "gateway-lb-role"
  description = "IAM role for the Load Balancer"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the Load Balancer
resource "aws_iam_policy" "lb_policy" {
  name        = "gateway-lb-policy"
  description = "IAM policy for the Load Balancer"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:CreateTags",
          "ec2:DescribeTags",
          "ec2:DescribeInstances",
          "ec2:DescribeVpcs",
          "ec2:DescribeSubnets",
          "ec2:CreateSecurityGroup",
          "ec2:DeleteSecurityGroup",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:DescribeSecurityGroups",
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = "elasticloadbalancing:CreateLoadBalancer",
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = "elasticloadbalancing:CreateTargetGroup",
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = "elasticloadbalancing:AttachTargetGroups",
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = "elasticloadbalancing:DetachTargetGroups",
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = "elasticloadbalancing:DescribeTargetGroups",
        Effect = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Create an IAM role policy attachment for the Load Balancer
resource "aws_iam_role_policy_attachment" "lb_attachment" {
  role       = aws_iam_role.lb_role.name
  policy_arn = aws_iam_policy.lb_policy.arn
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

# Create a subnet
resource "aws_subnet" "main" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create a Load Balancer
resource "aws_elb" "main" {
  name            = "gateway-lb"
  subnets         = [aws_subnet.main.id]
  security_groups = [aws_security_group.lb.id]

  listener {
    instance_port     = 80
    instance_protocol = "http"
    lb_port           = 80
    lb_protocol       = "http"
  }

  health_check {
    healthy_threshold   = 3
    unhealthy_threshold = 10
    timeout             = 5
    target                = "HTTP:80/"
    interval             = 30
  }
}

# Create a security group for the Load Balancer
resource "aws_security_group" "lb" {
  name        = "gateway-lb-sg"
  description = "Security group for the Load Balancer"

  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
