**Terraform Program Description**

This Terraform program will create a basic AWS RDS instance. It will define an Amazon RDS database instance with a specified database engine, instance class, and storage size. Additionally, it will create an IAM role with necessary permissions to access the RDS instance.

**Terraform HCL Program**
```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for RDS instance
resource "aws_iam_role" "rds_role" {
  name        = "rds-role"
  description = "RDS role for database access"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for RDS instance
resource "aws_iam_policy" "rds_policy" {
  name        = "rds-policy"
  description = "RDS policy for database access"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "rds:DescribeDBInstances",
          "rds:DescribeDBClusters",
          "rds:DescribeDBParameters",
          "rds:DescribeDBLogFiles",
          "rds:DescribeEvents",
        ]
        Resource = "*"
        Effect    = "Allow"
      }
    ]
  })
}

# Attach IAM policy to role
resource "aws_iam_role_policy_attachment" "rds_attach" {
  role       = aws_iam_role.rds_role.name
  policy_arn = aws_iam_policy.rds_policy.arn
}

# Create an RDS instance
resource "aws_db_instance" "example" {
  allocated_storage    = 20
  engine               = "mysql"
  instance_class       = "db.t2.micro"
  name                 = "example-db"
  username             = "admin"
  password             = "password123"
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.example.id]
  db_subnet_group_name = aws_db_subnet_group.example.name
}

# Create a database subnet group
