**main.tf**
```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the RDS instance
resource "aws_iam_role" "rds_role" {
  name        = "rds-role"
  description = "Role for RDS instance"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Create an IAM policy for the RDS instance
resource "aws_iam_policy" "rds_policy" {
  name        = "rds-policy"
  description = "Policy for RDS instance"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:*",
          "rds:*"
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "rds_attach" {
  role       = aws_iam_role.rds_role.name
  policy_arn = aws_iam_policy.rds_policy.arn
}

# Create an RDS instance
resource "aws_rds_instance" "example" {
  identifier           = "example-rds"
  instance_class       = "db.t2.micro"
  engine               = "mysql"
  username             = "admin"
  password             = "password"
  publicly_accessible = true
}

# Create a replica of the RDS instance
resource "aws_rds_instance" "replica" {
  identifier           = "example-rds-replica"
  instance_class       = "db.t2.micro"
  engine               = "mysql"
  username             = "admin"
  password             = "password"
  publicly_accessible = true
  replica_identifier  = aws_rds_instance.example.identifier
}
```
