**Description of Terraform Program:**

This Terraform program will create an AWS RDS instance from a specified database snapshot. The RDS instance will be created in a specified VPC, subnet, and availability zone. The program will also create an IAM role for the RDS instance with necessary permissions.

**Terraform HCL Program:**
```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
  access_key = "YOUR_ACCESS_KEY"
  secret_key = "YOUR_SECRET_KEY"
}

# Define variables
variable "database_snapshot_id" {
  type = string
  default = "snap-12345678"
}

variable "db_instance_class" {
  type = string
  default = "db.t2.micro"
}

variable "vpc_id" {
  type = string
  default = "vpc-12345678"
}

variable "subnet_id" {
  type = string
  default = "subnet-12345678"
}

variable "availability_zone" {
  type = string
  default = "us-west-2a"
}

# Create IAM role for RDS instance
resource "aws_iam_role" "rds_role" {
  name        = "rds-role"
  description = "IAM role for RDS instance"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Create IAM policy for RDS instance
resource "aws_iam_policy" "rds_policy" {
  name        = "rds-policy"
  description = "IAM policy for RDS instance"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "rds:DescribeDBInstances",
          "rds:DescribeDBSnapshots",
          "rds:CreateDBInstance",
          "rds:DeleteDBInstance",
          "rds:ModifyDBInstance",
          "rds:RestoreDBInstanceFromDBSnapshot",
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM policy to IAM role
resource "aws_iam_role_policy_attachment" "rds_attach" {
  role       = aws_iam_role.rds_role.name
  policy_arn = aws_iam_policy.rds_policy.arn
}

# Create RDS instance from snapshot
resource "aws_db_instance" "rds_instance" {
  identifier          = "my-rds-instance"
  instance_class      = var.db_instance_class
  engine              = "mysql"
  engine_version      = "5.7.17"
  snapshot_identifier = var.database_snapshot_id
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  vpc_id            = var.vpc_id
  subnet_id         = var.subnet_id
  availability_zone = var.availability_zone
}

# Create security group for RDS instance
resource "aws_security_group" "rds_sg" {
  name        = "rds-sg"
  description = "Security group for RDS instance"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

output "rds_instance_id" {
  value = aws_db_instance.rds_instance.id
}
```
This Terraform program defines a set of AWS resources, including:

* An IAM role for the RDS instance with necessary permissions
* An IAM policy for the RDS instance
* An RDS instance created from the specified database snapshot
* A security group for the RDS instance

Note that you should replace the placeholders (e.g., `YOUR_ACCESS_KEY`, `snap-12345678`) with your actual AWS credentials and database snapshot ID.

