This Terraform program will create a basic AWS RDS instance with gp3 storage type. It will define an AWS RDS instance with a specified instance class, storage size, and database engine. The program will also define an AWS IAM role for the RDS instance and configure the AWS provider to use a valid AWS region.

**Terraform HCL Program:**
```hcl
provider "aws" {
  region = "us-west-2" # Replace with your preferred region
}

variable "rds_instance_class" {
  type = string
  default = "db.t3.micro"
}

variable "rds_storage_size" {
  type = number
  default = 20
}

variable "rds_database_engine" {
  type = string
  default = "mysql"
}

resource "aws_db_instance" "rds_instance" {
  identifier = "rds-instance"
  instance_class = var.rds_instance_class
  storage_type = "gp3"
  allocated_storage = var.rds_storage_size
  engine = var.rds_database_engine
  engine_version = "5.7.22"
  username = "admin"
  password = "password123"
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
}

resource "aws_security_group" "rds_sg" {
  name        = "rds-sg"
  description = "RDS security group"
  vpc_id      = aws_vpc.default.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_vpc" "default" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_iam_role" "rds_role" {
  name        = "rds-role"
  description = "RDS IAM role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_attach" {
  role       = aws_iam_role.rds_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSPublicAccess"
}
```
This program defines an AWS RDS instance with the specified instance class, storage size, and database engine. It also defines an AWS IAM role for the RDS instance and attaches the Amazon RDSPublicAccess policy to it. The program uses the `gp3` storage type and specifies a `username` and `password` for the RDS instance.

Note: You should replace the `region` variable with your preferred AWS region. Also, make sure to update the `rds_instance_class`, `rds_storage_size`, and `rds_database_engine` variables as needed for your specific use case.

