Here's a Terraform HCL program to create a basic AWS RDS instance with io1 storage type:

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create a VPC to host the RDS instance
resource "aws_vpc" "rds_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "RDS VPC"
  }
}

# Create a Subnet to host the RDS instance
resource "aws_subnet" "rds_subnet" {
  cidr_block = "10.0.1.0/24"
  vpc_id     = aws_vpc.rds_vpc.id
  availability_zone = "us-west-2a"
  tags = {
    Name = "RDS Subnet"
  }
}

# Create an RDS instance with io1 storage type
resource "aws_db_instance" "rds_instance" {
  allocated_storage      = 20
  engine                 = "mysql"
  instance_class         = "db.t2.micro"
  username               = "admin"
  password               = "password"
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  db_subnet_group_name  = aws_db_subnet_group.rds_subnet_group.name
  storage_type           = "io1"
  iops                   = 1000
  skip_final_snapshot    = true
  tags = {
    Name = "RDS Instance"
  }
}

# Create a Security Group for the RDS instance
resource "aws_security_group" "rds_sg" {
  name        = "RDS SG"
  description = "Allow inbound traffic on RDS port"
  vpc_id      = aws_vpc.rds_vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a DB Subnet Group for the RDS instance
resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "RDS Subnet Group"
  description = "RDS Subnet Group"
  subnet_ids = [aws_subnet.rds_subnet.id]
}

# Define a variable for the RDS username and password
variable "rds_username" {
  default = "admin"
}

variable "rds_password" {
  default = "password"
}
```

This Terraform configuration creates the following resources:

1. An AWS VPC to host the RDS instance
2. An AWS Subnet to host the RDS instance
3. An AWS RDS instance with io1 storage type and a high IOPS setting (1000)
4. An AWS Security Group to allow inbound traffic on RDS port (3306)
5. An AWS DB Subnet Group for the RDS instance

Note: Make sure to replace the `rds_password` variable with a secure password. The password is currently set to "password" for demonstration purposes only.

