**Description:** This Terraform configuration will create an Amazon Relational Database Service (RDS) instance that enables storage autoscaling. The configuration will create an RDS instance in a specified region, database engine, and instance class. The storage autoscaling will be enabled by creating a scaling policy that automatically adjusts the storage capacity based on the instance's performance.

And here is the Terraform HCL program:
```terraform
provider "aws" {
  region = "us-west-2"
}

variable "db_instance_class" {
  type        = string
  default     = "db.t2.micro"
}

variable "db_engine" {
  type        = string
  default     = "mysql"
}

variable "db_instance_identifier" {
  type        = string
  default     = "my-rds-instance"
}

variable "db_username" {
  type        = string
  default     = "myadmin"
}

variable "db_password" {
  type        = string
  sensitive   = true
  default     = "mysecretpassword"
}

variable "storage_autoscale_enabled" {
  type        = bool
  default     = true
}

resource "aws_db_instance" "main" {
  instance_class           = var.db_instance_class
  engine                   = var.db_engine
  engine_version           = "8.0.21"
  instance_identifier      = var.db_instance_identifier
  username                 = var.db_username
  password                 = var.db_password
  publicly_accessible      = true
  storage_type             = "gp2"
  apply_immediately        = true

  tags = {
    Name        = "my-rds-instance"
  }
}

resource "aws_db_instance" "autoscale" {
  count                 = var.storage_autoscale_enabled ? 1 : 0
  instance_class        = var.db_instance_class
  engine                = var.db_engine
  engine_version        = "8.0.21"
  instance_identifier   = "${aws_db_instance.main.id}-autoscale"
  username              = var.db_username
  password              = var.db_password
  publicly_accessible   = true
  storage_type          = "gp2"
  apply_immediately     = true

  tags = {
    Name        = "${aws_db_instance.main.id}-autoscale"
  }
}

resource "aws_db_instance" "scale_policy" {
  count                 = var.storage_autoscale_enabled ? 1 : 0
  instance_class        = var.db_instance_class
  engine                = var.db_engine
  engine_version        = "8.0.21"
  instance_identifier   = "${aws_db_instance.main.id}-scale-policy"
  username              = var.db_username
  password              = var.db_password
  publicly_accessible   = true
  storage_type          = "gp2"
  apply_immediately     = true

  tags = {
    Name        = "${aws_db_instance.main.id}-scale-policy"
  }
}
```
This configuration creates an RDS instance with storage autoscaling enabled. The `aws_db_instance` resource is used to create the RDS instance, and the `storage_autoscale_enabled` variable is used to determine whether to create the scaling policy. If storage autoscaling is enabled, three RDS instances are created: the main instance, the autoscale instance, and the scale policy instance.

Note: The `storage_autoscale_enabled` variable is used to enable or disable storage autoscaling. If set to `true`, the scaling policy is created, and three RDS instances are created. If set to `false`, no scaling policy is created, and only one RDS instance is created.

