**Terraform Program Description**

This Terraform program will create an AWS RDS database instance with a default Amazon Key Management Service (KMS) key for encrypting the database storage. The database instance will store its master password in the Secrets Manager. The program will also create the required IAM roles and policies to allow the database instance to use the Secrets Manager.

**Terraform HCL Program**
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create a default KMS key for the database
resource "aws_kms_key" "default" {
  description             = "Default KMS key for RDS database"
  deletion_window_in_days = 10
  is_enabled               = true
}

# Create a Secrets Manager secret to store the database master password
resource "aws_secretsmanager_secret" "rds_master_password" {
  name = "rds-master-password"
}

# Create an IAM role for the database instance to use Secrets Manager
resource "aws_iam_role" "rds_instance_role" {
  name        = "rds-instance-role"
  description = "Role for RDS instance to access Secrets Manager"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the database instance to access Secrets Manager
resource "aws_iam_policy" "rds_instance_policy" {
  name        = "rds-instance-policy"
  description = "Policy for RDS instance to access Secrets Manager"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "secretsmanager:GetSecretValue"
        Effect = "Allow"
        Resource = aws_secretsmanager_secret.rds_master_password.arn
      }
    ]
  })
}

# Attach the IAM policy to the database instance role
resource "aws_iam_role_policy_attachment" "rds_instance_policy_attach" {
  role       = aws_iam_role.rds_instance_role.name
  policy_arn = aws_iam_policy.rds_instance_policy.arn
}

# Create the RDS database instance
resource "aws_db_instance" "example" {
  name                = "example-db"
  instance_class      = "db.t2.micro"
  engine              = "mysql"
  engine_version      = "5.7.25"
  username            = "admin"
  password            = aws_secretsmanager_secret.rds_master_password.arn
  iam_instance_profile = aws_iam_role.rds_instance_role.name
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]
  parameter_group_name = "default.ysql5.7"

  # Store the database master password in Secrets Manager
  secret_name = aws_secretsmanager_secret.rds_master_password.name
  secret_string = "master_password"
}

# Create a security group for the database instance
resource "aws_security_group" "rds_security_group" {
  name        = "rds-security-group"
  description = "Security group for RDS instance"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```
This Terraform program creates the following resources:

* A default KMS key for encrypting the database storage
* A Secrets Manager secret to store the database master password
* An IAM role for the database instance to use Secrets Manager
* An IAM policy for the database instance to access Secrets Manager
* A security group for the database instance
* The RDS database instance with the default KMS key and Secrets Manager secret

Note that this program assumes you have the necessary AWS credentials and region set up in your Terraform configuration. You can modify the program to suit your specific needs.

