  name        = "vpc-role"
  description = "Role for VPC to access internet"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the VPC to access the internet
resource "aws_iam_policy" "vpc_policy" {
  name        = "vpc-policy"
  description = "Policy for VPC to access internet"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "ec2:*
        Resource = "*"
        Effect = "Allow"
      }
    ]
  })
}

