**Terraform Program Description:**
This Terraform configuration will create a VPC in AWS with multiple public subnets and associate them with a route table configured for internet access via an internet gateway. The VPC will be created in the `us-west-2` region. This configuration will also create the necessary security groups and network ACLs to enable internet access for the subnets.

**Terraform HCL Program:**
```terraform
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Create a new VPC
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true
}

# Create public subnets
resource "aws_subnet" "public_subnets" {
  count = 3
  cidr_block = "10.0.${count.index}.0/24"
  vpc_id     = aws_vpc.example.id
  availability_zone = "us-west-2a${count.index}"
  map_public_ip_on_launch = true
}

# Create a route table for internet access
resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.example.id
}

# Associate public subnets with the route table
resource "aws_route_table_association" "public_subnets_association" {
  count = 3
  subnet_id      = aws_subnet.public_subnets[count.index].id
  route_table_id = aws_route_table.public_route_table.id
}

# Create an internet gateway
resource "aws_internet_gateway" "example" {
  vpc_id = aws_vpc.example.id
}

# Associate the internet gateway with the route table
resource "aws_route" "example" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.example.id
}

# Output the VPC ID and CIDR block
output "vpc_id" {
  value = aws_vpc.example.id
}

output "vpc_cidr_block" {
  value = aws_vpc.example.cidr_block
}
