  tags = {
    Name = "peer"
  }
}

resource "aws_vpc" "base" {
  cidr_block = var.vpc_cidr_base
  tags = {
    Name = "base"
  }
}

resource "aws_vpc_peering_connection" "pike" {
  name               = "pike"
  vpc_id             = aws_vpc.peer.id
  peer_vpc_id        = aws_vpc.base.id
  peer_owner_id      = aws_vpc.peer.owner_id
  auto_accept        = true
  tags = {
    Name        = "pike"
    permissions = "read-only"
  }
}

